export interface PolicyAnalysis {
  id: string;
  filename: string;
  uploadDate: string;
  type: string;
  rating: 'Good' | 'Needs Improvement' | 'Poor' | 'Unable to Analyze';
  score: number; // 0 to 10
  summary: string;
  coverageAnalysis: string;
  premiumVsValue: string;
  exclusions: string;
  deductibles: string;
  strengths: string[];
  redFlags: string[];
  recommendations: string[];
}

export interface AdminStats {
  totalPolicies: number;
  reviewed: number;
  goodPolicies: number;
  needsReview: number;
}

import { GoogleGenAI, Type } from "@google/genai";
import { PolicyAnalysis } from "../types";

const MODEL_NAME = 'gemini-3-flash-preview';

export const analyzePolicy = async (file: File): Promise<PolicyAnalysis> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  // Convert File to base64
  const base64Data = await new Promise<string>((resolve) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = (reader.result as string).split(',')[1];
      resolve(base64String);
    };
    reader.readAsDataURL(file);
  });

  const prompt = `You are a world-class insurance policy auditor at "The Insurance Boss". 
  Analyze the provided PDF insurance policy and provide a detailed review.
  Evaluate the coverage, premiums (if listed), exclusions, and deductibles.
  Be honest and direct about whether it is a "Good" policy or if the customer is being underserved.

  Return the analysis in a strictly formatted JSON object matching the requested schema.`;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: {
        parts: [
          { inlineData: { data: base64Data, mimeType: file.type || 'application/pdf' } },
          { text: prompt }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            type: { type: Type.STRING, description: "Type of insurance (e.g. Business, Health, Auto)" },
            rating: { type: Type.STRING, enum: ["Good", "Needs Improvement", "Poor"] },
            score: { type: Type.NUMBER, description: "Score out of 10" },
            summary: { type: Type.STRING, description: "High-level overview of the policy findings" },
            coverageAnalysis: { type: Type.STRING, description: "Detailed look at what is covered" },
            premiumVsValue: { type: Type.STRING, description: "Is the price fair for what they get?" },
            exclusions: { type: Type.STRING, description: "Notable exclusions and limitations" },
            deductibles: { type: Type.STRING, description: "Assessment of deductibles" },
            strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
            redFlags: { type: Type.ARRAY, items: { type: Type.STRING } },
            recommendations: { type: Type.ARRAY, items: { type: Type.STRING } },
          },
          required: ["type", "rating", "score", "summary", "coverageAnalysis", "strengths", "redFlags", "recommendations"]
        }
      }
    });

    const result = JSON.parse(response.text);

    return {
      id: Math.random().toString(36).substr(2, 9),
      filename: file.name,
      uploadDate: new Date().toLocaleString(),
      ...result
    };
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    throw new Error("Failed to analyze policy. Please ensure the file is a valid PDF and try again.");
  }
};

export const simulateEmailNotification = async (analysis: PolicyAnalysis) => {
