import React, { useState, useRef } from 'react';
import { analyzePolicy, simulateEmailNotification } from '../services/geminiService';
import { PolicyAnalysis } from '../types';

interface UploadSectionProps {
  onAnalysisComplete: (analysis: PolicyAnalysis) => void;
}

const UploadSection: React.FC<UploadSectionProps> = ({ onAnalysisComplete }) => {
  const [isUploading, setIsUploading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [uploadProgress, setUploadProgress] = useState(0);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.type !== 'application/pdf') {
      setError("Please upload a PDF file.");
      return;
    }

    setIsUploading(true);
    setError(null);
    setUploadProgress(10);

    try {
      // Step progress bar for visual feedback
      const interval = setInterval(() => {
        setUploadProgress(prev => (prev < 90 ? prev + 5 : prev));
      }, 500);

      const analysis = await analyzePolicy(file);
      clearInterval(interval);
      setUploadProgress(100);

      // Send notification
      await simulateEmailNotification(analysis);

      // Delay slightly for UX
      setTimeout(() => {
        onAnalysisComplete(analysis);
        setIsUploading(false);
      }, 500);

    } catch (err: any) {
      setError(err.message || "An error occurred during analysis.");
      setIsUploading(false);
    }
  };

  const triggerUpload = () => {
    fileInputRef.current?.click();
  };

  return (
    <div className="flex flex-col items-center justify-center text-center py-16 space-y-12 gradient-bg rounded-[3rem]">
      <div className="space-y-4 max-w-2xl px-4">
        <h2 className="text-5xl md:text-7xl font-extrabold tracking-tight leading-tight">
          Is Your Policy <span className="text-yellow-400">Protecting</span> You?
        </h2>
        <p className="text-gray-400 text-lg md:text-xl font-medium leading-relaxed">
          Upload your insurance policy and get an instant AI-powered analysis. Find coverage gaps, hidden exclusions, and get expert recommendations.
        </p>
      </div>

      <div className="w-full max-w-2xl px-6">
        <div 
          onClick={isUploading ? undefined : triggerUpload}
          className={`relative border-2 border-dashed rounded-[2rem] p-16 transition-all cursor-pointer group
            ${isUploading ? 'bg-white/5 border-white/10' : 'bg-[#1a1a1a]/50 border-white/10 hover:border-yellow-400 hover:bg-[#1a1a1a]'}
          `}
        >
          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileChange} 
            accept="application/pdf" 
            className="hidden" 
          />

          {isUploading ? (
            <div className="flex flex-col items-center space-y-6">
              <div className="relative w-20 h-20">
                <svg className="w-full h-full animate-spin text-yellow-400" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
              </div>
              <div>
                <h3 className="text-xl font-bold">Analyzing Your Policy...</h3>
                <p className="text-gray-400 mt-2">Our AI is scanning every page for risks and gaps</p>
              </div>
              <div className="w-full bg-white/5 rounded-full h-2 mt-4 max-w-xs overflow-hidden">
                <div 
                  className="bg-yellow-400 h-full transition-all duration-300" 
                  style={{ width: `${uploadProgress}%` }}
                ></div>
              </div>
            </div>
          ) : (
            <div className="flex flex-col items-center space-y-4">
              <div className="bg-yellow-400/10 p-5 rounded-3xl group-hover:bg-yellow-400/20 transition-colors">
                <svg className="w-10 h-10 text-yellow-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" />
                </svg>
              </div>
              <div className="space-y-2">
                <h3 className="text-2xl font-bold">Upload Your Insurance Policy</h3>
                <p className="text-gray-400">Drag & drop a PDF file or click to browse</p>
              </div>
              <div className="inline-flex items-center px-4 py-2 rounded-full bg-white/5 text-[10px] font-bold text-gray-500 uppercase tracking-widest border border-white/5">
                PDF files only • No size limit
              </div>
            </div>
          )}
        </div>

        {error && (
          <div className="mt-4 p-4 rounded-xl bg-red-500/10 border border-red-500/20 text-red-400 text-sm font-medium">
            {error}
          </div>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-8 w-full max-w-4xl px-4 pt-8">
        {[
          { icon: 'shield-check', title: 'Coverage Analysis', desc: 'Evaluate if your coverage meets your needs' },
          { icon: 'trending-up', title: 'Value Assessment', desc: 'Compare premium costs vs actual protection' },
          { icon: 'exclamation-circle', title: 'Red Flag Detection', desc: 'Identify exclusions and limitations' }
        ].map((feat, idx) => (
          <div key={idx} className="flex flex-col items-center space-y-4 text-center">
            <div className="bg-[#1a1a1a] p-4 rounded-xl border border-white/5 text-yellow-400">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                {feat.icon === 'shield-check' && <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" />}
                {feat.icon === 'trending-up' && <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" />}
                {feat.icon === 'exclamation-circle' && <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />}
              </svg>
            </div>
            <div>
              <h4 className="font-bold text-lg">{feat.title}</h4>
              <p className="text-gray-500 text-sm mt-1">{feat.desc}</p>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default UploadSection;

import React from 'react';
import { PolicyAnalysis } from '../types';

interface AnalysisResultProps {
  analysis: PolicyAnalysis;
  onReset: () => void;
}

const AnalysisResult: React.FC<AnalysisResultProps> = ({ analysis, onReset }) => {
  const scoreColor = analysis.score >= 7 ? 'text-green-400' : analysis.score >= 4 ? 'text-yellow-400' : 'text-red-400';
  const ratingBg = analysis.rating === 'Good' ? 'bg-green-500/20 text-green-400' : analysis.rating === 'Needs Improvement' ? 'bg-yellow-500/20 text-yellow-400' : 'bg-red-500/20 text-red-400';

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <h2 className="text-4xl font-extrabold tracking-tight">Policy Analysis Complete</h2>
          <p className="text-gray-400 font-medium mt-1">{analysis.filename}</p>
        </div>
        <button 
          onClick={onReset}
          className="px-6 py-2.5 bg-white/5 hover:bg-white/10 text-white rounded-xl border border-white/10 font-medium transition-colors"
        >
          Analyze Another Policy
        </button>
      </div>

      <div className="bg-[#1a1a1a] rounded-3xl p-8 border border-white/5 flex flex-col md:flex-row items-center gap-10">
        <div className="relative w-40 h-40 flex-shrink-0">
          <svg className="w-full h-full -rotate-90 transform" viewBox="0 0 100 100">
            <circle cx="50" cy="50" r="45" fill="transparent" stroke="currentColor" strokeWidth="8" className="text-white/5" />
            <circle 
              cx="50" cy="50" r="45" fill="transparent" stroke="currentColor" strokeWidth="8" 
              strokeDasharray={283} 
              strokeDashoffset={283 - (283 * analysis.score) / 10} 
              className={scoreColor}
              strokeLinecap="round"
            />
          </svg>
          <div className="absolute inset-0 flex flex-col items-center justify-center">
            <span className={`text-4xl font-bold ${scoreColor}`}>{analysis.score}</span>
            <span className="text-xs text-gray-500 font-bold uppercase tracking-widest">/10</span>
          </div>
        </div>

        <div className="flex-1 space-y-4">
          <div className="flex flex-wrap gap-2">
            <span className={`px-3 py-1 rounded-lg text-xs font-bold uppercase tracking-wider ${ratingBg}`}>
              {analysis.rating}
            </span>
            <span className="px-3 py-1 rounded-lg text-xs font-bold uppercase tracking-wider bg-white/5 text-gray-400 border border-white/5">
              {analysis.type}
            </span>
            {analysis.score >= 8 && (
              <span className="px-3 py-1 rounded-lg text-xs font-bold uppercase tracking-wider bg-yellow-400/10 text-yellow-400 border border-yellow-400/10">
                Recommended
              </span>
            )}
          </div>
          <p className="text-lg text-gray-300 leading-relaxed font-medium">
            {analysis.summary}
          </p>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <Card icon="shield" title="Coverage Analysis" content={analysis.coverageAnalysis} />
        <Card icon="trending-up" title="Premium vs Value" content={analysis.premiumVsValue} />
        <Card icon="alert-triangle" title="Exclusions & Limitations" content={analysis.exclusions} color="orange" />
        <Card icon="file-text" title="Deductibles Assessment" content={analysis.deductibles} color="blue" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <ListCard title="Strengths" items={analysis.strengths} type="strength" />
        <ListCard title="Red Flags" items={analysis.redFlags} type="danger" />
        <ListCard title="Recommendations" items={analysis.recommendations} type="warning" />
      </div>

      <div className="bg-yellow-400/5 border border-yellow-400/10 rounded-3xl p-12 text-center space-y-6">
        <h3 className="text-3xl font-bold">Need Expert Guidance?</h3>
        <p className="text-gray-400 text-lg max-w-xl mx-auto">
          Let The Insurance Boss help you find the perfect coverage. Get a customized evaluation of your specific needs today.
        </p>
        <button className="bg-yellow-400 text-black px-8 py-3.5 rounded-2xl font-bold text-lg hover:bg-yellow-500 transition-all hover:scale-105 flex items-center gap-2 mx-auto">
          Get Free Consultation
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 5l7 7m0 0l-7 7m7-7H3" />
          </svg>
        </button>
      </div>
    </div>
  );
};

