import React, { useState, useRef } from 'react';
import { analyzePolicy, simulateEmailNotification } from '../services/geminiService';
import { PolicyAnalysis } from '../types';

interface UploadSectionProps {
  onAnalysisComplete: (analysis: PolicyAnalysis) => void;
}

const UploadSection: React.FC<UploadSectionProps> = ({ onAnalysisComplete }) => {
  const [isUploading, setIsUploading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [uploadProgress, setUploadProgress] = useState(0);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.type !== 'application/pdf') {
      setError("Please upload a PDF file.");
      return;
    }

    setIsUploading(true);
    setError(null);
    setUploadProgress(10);

    try {
      const interval = setInterval(() => {
        setUploadProgress(prev => (prev < 90 ? prev + 5 : prev));
      }, 500);

      const analysis = await analyzePolicy(file);
      clearInterval(interval);
      setUploadProgress(100);

      await simulateEmailNotification(analysis);

      setTimeout(() => {
        onAnalysisComplete(analysis);
        setIsUploading(false);
      }, 500);

    } catch (err: any) {
      setError(err.message || "An error occurred during analysis.");
      setIsUploading(false);
    }
  };

  const triggerUpload = () => {
    fileInputRef.current?.click();
  };

  return (
    <div className="flex flex-col items-center justify-center text-center py-12 md:py-24 space-y-16 gradient-bg rounded-[4rem] border border-white/5 bg-[#050505]">
      <div className="flex flex-col items-center space-y-8 max-w-3xl px-6">
        <div className="relative group">
          <div className="absolute inset-0 bg-yellow-400 rounded-full blur-2xl opacity-10 group-hover:opacity-30 transition-opacity"></div>
          <div className="relative w-32 h-32 md:w-56 md:h-56 rounded-full border-4 border-yellow-400 p-1 bg-black shadow-2xl group-hover:scale-105 transition-transform duration-500">
            <img 
              src="logo.png" 
              alt="The Insurance Boss" 
              className="w-full h-full object-contain rounded-full"
              onError={(e) => {
                e.currentTarget.src = 'https://api.iconify.design/mdi:account-tie-hat.svg?color=%23facc15';
              }}
            />
          </div>
        </div>

        <div className="space-y-4">
          <h2 className="text-6xl md:text-[10rem] font-black tracking-[-0.05em] leading-[0.8] uppercase italic text-white">
            THE BOSS <br/> <span className="text-yellow-400">IS IN.</span>
          </h2>
          <p className="text-gray-400 text-xl md:text-3xl font-medium leading-tight max-w-xl mx-auto uppercase tracking-tighter opacity-80 italic">
            Hand over your policy. <br/> Stop getting played by the firms.
          </p>
        </div>
      </div>

      <div className="w-full max-w-2xl px-6">
        <div 
          onClick={isUploading ? undefined : triggerUpload}
          className={`relative border-4 border-dashed rounded-[3rem] p-12 md:p-24 transition-all cursor-pointer group
            ${isUploading ? 'bg-white/5 border-white/10' : 'bg-[#0f0f0f] border-white/10 hover:border-yellow-400 hover:shadow-[0_0_80px_rgba(250,204,21,0.1)]'}
          `}
        >
          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileChange} 
            accept="application/pdf" 
            className="hidden" 
          />

          {isUploading ? (
            <div className="flex flex-col items-center space-y-8">
              <div className="relative w-24 h-24">
                <svg className="w-full h-full animate-spin text-yellow-400" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-10" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-90" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
              </div>
              <div>
                <h3 className="text-4xl font-black uppercase italic tracking-tighter text-white">Analyzing...</h3>
                <p className="text-yellow-400/60 mt-2 font-black uppercase text-xs tracking-[0.4em]">Exposing loopholes instantly</p>
              </div>
              <div className="w-full bg-white/5 rounded-full h-4 mt-4 max-w-xs overflow-hidden border border-white/5">
                <div 
                  className="bg-yellow-400 h-full transition-all duration-300" 
                  style={{ width: `${uploadProgress}%` }}
                ></div>
              </div>
            </div>
          ) : (
            <div className="flex flex-col items-center space-y-8">
              <div className="bg-yellow-400 p-8 rounded-[3rem] shadow-2xl shadow-yellow-400/20 group-hover:scale-110 transition-transform duration-500">
                <svg className="w-16 h-16 text-black" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" />
                </svg>
              </div>
              <div className="space-y-4">
                <h3 className="text-4xl md:text-5xl font-black uppercase italic tracking-tighter text-white">Drop the Evidence</h3>
                <p className="text-gray-500 font-bold uppercase text-sm tracking-[0.2em]">PDF Analysis • 100% Confidential</p>
              </div>
            </div>
          )}
        </div>

        {error && (
          <div className="mt-8 p-6 rounded-2xl bg-red-500 text-white font-black uppercase tracking-[0.2em] text-xs italic shadow-2xl shadow-red-500/20 text-center">
            ACCESS DENIED: {error}
