          { icon: 'trending-up', title: 'Leverage Audit', desc: 'Is your premium a fair trade for the risk?' },
          { icon: 'exclamation-circle', title: 'Zero Loopholes', desc: 'We scan for the fine print that strips your rights.' }
        ].map((feat, idx) => (
