import { GoogleGenAI, Type } from "@google/genai";
import { PolicyAnalysis } from "../types";

const MODEL_NAME = 'gemini-3-flash-preview';

export const analyzePolicy = async (file: File): Promise<PolicyAnalysis> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  // Convert File to base64
  const base64Data = await new Promise<string>((resolve) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = (reader.result as string).split(',')[1];
      resolve(base64String);
    };
    reader.readAsDataURL(file);
  });

  const prompt = `You are a world-class insurance policy auditor at "The Insurance Boss". 
  Analyze the provided PDF insurance policy and provide a detailed review.
  Evaluate the coverage, premiums (if listed), exclusions, and deductibles.
  Be honest and direct about whether it is a "Good" policy or if the customer is being underserved.

  Return the analysis in a strictly formatted JSON object matching the requested schema.`;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: {
        parts: [
          { inlineData: { data: base64Data, mimeType: file.type || 'application/pdf' } },
          { text: prompt }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            type: { type: Type.STRING, description: "Type of insurance (e.g. Business, Health, Auto)" },
            rating: { type: Type.STRING, enum: ["Good", "Needs Improvement", "Poor"] },
            score: { type: Type.NUMBER, description: "Score out of 10" },
            summary: { type: Type.STRING, description: "High-level overview of the policy findings" },
            coverageAnalysis: { type: Type.STRING, description: "Detailed look at what is covered" },
            premiumVsValue: { type: Type.STRING, description: "Is the price fair for what they get?" },
            exclusions: { type: Type.STRING, description: "Notable exclusions and limitations" },
            deductibles: { type: Type.STRING, description: "Assessment of deductibles" },
            strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
            redFlags: { type: Type.ARRAY, items: { type: Type.STRING } },
            recommendations: { type: Type.ARRAY, items: { type: Type.STRING } },
          },
          required: ["type", "rating", "score", "summary", "coverageAnalysis", "strengths", "redFlags", "recommendations"]
        }
      }
    });

    const result = JSON.parse(response.text);

    return {
      id: Math.random().toString(36).substr(2, 9),
      filename: file.name,
      uploadDate: new Date().toLocaleString(),
      ...result
    };
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    throw new Error("Failed to analyze policy. Please ensure the file is a valid PDF and try again.");
  }
};

/**
 * Sends a real email notification to bossofinsurance@gmail.com
 * NOTE: Check your email (including spam) for an activation email from FormSubmit!
 * You MUST click that link to start receiving these notifications.
 */
export const sendEmailNotification = async (analysis: PolicyAnalysis) => {
  const EMAIL = "bossofinsurance@gmail.com";
  const endpoint = `https://formsubmit.co/ajax/${EMAIL}`;

  const payload = {
    _subject: `BOSS ALERT: New Policy Review (${analysis.score}/10) - ${analysis.filename}`,
    _honey: "", // Honeypot to prevent spam
    _captcha: "false",
    _template: "table",
    filename: analysis.filename,
    policy_type: analysis.type,
    rating: analysis.rating,
    score: analysis.score,
    summary: analysis.summary,
    top_strengths: analysis.strengths.slice(0, 3).join(", "),
    red_flags: analysis.redFlags.slice(0, 3).join(", "),
    time: new Date().toLocaleString()
  };

  try {
    const response = await fetch(endpoint, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Accept": "application/json"
      },
      body: JSON.stringify(payload)
    });

    const data = await response.json();

    if (data.success === "true") {
      console.log("SUCCESS: Notification signal sent to FormSubmit for " + EMAIL);
      return true;
    } else {
      console.error("FormSubmit API returned an error:", data.message);
      return false;
    }
  } catch (error) {
    console.error("Network Error sending email notification:", error);
    return false;
  }
};

import React, { useState, useRef } from 'react';
import { analyzePolicy, sendEmailNotification } from '../services/geminiService';
import { PolicyAnalysis } from '../types';

interface UploadSectionProps {
  onAnalysisComplete: (analysis: PolicyAnalysis) => void;
}

const UploadSection: React.FC<UploadSectionProps> = ({ onAnalysisComplete }) => {
  const [isUploading, setIsUploading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [statusMessage, setStatusMessage] = useState<string>('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.type !== 'application/pdf') {
      setError("Please upload a PDF file.");
      return;
    }

    setIsUploading(true);
    setError(null);
    setUploadProgress(10);
    setStatusMessage('Scanning document structure...');

    try {
      const interval = setInterval(() => {
        setUploadProgress(prev => {
          if (prev < 40) return prev + 2;
          if (prev < 80) return prev + 1;
          return prev;
        });
      }, 300);

      // 1. Perform AI Analysis
      const analysis = await analyzePolicy(file);
      clearInterval(interval);
      setUploadProgress(85);
      setStatusMessage('Alerting The Boss...');

      // 2. Send Real Email Notification
      const success = await sendEmailNotification(analysis);

      if (!success) {
        console.warn("Notification might have failed or needs activation.");
      }

      setUploadProgress(100);
      setStatusMessage('Analysis Ready');

      // 3. Complete process
      setTimeout(() => {
        onAnalysisComplete(analysis);
        setIsUploading(false);
      }, 800);

    } catch (err: any) {
      setError(err.message || "An error occurred during analysis.");
      setIsUploading(false);
    }
  };

  const triggerUpload = () => {
    fileInputRef.current?.click();
  };

  return (
    <div className="flex flex-col items-center justify-center text-center py-16 space-y-12 gradient-bg rounded-[3rem]">
      <div className="space-y-4 max-w-2xl px-4">
        <h2 className="text-5xl md:text-7xl font-extrabold tracking-tight leading-tight text-white">
          Is Your Policy <span className="text-yellow-400">Protecting</span> You?
