  formData.append('summary', analysis.summary);
  formData.append('strengths', analysis.strengths.slice(0, 3).join(", "));
  formData.append('red_flags', analysis.redFlags.slice(0, 3).join(", "));
  formData.append('_template', 'table');
  formData.append('_captcha', 'false');

  try {
    const response = await fetch(endpoint, {
      method: "POST",
      body: formData,
      headers: {
        'Accept': 'application/json'
      }
    });

    const data = await response.json();

    if (data.success === "true") {
      console.log("SUCCESS: Notification signal sent to " + EMAIL);
      return true;
    } else {
      console.warn("FormSubmit Notice:", data.message);
      // If we get the "browsed as HTML files" error, it means FormSubmit doesn't trust the Origin.
      // We still return true to allow the user to see their result, but log the issue.
      return false;
    }
  } catch (error) {
    console.error("Network Error sending email notification:", error);
    return false;
  }
};

