import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route } from 'react-router-dom';
import Header from './components/Header';
import UploadSection from './components/UploadSection';
import AnalysisResult from './components/AnalysisResult';
import AdminDashboard from './components/AdminDashboard';
import AdminLogin from './components/AdminLogin';
import { PolicyAnalysis } from './types';

const App: React.FC = () => {
  const [isAdmin, setIsAdmin] = useState(false);
  const [allPolicies, setAllPolicies] = useState<PolicyAnalysis[]>([]);
  const [currentAnalysis, setCurrentAnalysis] = useState<PolicyAnalysis | null>(null);

  useEffect(() => {
    const saved = localStorage.getItem('insurance_boss_policies');
    if (saved) {
      setAllPolicies(JSON.parse(saved));
    }
  }, []);

  const savePolicies = (policies: PolicyAnalysis[]) => {
    setAllPolicies(policies);
    localStorage.setItem('insurance_boss_policies', JSON.stringify(policies));
  };

  const handleNewAnalysis = (analysis: PolicyAnalysis) => {
    const updated = [analysis, ...allPolicies];
    savePolicies(updated);
    setCurrentAnalysis(analysis);
  };

  const handleDeletePolicy = (id: string) => {
    const updated = allPolicies.filter(p => p.id !== id);
    savePolicies(updated);
  };

  return (
    <HashRouter>
      <div className="min-h-screen bg-transparent text-white boss-gradient selection:bg-yellow-500/30">
        <Header isAdmin={isAdmin} setIsAdmin={setIsAdmin} />

        <main className="container mx-auto px-4 py-8 max-w-6xl">
          <Routes>
            <Route path="/" element={
              currentAnalysis ? (
                <AnalysisResult 
                  analysis={currentAnalysis} 
                  onReset={() => setCurrentAnalysis(null)} 
                />
              ) : (
                <UploadSection onAnalysisComplete={handleNewAnalysis} />
              )
            } />

            <Route path="/admin" element={
              isAdmin ? (
                <AdminDashboard 
                  policies={allPolicies} 
                  onDelete={handleDeletePolicy}
                  onView={(p) => setCurrentAnalysis(p)}
                />
              ) : (
                <AdminLogin onLogin={() => setIsAdmin(true)} />
              )
            } />
          </Routes>
        </main>

        <footer className="py-12 border-t border-white/5 text-center text-gray-500 text-sm bg-transparent">
          <p>© {new Date().getFullYear()} The Insurance Boss Policy Review Tool.</p>
          <div className="mt-4 flex justify-center gap-6">
            <a href="https://theinsuranceboss.com" className="hover:text-yellow-400 transition-colors">Website</a>
            <a href="#" className="hover:text-yellow-400 transition-colors">Privacy</a>
            <a href="#" className="hover:text-yellow-400 transition-colors">Terms</a>
          </div>
        </footer>
      </div>
    </HashRouter>
  );
};

export default App;

