    setIsUploading(true);
    setError(null);
    setUploadProgress(10);

    try {
      const interval = setInterval(() => {
        setUploadProgress(prev => (prev < 90 ? prev + 2 : prev));
      }, 200);

      const analysis = await analyzePolicy(file);
      clearInterval(interval);

      await sendEmailNotification(analysis);

      setUploadProgress(100);
      setTimeout(() => {
        onAnalysisComplete(analysis);
        setIsUploading(false);
      }, 500);

    } catch (err: any) {
      setError("Analysis error. Please try again.");
      setIsUploading(false);
    }
  };

  return (
    <div className="flex flex-col items-center justify-center text-center py-16 space-y-12 glass-card rounded-[3rem]">
      <div className="space-y-4 max-w-2xl px-4">
        <h2 className="text-5xl md:text-6xl font-extrabold tracking-tight text-white">
          Is Your Policy <span className="text-yellow-400">Protecting</span> You?
        </h2>
        <p className="text-gray-400 text-lg md:text-xl">
          Upload your insurance policy and get an instant AI-powered analysis.
        </p>
      </div>

      <div className="w-full max-w-2xl px-6">
        <div 
          onClick={() => !isUploading && fileInputRef.current?.click()}
          className={`relative border-2 border-dashed rounded-[2rem] p-16 transition-all cursor-pointer group
            ${isUploading ? 'bg-white/5 border-white/10' : 'bg-white/5 border-white/10 hover:border-yellow-400'}
          `}
        >
          <input type="file" ref={fileInputRef} onChange={handleFileChange} accept="application/pdf" className="hidden" />

          {isUploading ? (
            <div className="flex flex-col items-center space-y-6">
              <svg className="w-16 h-16 animate-spin text-yellow-400" fill="none" viewBox="0 0 24 24">
                <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
              </svg>
