import { GoogleGenAI, Type } from "@google/genai";
import { PolicyAnalysis } from "../types";

const MODEL_NAME = 'gemini-3-flash-preview';

export const analyzePolicy = async (file: File): Promise<PolicyAnalysis> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const base64Data = await new Promise<string>((resolve) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = (reader.result as string).split(',')[1];
      resolve(base64String);
    };
    reader.readAsDataURL(file);
  });

  const prompt = `You are "The Insurance Boss", a legendary insurance auditor known for brutal honesty and finding hidden details others miss. 

  TASK:
  Analyze the provided PDF insurance policy. You must find:
  1. Gaps in coverage where the customer is exposed.
  2. Hidden exclusions that could deny a claim.
  3. A value assessment (is the premium fair for the coverage?).
  4. Deductibles (are they too high?).

  OUTPUT REQUIREMENTS:
  - Provide an "Optimal" and high-quality review every time.
  - The "score" must be a number between 0.0 and 10.0 (e.g., 6.2, 8.5, 4.0). DO NOT use 0-100 scale.
  - The "rating" must be one of: "Good", "Needs Improvement", "Poor".
  - Ensure "recommendations" are actionable and specific to the policy type.

  Return the analysis in a strictly formatted JSON object matching the requested schema.`;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: {
        parts: [
          { inlineData: { data: base64Data, mimeType: file.type || 'application/pdf' } },
          { text: prompt }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            type: { type: Type.STRING },
            rating: { type: Type.STRING, enum: ["Good", "Needs Improvement", "Poor"] },
            score: { type: Type.NUMBER, description: "A precise score from 0.0 to 10.0" },
            summary: { type: Type.STRING },
            coverageAnalysis: { type: Type.STRING },
            premiumVsValue: { type: Type.STRING },
            exclusions: { type: Type.STRING },
            deductibles: { type: Type.STRING },
            strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
            redFlags: { type: Type.ARRAY, items: { type: Type.STRING } },
            recommendations: { type: Type.ARRAY, items: { type: Type.STRING } },
          },
          required: ["type", "rating", "score", "summary", "coverageAnalysis", "strengths", "redFlags", "recommendations"]
        }
      }
    });

    let result = JSON.parse(response.text);

    // Safety check: if AI returns a 0-100 score by mistake, convert it to 0-10
    if (result.score > 10) {
      result.score = result.score / 10;
    }

    return {
      id: Math.random().toString(36).substr(2, 9),
      filename: file.name,
      uploadDate: new Date().toLocaleString(),
      ...result
    };
  } catch (error) {
    console.error("Analysis error:", error);
    throw new Error("Analysis failed. Please ensure the PDF is readable.");
  }
};

export const sendEmailNotification = async (analysis: PolicyAnalysis) => {
  const EMAIL = "bossofinsurance@gmail.com";

  return new Promise<boolean>((resolve) => {
    try {
      const iframeName = `form_target_${Date.now()}`;
      const iframe = document.createElement('iframe');
      iframe.name = iframeName;
      iframe.style.display = 'none';
      document.body.appendChild(iframe);

      const form = document.createElement('form');
      form.action = `https://formsubmit.co/${EMAIL}`;
      form.method = 'POST';
      form.target = iframeName;

      const fields: Record<string, string> = {
        _subject: `BOSS ALERT: New Policy Review (${analysis.score.toFixed(1)}/10) - ${analysis.filename}`,
        _captcha: "false",
        _template: "table",
        filename: analysis.filename,
        policy_type: analysis.type,
        rating: analysis.rating,
        score: analysis.score.toFixed(1),
        summary: analysis.summary
      };

      for (const [key, value] of Object.entries(fields)) {
        const input = document.createElement('input');
        input.type = 'hidden';
        input.name = key;
        input.value = value;
        form.appendChild(input);
      }

      document.body.appendChild(form);
      form.submit();

      setTimeout(() => {
        if (document.body.contains(form)) document.body.removeChild(form);
        if (document.body.contains(iframe)) document.body.removeChild(iframe);
        resolve(true);
      }, 3000);
    } catch (error) {
      resolve(false);
    }
  });
};

