import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Navigate, useNavigate } from 'react-router-dom';
import Header from './components/Header';
import UploadSection from './components/UploadSection';
import AnalysisResult from './components/AnalysisResult';
import AdminDashboard from './components/AdminDashboard';
import AdminLogin from './components/AdminLogin';
import WizardForm from './components/WizardForm';
import { PolicyAnalysis, QuoteRequest } from './types';

// Wrapper component to use navigation within Header
const HeaderWrapper: React.FC<{ 
  isAdmin: boolean; 
  setIsAdmin: (v: boolean) => void; 
  setShowWizard: (v: boolean) => void;
  setCurrentAnalysis: (v: PolicyAnalysis | null) => void;
}> = ({ isAdmin, setIsAdmin, setShowWizard, setCurrentAnalysis }) => {
  const navigate = useNavigate();

  const handleOpenWizard = () => {
    setCurrentAnalysis(null);
    setShowWizard(true);
    navigate('/');
  };

  const handleGoHome = () => {
    setCurrentAnalysis(null);
    setShowWizard(false);
    navigate('/');
  };

  return (
    <Header 
      isAdmin={isAdmin} 
      setIsAdmin={setIsAdmin} 
      onOpenWizard={handleOpenWizard} 
      onGoHome={handleGoHome}
    />
  );
};

const App: React.FC = () => {
  const [isAdmin, setIsAdmin] = useState(false);
  const [allPolicies, setAllPolicies] = useState<PolicyAnalysis[]>([]);
  const [allLeads, setAllLeads] = useState<QuoteRequest[]>([]);
  const [currentAnalysis, setCurrentAnalysis] = useState<PolicyAnalysis | null>(null);
  const [showWizard, setShowWizard] = useState(false);

  useEffect(() => {
    const savedPolicies = localStorage.getItem('insurance_boss_policies');
    if (savedPolicies) setAllPolicies(JSON.parse(savedPolicies));

    const savedLeads = localStorage.getItem('insurance_boss_leads');
    if (savedLeads) setAllLeads(JSON.parse(savedLeads));
  }, []);

  const savePolicies = (policies: PolicyAnalysis[]) => {
    setAllPolicies(policies);
    localStorage.setItem('insurance_boss_policies', JSON.stringify(policies));
  };

  const saveLeads = (leads: QuoteRequest[]) => {
    setAllLeads(leads);
    localStorage.setItem('insurance_boss_leads', JSON.stringify(leads));
  };

  const handleNewAnalysis = (analysis: PolicyAnalysis) => {
    const updated = [analysis, ...allPolicies];
    savePolicies(updated);
    setCurrentAnalysis(analysis);
  };

  const handleNewLead = (lead: QuoteRequest) => {
    const updated = [lead, ...allLeads];
    saveLeads(updated);
  };

  const handleDeletePolicy = (id: string) => {
    const updated = allPolicies.filter(p => p.id !== id);
    savePolicies(updated);
  };

  const handleDeleteLead = (id: string) => {
    const updated = allLeads.filter(l => l.id !== id);
    saveLeads(updated);
  };

  const handleStatusChange = (id: string, status: QuoteRequest['status']) => {
    const updated = allLeads.map(l => l.id === id ? { ...l, status } : l);
    saveLeads(updated);
  };

  return (
    <HashRouter>
      <div className="min-h-screen bg-transparent text-white boss-gradient selection:bg-yellow-500/30">
        <HeaderWrapper 
          isAdmin={isAdmin} 
          setIsAdmin={setIsAdmin} 
          setShowWizard={setShowWizard}
          setCurrentAnalysis={setCurrentAnalysis}
        />

        <main className="container mx-auto px-4 py-8 max-w-6xl">
          <Routes>
            <Route path="/" element={
              showWizard ? (
                <WizardForm 
                  onSubmit={(lead) => {
                    handleNewLead(lead);
                  }} 
                  onCancel={() => setShowWizard(false)} 
                />
              ) : currentAnalysis ? (
                <AnalysisResult 
                  analysis={currentAnalysis} 
                  onReset={() => setCurrentAnalysis(null)} 
                  onOpenWizard={() => setShowWizard(true)}
                />
              ) : (
                <UploadSection onAnalysisComplete={handleNewAnalysis} />
              )
            } />

            <Route path="/quote" element={
              <div className="py-10">
