import { GoogleGenAI, Type } from "@google/genai";
import { PolicyAnalysis } from "../types";

const MODEL_NAME = 'gemini-3-flash-preview';

export const analyzePolicy = async (file: File): Promise<PolicyAnalysis> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const base64Data = await new Promise<string>((resolve) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = (reader.result as string).split(',')[1];
      resolve(base64String);
    };
    reader.readAsDataURL(file);
  });

  const prompt = `You are "The Insurance Boss", a legendary insurance auditor. 

  TASK:
  Analyze the provided PDF insurance policy. You must extract technical data and provide a professional audit.

  EXTRACT THE FOLLOWING DATA:
  1. Insured Name & Address.
  2. Policy Number & Dates (Effective/Expiration).
  3. Technical Coverage Limits (e.g., General Liability: $1,000,000, Property: $500,000, etc.).
  4. Gaps, Exclusions, and Value Assessment.

  OUTPUT REQUIREMENTS:
  - Provide an "Optimal" and high-quality review.
  - The "score" must be a number between 0.0 and 10.0.
  - Return exactly the requested JSON format.`;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: {
        parts: [
          { inlineData: { data: base64Data, mimeType: file.type || 'application/pdf' } },
          { text: prompt }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            type: { type: Type.STRING },
            rating: { type: Type.STRING, enum: ["Good", "Needs Improvement", "Poor"] },
            score: { type: Type.NUMBER },
            insuredName: { type: Type.STRING },
            insuredAddress: { type: Type.STRING },
            policyNumber: { type: Type.STRING },
            effectiveDate: { type: Type.STRING },
            expirationDate: { type: Type.STRING },
            coverageLimits: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  label: { type: Type.STRING },
                  limit: { type: Type.STRING }
                }
              }
            },
            summary: { type: Type.STRING },
            coverageAnalysis: { type: Type.STRING },
            premiumVsValue: { type: Type.STRING },
            exclusions: { type: Type.STRING },
            deductibles: { type: Type.STRING },
            strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
            redFlags: { type: Type.ARRAY, items: { type: Type.STRING } },
            recommendations: { type: Type.ARRAY, items: { type: Type.STRING } },
          },
          required: ["insuredName", "type", "rating", "score", "summary", "coverageLimits"]
        }
      }
    });

    let result = JSON.parse(response.text);

    if (result.score > 10) {
      result.score = result.score / 10;
    }

    return {
      id: Math.random().toString(36).substr(2, 9),
      filename: file.name,
      uploadDate: new Date().toLocaleString(),
      fileData: base64Data, // Save original file content
      ...result
    };
  } catch (error) {
    console.error("Analysis error:", error);
    throw new Error("Analysis failed. Please ensure the PDF is readable.");
  }
};

export const sendEmailNotification = async (analysis: PolicyAnalysis) => {
  const EMAIL = "bossofinsurance@gmail.com";

  return new Promise<boolean>((resolve) => {
    try {
      const iframeName = `form_target_${Date.now()}`;
      const iframe = document.createElement('iframe');
      iframe.name = iframeName;
      iframe.style.display = 'none';
      document.body.appendChild(iframe);

      const form = document.createElement('form');
      form.action = `https://formsubmit.co/${EMAIL}`;
      form.method = 'POST';
      form.target = iframeName;

      const fields: Record<string, string> = {
        _subject: `BOSS ALERT: ${analysis.insuredName} - (${analysis.score.toFixed(1)}/10)`,
        _captcha: "false",
        insured_name: analysis.insuredName,
        policy_number: analysis.policyNumber || 'N/A',
        rating: analysis.rating,
        score: analysis.score.toFixed(1),
        summary: analysis.summary
      };

      for (const [key, value] of Object.entries(fields)) {
        const input = document.createElement('input');
        input.type = 'hidden';
        input.name = key;
        input.value = value;
        form.appendChild(input);
      }

      document.body.appendChild(form);
      form.submit();

      setTimeout(() => {
        if (document.body.contains(form)) document.body.removeChild(form);
        if (document.body.contains(iframe)) document.body.removeChild(iframe);
        resolve(true);
      }, 3000);
    } catch (error) {
      resolve(false);
    }
  });
};

import { openDB, IDBPDatabase } from 'https://esm.sh/idb';

const DB_NAME = 'TheInsuranceBossDB';
const DB_VERSION = 1;
const STORE_POLICIES = 'policies';
const STORE_LEADS = 'leads';

let dbPromise: Promise<IDBPDatabase>;

const getDB = () => {
  if (!dbPromise) {
    dbPromise = openDB(DB_NAME, DB_VERSION, {
      upgrade(db) {
        if (!db.objectStoreNames.contains(STORE_POLICIES)) {
          db.createObjectStore(STORE_POLICIES, { keyPath: 'id' });
        }
        if (!db.objectStoreNames.contains(STORE_LEADS)) {
          db.createObjectStore(STORE_LEADS, { keyPath: 'id' });
        }
      },
    });
  }
  return dbPromise;
};

export const storage = {
  async savePolicy(policy: any) {
    const db = await getDB();
    await db.put(STORE_POLICIES, policy);
  },
  async getPolicies() {
    const db = await getDB();
    return db.getAll(STORE_POLICIES);
  },
  async deletePolicy(id: string) {
    const db = await getDB();
    await db.delete(STORE_POLICIES, id);
  },
  async saveLead(lead: any) {
    const db = await getDB();
    await db.put(STORE_LEADS, lead);
  },
  async getLeads() {
    const db = await getDB();
    return db.getAll(STORE_LEADS);
  },
  async deleteLead(id: string) {
    const db = await getDB();
    await db.delete(STORE_LEADS, id);
  },
  async clearAll() {
    const db = await getDB();
    await db.clear(STORE_POLICIES);
    await db.clear(STORE_LEADS);
  },
  async exportBackup() {
    const policies = await this.getPolicies();
    const leads = await this.getLeads();
    return JSON.stringify({ policies, leads, version: DB_VERSION, timestamp: new Date().toISOString() });
  },
  async importBackup(jsonString: string) {
    const data = JSON.parse(jsonString);
    const db = await getDB();
    const tx = db.transaction([STORE_POLICIES, STORE_LEADS], 'readwrite');
    for (const p of (data.policies || [])) await tx.objectStore(STORE_POLICIES).put(p);
    for (const l of (data.leads || [])) await tx.objectStore(STORE_LEADS).put(l);
    await tx.done;
  }
};

import React, { useState, useEffect } from 'react';
