import { GoogleGenAI, Type } from "@google/genai";
import { PolicyAnalysis } from "../types";

const MODEL_NAME = 'gemini-3-flash-preview';

export const analyzePolicy = async (file: File): Promise<PolicyAnalysis> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const base64Data = await new Promise<string>((resolve) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = (reader.result as string).split(',')[1];
      resolve(base64String);
    };
    reader.readAsDataURL(file);
  });

  const prompt = `You are "The Insurance Boss", a legendary insurance auditor with deep expertise in identifying hidden traps in commercial policies.

  TASK:
  Analyze the provided PDF insurance policy. You must extract technical data and perform a high-stakes Industry-Specific Exclusion Audit.

  1. IDENTIFY THE BUSINESS: Based on the "Insured Name" and operations mentioned, determine the primary industry (Construction, Real Estate, Manufacturing, Tech, etc.).
  2. EXCLUSION AUDIT: Perform a critical review of the exclusions. 
     - If Construction: Check specifically for "Action Over", "Injury to Subcontractors", "Residential/Multi-family" or "EFIS" exclusions.
     - If Real Estate: Check for "Assault & Battery", "Hired/Non-Owned Auto", or "Communicable Disease" exclusions.
     - If Professional: Check for "Professional Liability Gap" or "Cyber Liability" exclusions.
  3. EVALUATE RISK: Explain WHY these specific exclusions are dangerous for the specific work this business does.

  OUTPUT REQUIREMENTS:
  - Return exactly the requested JSON format.
  - The "score" must be a number between 0.0 and 10.0.
  - The "industryExclusionAudit" field must be a detailed assessment of these specific risks.`;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: {
        parts: [
          { inlineData: { data: base64Data, mimeType: file.type || 'application/pdf' } },
          { text: prompt }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            type: { type: Type.STRING },
            rating: { type: Type.STRING, enum: ["Good", "Needs Improvement", "Poor"] },
            score: { type: Type.NUMBER },
            insuredName: { type: Type.STRING },
            insuredAddress: { type: Type.STRING },
            policyNumber: { type: Type.STRING },
