              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  label: { type: Type.STRING },
                  limit: { type: Type.STRING }
                }
              }
            },
            summary: { type: Type.STRING },
            coverageAnalysis: { type: Type.STRING },
            premiumVsValue: { type: Type.STRING },
            exclusions: { type: Type.STRING },
            industryExclusionAudit: { type: Type.STRING, description: 'Critical audit of exclusions vs industry-specific risks.' },
            deductibles: { type: Type.STRING },
            strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
            redFlags: { type: Type.ARRAY, items: { type: Type.STRING } },
            recommendations: { type: Type.ARRAY, items: { type: Type.STRING } },
          },
          required: ["insuredName", "type", "rating", "score", "summary", "coverageLimits", "industryExclusionAudit"]
        }
      }
    });

    let result = JSON.parse(response.text);

    if (result.score > 10) {
      result.score = result.score / 10;
    }

    return {
      id: Math.random().toString(36).substr(2, 9),
      filename: file.name,
      uploadDate: new Date().toLocaleString(),
      fileData: base64Data, // Save original file content
      ...result
    };
  } catch (error) {
    console.error("Analysis error:", error);
    throw new Error("Analysis failed. Please ensure the PDF is readable.");
  }
};

