const UploadSection: React.FC<UploadSectionProps> = ({ onAnalysisComplete, existingPolicies }) => {
  const [isUploading, setIsUploading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [statusText, setStatusText] = useState("Analyzing Policy...");
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || file.type !== 'application/pdf') {
      setError("Please upload a PDF file.");
      return;
    }

    setIsUploading(true);
    setError(null);
    setUploadProgress(10);
    setStatusText("Reading File...");

    try {
      // 1. Get base64 to calculate hash locally first
      const base64Data = await new Promise<string>((resolve) => {
        const reader = new FileReader();
        reader.onloadend = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(file);
      });

      const fileHash = await calculateFileHash(base64Data);

      // 2. Check if we already have this exact policy in our vault
      const existingMatch = existingPolicies.find(p => p.fileHash === fileHash);

      if (existingMatch) {
        setStatusText("Retrieved from Vault!");
        setUploadProgress(100);
        setTimeout(() => {
          onAnalysisComplete(existingMatch);
          setIsUploading(false);
        }, 800);
        return;
      }

      // 3. New policy, proceed with AI analysis
      setStatusText("Boss AI Analysis...");
      const interval = setInterval(() => {
        setUploadProgress(prev => (prev < 90 ? prev + 2 : prev));
      }, 300);

      const analysis = await analyzePolicy(file);
      clearInterval(interval);

      setStatusText("Sending Notification...");
      await sendEmailNotification(analysis);

      setUploadProgress(100);
      setStatusText("Audit Complete!");
      setTimeout(() => {
        onAnalysisComplete(analysis);
        setIsUploading(false);
      }, 800);

    } catch (err: any) {
      console.error(err);
      setError("Analysis error. Please try again.");
      setIsUploading(false);
    }
  };

  return (
    <div className="flex flex-col items-center justify-center text-center py-16 space-y-12 glass-card rounded-[3rem] animate-in fade-in duration-700">
