import React, { useState, useRef } from 'react';
import { analyzePolicy, sendEmailNotification, calculateFileHash } from '../services/geminiService';
import { PolicyAnalysis } from '../types';

interface UploadSectionProps {
  onAnalysisComplete: (analysis: PolicyAnalysis) => void;
  existingPolicies: PolicyAnalysis[];
}

const UploadSection: React.FC<UploadSectionProps> = ({ onAnalysisComplete, existingPolicies }) => {
  const [isUploading, setIsUploading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [statusText, setStatusText] = useState("Analyzing Policy...");
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || file.type !== 'application/pdf') {
      setError("Please upload a PDF file.");
      return;
    }

    setIsUploading(true);
    setError(null);
    setUploadProgress(10);
    setStatusText("Reading File...");

    let interval: any = null;

    try {
      // 1. Get base64 to calculate hash locally first
      const base64Data = await new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onloadend = () => resolve((reader.result as string).split(',')[1]);
        reader.onerror = () => reject(new Error("Failed to read file"));
        reader.readAsDataURL(file);
      });

      setStatusText("Securing Vault Access...");
      const fileHash = await calculateFileHash(base64Data);

      // 2. Check vault
      const existingMatch = existingPolicies.find(p => p.fileHash === fileHash);

      if (existingMatch) {
        setStatusText("Retrieved from Vault!");
        setUploadProgress(100);
        setTimeout(() => {
          onAnalysisComplete(existingMatch);
          setIsUploading(false);
        }, 500);
        return;
      }

      // 3. New policy AI analysis
      setStatusText("Boss AI Analysis...");
      interval = setInterval(() => {
        setUploadProgress(prev => {
          if (prev < 40) return prev + 5;
          if (prev < 85) return prev + 1;
          return prev;
        });
      }, 500);

      const analysis = await analyzePolicy(file);

      // Stop the slow tick and bump progress
      if (interval) clearInterval(interval);
      setUploadProgress(90);

      setStatusText("Finalizing Report...");
      await sendEmailNotification(analysis);

      setUploadProgress(100);
      setStatusText("Audit Complete!");

      setTimeout(() => {
        onAnalysisComplete(analysis);
      }, 500);

    } catch (err: any) {
      console.error("Upload process error:", err);
      setError(err.message || "An unexpected error occurred during analysis.");
      setIsUploading(false);
    } finally {
      if (interval) clearInterval(interval);
      // We don't set isUploading to false here immediately if it's successful, 
      // because onAnalysisComplete transitions the view.
    }
  };

  return (
    <div className="flex flex-col items-center justify-center text-center py-16 space-y-12 glass-card rounded-[3rem] animate-in fade-in duration-700">
      <div className="space-y-4 max-w-2xl px-4">
