          Is Your Policy <span className="text-yellow-400">Protecting</span> You?
        </h2>
        <p className="text-gray-400 text-lg md:text-xl">
          Upload your insurance policy and get an instant, consistent, AI-powered analysis.
        </p>
      </div>

      <div className="w-full max-w-2xl px-6">
        <div 
          onClick={() => !isUploading && fileInputRef.current?.click()}
          className={`relative border-2 border-dashed rounded-[2rem] p-16 transition-all cursor-pointer group overflow-hidden
            ${isUploading ? 'bg-white/5 border-white/10 shadow-inner' : 'bg-white/5 border-white/10 hover:border-yellow-400 hover:bg-yellow-400/[0.02]'}
          `}
        >
          <input type="file" ref={fileInputRef} onChange={handleFileChange} accept="application/pdf" className="hidden" />

          {isUploading ? (
            <div className="flex flex-col items-center space-y-6">
              <div className="relative">
                 <svg className="w-20 h-20 animate-spin text-yellow-400" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-10" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-90" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
                <div className="absolute inset-0 flex items-center justify-center text-[10px] font-black text-yellow-400 uppercase tracking-tighter">
                  {uploadProgress}%
                </div>
              </div>
              <div className="space-y-2">
                <h3 className="text-2xl font-black italic tracking-tighter uppercase text-white">{statusText}</h3>
                <p className="text-gray-500 text-sm font-medium">This may take up to 60 seconds for large files...</p>
              </div>
              <div className="w-48 h-1 bg-white/5 rounded-full overflow-hidden">
                <div className="h-full bg-yellow-400 transition-all duration-500" style={{ width: `${uploadProgress}%` }} />
              </div>
            </div>
          ) : (
            <div className="flex flex-col items-center space-y-4">
              <div className="bg-yellow-400/10 p-6 rounded-3xl text-yellow-400 group-hover:scale-110 transition-transform duration-500">
                <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" />
                </svg>
              </div>
              <h3 className="text-2xl font-bold group-hover:text-yellow-400 transition-colors">Click to Upload Policy</h3>
              <p className="text-gray-500 font-medium">Deterministic & Private Vault Storage</p>
            </div>
          )}
        </div>
        {error && (
          <div className="mt-6 p-6 bg-red-500/10 border border-red-500/20 rounded-2xl text-red-400 text-sm animate-in fade-in slide-in-from-top-2">
            <div className="flex items-center gap-3 justify-center">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"/></svg>
              <p className="font-bold uppercase tracking-tight">{error}</p>
            </div>
            <button 
              onClick={() => setError(null)}
              className="mt-4 text-[10px] font-black uppercase tracking-widest text-red-400/60 hover:text-red-400 underline"
            >
              Dismiss
            </button>
          </div>
        )}
      </div>

      <div className="flex items-center gap-8 opacity-40">
        <div className="flex items-center gap-2">
          <svg className="w-4 h-4 text-green-400" fill="currentColor" viewBox="0 0 24 24"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg>
          <span className="text-[10px] font-black uppercase tracking-widest">Encrypted Vault</span>
        </div>
        <div className="flex items-center gap-2">
           <svg className="w-4 h-4 text-blue-400" fill="currentColor" viewBox="0 0 24 24"><path d="M12 1L3 5v6c0 5.55 3.84 10.74 9 12 5.16-1.26 9-6.45 9-12V5l-9-4z"/></svg>
           <span className="text-[10px] font-black uppercase tracking-widest">Boss Verified</span>
        </div>
      </div>
