import { GoogleGenAI, Type } from "@google/genai";
import { PolicyAnalysis } from "../types";

// Insurance policy analysis is a complex reasoning task; using gemini-3-pro-preview for best results.
const MODEL_NAME = 'gemini-3-pro-preview';

/**
 * Calculates a unique hash for the file content.
 * Includes a fallback for non-secure (HTTP) environments where crypto.subtle is unavailable.
 */
export const calculateFileHash = async (base64: string): Promise<string> => {
  try {
    if (window.isSecureContext && crypto.subtle) {
      const msgUint8 = new TextEncoder().encode(base64);
      const hashBuffer = await crypto.subtle.digest('SHA-256', msgUint8);
      const hashArray = Array.from(new Uint8Array(hashBuffer));
      return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
    }
  } catch (e) {
    console.warn("Secure crypto failed, falling back to basic hash", e);
  }

  // Fallback simple hash for non-secure contexts
  let hash = 0;
  for (let i = 0; i < base64.length; i++) {
    const char = base64.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash; // Convert to 32bit integer
  }
  return 'fallback-' + Math.abs(hash).toString(16);
};

/**
 * Analyzes the policy using Gemini AI.
 * Increased timeout to 300s and disabled thinking to prevent the "timed out" error for large/complex PDFs.
 */
export const analyzePolicy = async (file: File): Promise<PolicyAnalysis> => {
  // Always use the required initialization format with process.env.API_KEY.
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const base64Data = await new Promise<string>((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = (reader.result as string).split(',')[1];
      resolve(base64String);
    };
    reader.onerror = () => reject(new Error("Failed to read the file."));
    reader.readAsDataURL(file);
  });

  const fileHash = await calculateFileHash(base64Data);

  const prompt = `You are "The Insurance Boss", a legendary insurance auditor with deep expertise in identifying hidden traps in commercial policies.

  TASK:
  Analyze the provided PDF insurance policy. You must perform a deep-dive "Exclusion Review".

  1. DETECT EXCLUSIONS: Search the policy for specific exclusion clauses. List the actual titles or brief descriptions of the exclusions you find (e.g., "Total Pollution Exclusion", "Assault & Battery Exclusion", "Action Over Exclusion").
  2. INDUSTRY AUDIT: Perform a critical review of these exclusions relative to the business's industry.
     - Construction: Look for "Action Over", "Injury to Subcontractors", "Residential/Multi-family", "EFIS", or "Prior Work".
     - Real Estate: Look for "Assault & Battery", "Hired/Non-Owned Auto", "Lead Paint", or "Mold".
     - Professional: Look for "Cyber Breach", "Breach of Contract", or "Known Circumstances".
  3. BOSS CRITIQUE: Explain WHY these specific detected exclusions are dangerous or standard.

  SCORING RUBRIC (BE STRICT):
  - 9.0 - 10.0: EXCEPTIONAL. No dangerous industry-specific exclusions found.
  - 7.0 - 8.9: GOOD. Only minor/standard exclusions for the industry.
  - 4.0 - 6.9: NEEDS IMPROVEMENT. Missing key protections or has non-critical industry-specific exclusions.
  - 0.0 - 3.9: POOR/DANGEROUS. Contains "Action Over", "Assault & Battery", or other catastrophic exclusions for this specific industry.

  OUTPUT REQUIREMENTS:
  - Return exactly the requested JSON format.
  - "foundExclusions" should be an array of strings representing the specific clauses detected.
  - "industryExclusionAudit" should be your professional review/critique of those exclusions.`;

  // Increased timeout to 300 seconds (5 minutes) for massive insurance documents
  const timeoutPromise = new Promise((_, reject) => 
    setTimeout(() => reject(new Error("AI Analysis timed out. Insurance policies can be very long; try uploading just the first 25 pages of the Dec and Exclusions if this continues.")), 300000)
  );

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: {
        parts: [
          { inlineData: { data: base64Data, mimeType: file.type || 'application/pdf' } },
          { text: prompt }
        ]
      },
      config: {
        seed: 42,
        temperature: 0,
        thinkingConfig: { thinkingBudget: 0 }, // Disable thinking to minimize latency/timeout risk
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            type: { type: Type.STRING },
            rating: { type: Type.STRING, enum: ["Good", "Needs Improvement", "Poor"] },
            score: { type: Type.NUMBER },
            insuredName: { type: Type.STRING },
            insuredAddress: { type: Type.STRING },
            policyNumber: { type: Type.STRING },
            effectiveDate: { type: Type.STRING },
            expirationDate: { type: Type.STRING },
            coverageLimits: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  label: { type: Type.STRING },
                  limit: { type: Type.STRING }
                }
              }
            },
            summary: { type: Type.STRING },
            coverageAnalysis: { type: Type.STRING },
            premiumVsValue: { type: Type.STRING },
            exclusions: { type: Type.STRING },
            foundExclusions: { type: Type.ARRAY, items: { type: Type.STRING } },
            industryExclusionAudit: { type: Type.STRING },
            deductibles: { type: Type.STRING },
            strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
            redFlags: { type: Type.ARRAY, items: { type: Type.STRING } },
            recommendations: { type: Type.ARRAY, items: { type: Type.STRING } },
          },
          required: ["insuredName", "type", "rating", "score", "summary", "foundExclusions", "industryExclusionAudit"]
        }
      }
    });

    // Access text property directly as per guidelines.
    let result = JSON.parse(response.text || '{}');

    if (result.score > 10) result.score = result.score / 10;
    if (result.score < 0) result.score = 0;

    return {
      id: Math.random().toString(36).substr(2, 9),
      filename: file.name,
      uploadDate: new Date().toLocaleString(),
      fileData: base64Data,
      fileHash: fileHash,
      ...result
    };
  } catch (error) {
    console.error("Analysis error:", error);
    if (error instanceof Error && error.message.includes("timed out")) {
      throw error;
    }
    throw new Error("Analysis failed. The PDF might be too large or complex for real-time processing.");
  }
};

export const sendEmailNotification = async (analysis: PolicyAnalysis) => {
  const EMAIL = "bossofinsurance@gmail.com";

  return new Promise<boolean>((resolve) => {
    try {
      const iframeName = `form_target_${Date.now()}`;
      const iframe = document.createElement('iframe');
      iframe.name = iframeName;
      iframe.style.display = 'none';
      document.body.appendChild(iframe);

      const form = document.createElement('form');
      form.action = `https://formsubmit.co/${EMAIL}`;
      form.method = 'POST';
      form.target = iframeName;

      const fields: Record<string, string> = {
        _subject: `BOSS ALERT: ${analysis.insuredName} - (${analysis.score.toFixed(1)}/10)`,
        _captcha: "false",
        insured_name: analysis.insuredName,
        policy_number: analysis.policyNumber || 'N/A',
        rating: analysis.rating,
        score: analysis.score.toFixed(1),
        summary: analysis.summary
      };

      for (const [key, value] of Object.entries(fields)) {
        const input = document.createElement('input');
        input.type = 'hidden';
        input.name = key;
        input.value = value;
        form.appendChild(input);
      }

      document.body.appendChild(form);
      form.submit();

      // Resolve quickly to not block UI
      setTimeout(() => {
        if (document.body.contains(form)) document.body.removeChild(form);
        if (document.body.contains(iframe)) document.body.removeChild(iframe);
        resolve(true);
      }, 1000);
    } catch (error) {
      console.warn("Notification error:", error);
      resolve(false);
    }
  });
};

import { GoogleGenAI, Type } from "@google/genai";
