import React, { useRef } from 'react';
import { PolicyAnalysis } from '../types';

interface AnalysisResultProps {
  analysis: PolicyAnalysis;
  onReset: () => void;
  onOpenWizard: () => void;
}

const AnalysisResult: React.FC<AnalysisResultProps> = ({ analysis, onReset, onOpenWizard }) => {
  const pdfTemplateRef = useRef<HTMLDivElement>(null);

  const scoreColor = analysis.score >= 7 ? '#facc15' : analysis.score >= 4 ? '#fbbf24' : '#f87171';
  const scoreRingColor = analysis.score >= 7 ? 'stroke-yellow-400' : analysis.score >= 4 ? 'stroke-orange-400' : 'stroke-red-400';

  const displayScore = analysis.score.toFixed(0);

  const handleDownloadPDF = async () => {
    if (!pdfTemplateRef.current) return;

    const html2pdf = (window as any).html2pdf;
    if (!html2pdf) {
      alert("Boss, the PDF engine is still warming up. Give it one more second.");
      return;
    }

    const opt = {
