import React, { useRef } from 'react';
import { PolicyAnalysis } from '../types';

interface AnalysisResultProps {
  analysis: PolicyAnalysis;
  onReset: () => void;
  onOpenWizard: () => void;
}

const AnalysisResult: React.FC<AnalysisResultProps> = ({ analysis, onReset, onOpenWizard }) => {
  const pdfTemplateRef = useRef<HTMLDivElement>(null);

  const scoreRingColor = analysis.score >= 7.5 ? 'stroke-green-400' : analysis.score >= 5 ? 'stroke-yellow-400' : 'stroke-red-500';
  const scoreTextColor = analysis.score >= 7.5 ? 'text-green-400' : analysis.score >= 5 ? 'text-yellow-400' : 'text-red-500';
  const displayScore = analysis.score.toFixed(1);

