    if (!pdfTemplateRef.current) return;
    const html2pdf = (window as any).html2pdf;
    if (!html2pdf) {
      alert("Boss, the PDF engine is still warming up.");
      return;
    }
    const opt = {
      margin: 0,
      filename: `TheInsuranceBoss_Audit_${analysis.insuredName.replace(/\s+/g, '_')}.pdf`,
      image: { type: 'jpeg', quality: 1.0 },
      html2canvas: { scale: 2.5, useCORS: true, letterRendering: true, scrollY: 0, windowWidth: 1280 },
      jsPDF: { unit: 'in', format: 'letter', orientation: 'landscape' }
    };
    try {
      await html2pdf().set(opt).from(pdfTemplateRef.current).save();
    } catch (error) {
      console.error("PDF Generation failed:", error);
    }
  };

  return (
    <div className="relative space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700 pb-24 max-w-7xl mx-auto px-4 lg:px-0">

