  onReset: () => void;
  onOpenWizard: () => void;
}

const AnalysisResult: React.FC<AnalysisResultProps> = ({ analysis, onReset, onOpenWizard }) => {
  const dashboardRef = useRef<HTMLDivElement>(null);

  const scoreColor = analysis.score >= 7.5 ? 'text-green-400' : analysis.score >= 5 ? 'text-yellow-400' : 'text-red-500';
  const displayScore = Math.round(analysis.score);

  const handleDownloadPDF = async () => {
    if (!dashboardRef.current) return;
    const html2pdf = (window as any).html2pdf;
    if (!html2pdf) {
      alert("Boss, the PDF engine is still warming up. Refresh or wait a second.");
      return;
    }

    const element = dashboardRef.current;

