interface AnalysisResultProps {
  analysis: PolicyAnalysis;
  onReset: () => void;
  onOpenWizard: () => void;
}

const AnalysisResult: React.FC<AnalysisResultProps> = ({ analysis, onReset, onOpenWizard }) => {
  const dashboardRef = useRef<HTMLDivElement>(null);

  const scoreColorClass = analysis.score >= 7.5 ? 'text-green-400' : analysis.score >= 5 ? 'text-yellow-400' : 'text-red-500';
  const scoreStrokeClass = analysis.score >= 7.5 ? 'stroke-green-400' : analysis.score >= 5 ? 'stroke-yellow-400' : 'stroke-red-500';
  const displayScore = Math.round(analysis.score);

  const handleDownloadPDF = async () => {
    if (!dashboardRef.current) return;
    const html2pdf = (window as any).html2pdf;
    if (!html2pdf) {
      alert("PDF engine loading. Please wait.");
      return;
    }

    const element = dashboardRef.current;
    const opt = {
      margin: 0.1,
      filename: `THE_INSURANCE_BOSS_AUDIT_${analysis.insuredName.toUpperCase().replace(/\s+/g, '_')}.pdf`,
      image: { type: 'jpeg', quality: 1.0 },
      html2canvas: { 
        scale: 2, 
        useCORS: true, 
        backgroundColor: '#000000',
        logging: false,
        letterRendering: true,
        windowWidth: 1200 
      },
      jsPDF: { unit: 'in', format: 'letter', orientation: 'landscape' }
    };

    try {
      const buttons = element.querySelector('.pdf-hide');
      if (buttons) (buttons as HTMLElement).style.display = 'none';
      window.scrollTo(0, 0);
      await html2pdf().set(opt).from(element).save();
      if (buttons) (buttons as HTMLElement).style.display = 'flex';
    } catch (error) {
      console.error("PDF Generation failed:", error);
    }
  };

  return (
    <div ref={dashboardRef} className="relative space-y-6 animate-in fade-in duration-700 pb-24 max-w-7xl mx-auto px-4 lg:px-8 bg-black">

