              cx="64"
              cy="64"
              r="58"
              stroke="currentColor"
              strokeWidth="10"
              fill="transparent"
              strokeDasharray={2 * Math.PI * 58}
              strokeDashoffset={2 * Math.PI * 58 * (1 - analysis.score / 10)}
              className={`${scoreStrokeClass} transition-all duration-1000 ease-out`}
              strokeLinecap="round"
            />
