          <div className="absolute inset-0 flex flex-col items-center justify-center">
            <span className={`text-4xl font-black italic ${scoreColorClass}`}>{displayScore}</span>
            <span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest -mt-1">/10</span>
          </div>
        </div>

        <div className="space-y-4 flex-1">
          <div className="flex flex-wrap gap-2">
            <Badge text={analysis.rating?.toUpperCase() || "GOOD"} color="green" />
            <Badge text="BUSINESS" color="gray" />
            <Badge text="RECOMMENDED" color="green" />
          </div>
          <p className="text-gray-300 text-lg md:text-xl font-medium leading-relaxed tracking-tight">
            {analysis.summary}
          </p>
        </div>
      </div>

      {/* ASSESSMENT GRID: 2x2 */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <AssessmentCard 
          title="Coverage Analysis" 
          icon={<ShieldIcon />} 
          content={analysis.coverageAnalysis} 
        />
        <AssessmentCard 
          title="Premium vs Value" 
          icon={<TrendIcon />} 
          content={analysis.premiumVsValue} 
