        />
        <AssessmentCard 
          title="Deductibles Assessment" 
          icon={<FileTextIcon />} 
          content={analysis.deductibles} 
        />
      </div>

      {/* FOOTER COLUMNS: Strengths, Red Flags, Recommendations */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Strengths */}
        <div className="bg-[#111111] border border-white/5 rounded-3xl p-8 space-y-6">
          <div className="flex items-center gap-3 text-green-400">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
            <h3 className="text-xl font-black italic uppercase tracking-tighter">Strengths</h3>
          </div>
          <ul className="space-y-4">
            {analysis.strengths.map((s, i) => (
              <li key={i} className="flex gap-3 items-start">
