          <ul className="space-y-4">
            {analysis.strengths.map((s, i) => (
              <li key={i} className="flex gap-3 items-start">
                <svg className="w-5 h-5 text-green-400/80 mt-0.5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M11.049 2.927c.3-.921 1.603-.921 1.902 0l1.519 4.674a1 1 0 00.95.69h4.915c.969 0 1.371 1.24.588 1.81l-3.976 2.888a1 1 0 00-.363 1.118l1.518 4.674c.3.922-.755 1.688-1.538 1.118l-3.976-2.888a1 1 0 00-1.176 0l-3.976 2.888c-.783.57-1.838-.197-1.538-1.118l1.518-4.674a1 1 0 00-.363-1.118l-3.976-2.888c-.784-.57-.382-1.81.588-1.81h4.914a1 1 0 00.951-.69l1.519-4.674z"/></svg>
                <p className="text-sm font-semibold text-gray-400 leading-snug">{s}</p>
              </li>
            ))}
          </ul>
        </div>

        {/* Red Flags */}
        <div className="bg-[#111111] border border-white/5 rounded-3xl p-8 space-y-6">
          <div className="flex items-center gap-3 text-red-500">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M10 14l2-2m0 0l2-2m-2 2l-2-2m2 2l2 2m7-2a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
            <h3 className="text-xl font-black italic uppercase tracking-tighter">Red Flags</h3>
          </div>
          <ul className="space-y-4">
            {analysis.redFlags.map((r, i) => (
              <li key={i} className="flex gap-3 items-start">
                <svg className="w-5 h-5 text-red-500 mt-0.5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"/></svg>
                <p className="text-sm font-semibold text-red-500/80 leading-snug">{r}</p>
              </li>
            ))}
          </ul>
        </div>

        {/* Recommendations */}
        <div className="bg-[#111111] border border-white/5 rounded-3xl p-8 space-y-6">
          <div className="flex items-center gap-3 text-yellow-400">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 5l7 7-7 7M5 5l7 7-7 7"/></svg>
            <h3 className="text-xl font-black italic uppercase tracking-tighter">Recommendations</h3>
          </div>
          <ul className="space-y-4">
            {analysis.recommendations.map((rec, i) => (
              <li key={i} className="flex gap-3 items-start">
                <div className="w-6 h-6 rounded-full bg-yellow-400 text-black flex items-center justify-center text-[10px] font-black flex-shrink-0 mt-0.5">
                  {i + 1}
                </div>
                <p className="text-sm font-semibold text-gray-300 leading-snug">{rec}</p>
              </li>
            ))}
          </ul>
        </div>
      </div>

      {/* ACTIONS */}
      <div className="pdf-hide pt-10 flex flex-col md:flex-row justify-between items-center gap-6">
        <button onClick={onReset} className="text-gray-500 hover:text-white font-bold text-sm uppercase tracking-widest transition-colors flex items-center gap-2">
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
          Back to Audit
        </button>
        <button onClick={handleDownloadPDF} className="bg-yellow-400 px-12 py-5 rounded-2xl text-black font-black text-sm uppercase tracking-widest hover:bg-yellow-500 transition-all shadow-[0_10px_30px_rgba(250,204,21,0.2)]">
          Export Boss Report
