        {icon}
        <h3 className="text-xl font-black italic uppercase tracking-tighter">{title}</h3>
      </div>
      <ul className="space-y-4 flex-1">
        {items.map((item, i) => (
          <li key={i} className="flex gap-4 items-start group">
            {isOrdered ? (
              <div className="w-6 h-6 rounded-lg bg-yellow-400 text-black flex items-center justify-center text-[10px] font-black flex-shrink-0 mt-0.5">
                {i + 1}
              </div>
            ) : (
              <div className={`mt-1 flex-shrink-0 ${colorStyles[color].split(' ')[0]}`}>
                <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" /></svg>
              </div>
            )}
            <p className="text-sm font-semibold text-gray-400 leading-snug group-hover:text-gray-200 transition-colors">{item}</p>
          </li>
        ))}
      </ul>
    </div>
  );
};

