import React, { useRef } from 'react';
import { PolicyAnalysis } from '../types';

interface AnalysisResultProps {
  analysis: PolicyAnalysis;
  onReset: () => void;
  onOpenWizard: () => void;
}

const AnalysisResult: React.FC<AnalysisResultProps> = ({ analysis, onReset, onOpenWizard }) => {
  const dashboardRef = useRef<HTMLDivElement>(null);

  const scoreColor = analysis.score >= 7.5 ? 'text-green-400' : analysis.score >= 5 ? 'text-yellow-400' : 'text-red-500';
  const scoreStroke = analysis.score >= 7.5 ? 'stroke-green-400' : analysis.score >= 5 ? 'stroke-yellow-400' : 'stroke-red-500';
  const displayScore = Math.round(analysis.score);

  const handleDownloadPDF = async () => {
    if (!dashboardRef.current) return;
    const html2pdf = (window as any).html2pdf;
    if (!html2pdf) {
      alert("Boss, the PDF engine is still warming up. Try again in a second.");
      return;
    }

    const element = dashboardRef.current;

    const opt = {
      margin: 0.1,
      filename: `BOSS_AUDIT_${analysis.insuredName.toUpperCase().replace(/\s+/g, '_')}.pdf`,
      image: { type: 'jpeg', quality: 1.0 },
      html2canvas: { 
        scale: 2, 
        useCORS: true, 
        backgroundColor: '#000000',
        letterRendering: true,
        windowWidth: 1400 
      },
      jsPDF: { unit: 'in', format: 'letter', orientation: 'landscape' }
    };

    try {
      const buttons = element.querySelector('.pdf-hide');
      if (buttons) (buttons as HTMLElement).style.display = 'none';
      window.scrollTo(0, 0);
      await html2pdf().set(opt).from(element).save();
      if (buttons) (buttons as HTMLElement).style.display = 'flex';
    } catch (error) {
      console.error("PDF Export failed:", error);
    }
  };

  const formatAuditText = (text: string) => {
    return text.split('\n').filter(line => line.trim().length > 0).map((line, i) => (
      <p key={i} className="mb-4 last:mb-0">
        {line.trim().startsWith('-') || line.trim().startsWith('*') 
          ? <span className="flex gap-2"><span className="text-yellow-400">•</span> {line.trim().substring(1).trim()}</span>
          : line.trim()
        }
      </p>
    ));
  };

  return (
    <div ref={dashboardRef} className="relative space-y-6 animate-in fade-in duration-1000 pb-24 max-w-7xl mx-auto px-4 lg:px-8 bg-black">

      {/* 1. TOP HEADER: SCORE + SNAPSHOT */}
      <div className="bg-[#111111] rounded-[2.5rem] p-8 border border-white/5 flex flex-col md:flex-row items-center gap-10">
        {/* SCORE CIRCLE */}
        <div className="relative w-40 h-40 flex-shrink-0 group">
          <svg className="w-full h-full transform -rotate-90 filter drop-shadow-[0_0_20px_rgba(250,204,21,0.15)]">
            <circle cx="80" cy="80" r="72" stroke="currentColor" strokeWidth="6" fill="transparent" className="text-white/5" />
            <circle
              cx="80"
              cy="80"
              r="72"
              stroke="currentColor"
              strokeWidth="12"
              fill="transparent"
              strokeDasharray={2 * Math.PI * 72}
              strokeDashoffset={2 * Math.PI * 72 * (1 - analysis.score / 10)}
              className={`${scoreStroke} transition-all duration-1000 ease-out`}
              strokeLinecap="round"
            />
          </svg>
          <div className="absolute inset-0 flex flex-col items-center justify-center">
            <span className={`text-6xl font-black italic tracking-tighter ${scoreColor}`}>
              {displayScore}
            </span>
            <span className="text-[12px] font-bold text-gray-500 uppercase tracking-widest -mt-1">/ 10</span>
          </div>
        </div>

        {/* SUMMARY & BADGES */}
        <div className="space-y-6 flex-1">
          <div className="flex flex-wrap gap-2">
            <Badge text={analysis.rating?.toUpperCase() || "GOOD"} color="green" />
            <Badge text={analysis.type?.toUpperCase() || "BUSINESS"} color="gray" />
            <Badge text="BOSS VERIFIED" color="yellow" />
          </div>
          <div className="space-y-2">
            <p className="text-gray-400 text-[10px] font-black uppercase tracking-widest">Executive Audit Summary</p>
            <p className="text-white text-xl md:text-2xl font-bold leading-snug italic tracking-tight">
              "{analysis.summary}"
            </p>
          </div>
          <div className="flex flex-wrap gap-8 border-t border-white/5 pt-4">
             <SnapshotInfo label="Insured" value={analysis.insuredName} />
             <SnapshotInfo label="Policy #" value={analysis.policyNumber || 'PENDING'} />
             <SnapshotInfo label="Term" value={`${analysis.effectiveDate || 'N/A'} - ${analysis.expirationDate || 'N/A'}`} />
          </div>
        </div>
      </div>

      {/* 2. CORE ASSESSMENT GRID */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <AssessmentCard title="Coverage Analysis" icon={<ShieldIcon />} content={analysis.coverageAnalysis} />
        <AssessmentCard title="Premium vs Value" icon={<TrendIcon />} content={analysis.premiumVsValue} />
        <AssessmentCard title="Found Deductibles" icon={<DocIcon />} content={analysis.deductibles} />

        {/* REFINED EXCLUSIONS & LIMITATIONS CARD */}
        <div className="p-8 bg-[#111111] rounded-[2rem] border border-white/5 space-y-6 hover:border-white/20 transition-all h-full group">
          <div className="flex items-center gap-3 text-red-500 group-hover:scale-[1.02] transition-transform">
            <div className="p-2 bg-red-500/5 rounded-lg border border-red-500/10">
              <WarningIcon />
            </div>
            <h3 className="text-lg font-black italic uppercase tracking-tighter text-white/90">Exclusions & Limitations</h3>
          </div>

          <div className="space-y-4">
            <p className="text-gray-400 text-sm leading-relaxed italic border-b border-white/5 pb-3">
              {analysis.exclusions}
            </p>
            <div className="space-y-3">
              <h4 className="text-[9px] font-black text-gray-500 uppercase tracking-widest">Identified Clauses:</h4>
              <div className="grid grid-cols-1 gap-2">
                {analysis.foundExclusions?.map((ex, i) => (
                  <div key={i} className="flex items-start gap-3 bg-white/[0.02] p-3 rounded-xl border border-white/5">
                    <div className="mt-0.5 flex-shrink-0">
                      <RedFlagIcon />
                    </div>
                    <span className="text-xs font-bold text-gray-300 leading-tight uppercase tracking-tight">{ex}</span>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* 3. INDUSTRY EXCLUSION DEPTH AUDIT */}
      <div className="bg-[#111111] rounded-[2.5rem] border border-white/5 overflow-hidden">
        <div className="bg-yellow-400/5 px-8 py-6 border-b border-white/5 flex items-center justify-between">
          <div className="flex items-center gap-3 text-yellow-400">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19.428 15.428a2 2 0 00-1.022-.547l-2.387-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z" /></svg>
            <h3 className="text-xl font-black italic uppercase tracking-tighter">Industry Exclusion Depth Audit</h3>
          </div>
          <span className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Proprietary AI Logic</span>
        </div>

        <div className="p-8 grid grid-cols-1 lg:grid-cols-12 gap-10">
          <div className="lg:col-span-8 space-y-6">
            <div className="space-y-4">
              <h4 className="text-[10px] font-black text-yellow-400/60 uppercase tracking-widest">Professional Industry Critique</h4>
              <div className="text-gray-300 text-lg leading-relaxed font-medium italic">
                {formatAuditText(analysis.industryExclusionAudit)}
              </div>
            </div>
          </div>

          <div className="lg:col-span-4 space-y-6">
            <div className="bg-black/40 rounded-3xl p-6 border border-white/10 space-y-4">
              <h4 className="text-[10px] font-black text-red-500/80 uppercase tracking-widest border-b border-white/5 pb-3">Detected Toxic Clauses</h4>
              <div className="space-y-3">
                {analysis.foundExclusions?.map((ex, i) => (
                  <div key={i} className="flex items-start gap-3 group">
                    <div className="w-1.5 h-1.5 rounded-full bg-red-500 mt-1.5 flex-shrink-0 group-hover:scale-150 transition-transform" />
                    <span className="text-xs font-bold text-gray-400 uppercase leading-tight tracking-tight group-hover:text-red-400 transition-colors">
                      {ex}
                    </span>
                  </div>
                ))}
              </div>
            </div>

            <div className="p-6 bg-green-500/5 rounded-3xl border border-green-500/10">
               <h4 className="text-[10px] font-black text-green-400/80 uppercase tracking-widest mb-2">Audit Verdict</h4>
               <p className="text-sm font-bold text-white italic">
                 {analysis.score >= 7 
                  ? "Standard industry limitations detected. Overall coverage posture is resilient." 
                  : "Caution recommended. High-impact exclusions detected that may compromise core operations."}
               </p>
            </div>
          </div>
        </div>
      </div>

      {/* 4. FOOTER TRIO */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <ColumnCard 
          title="Strengths" 
          color="green" 
          icon={<CheckCircleIcon />} 
          items={analysis.strengths} 
        />
        <ColumnCard 
          title="Red Flags" 
          color="red" 
          icon={<AlertCircleIcon />} 
          items={analysis.redFlags} 
        />
        <ColumnCard 
          title="Recommendations" 
          color="yellow" 
          icon={<ChevronRightIcon />} 
          items={analysis.recommendations} 
          isOrdered 
        />
      </div>

      {/* 5. ACTIONS SECTION */}
      <div className="pdf-hide pt-10 flex flex-col md:flex-row justify-between items-center gap-6 border-t border-white/5">
        <button 
          onClick={onReset} 
          className="text-gray-500 hover:text-white font-black text-sm uppercase tracking-[0.2em] transition-all flex items-center gap-2 group"
        >
          <svg className="w-4 h-4 group-hover:-translate-x-1 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
          New Audit
        </button>
        <div className="flex gap-4">
          <button 
            onClick={onOpenWizard} 
            className="px-8 py-5 rounded-2xl bg-white/5 border border-white/10 text-white font-black text-xs uppercase tracking-widest hover:bg-white/10 transition-all"
          >
            Consult Expert
          </button>
          <button 
            onClick={handleDownloadPDF} 
            className="bg-yellow-400 px-12 py-5 rounded-2xl text-black font-black text-sm uppercase tracking-widest hover:bg-yellow-500 transition-all shadow-[0_15px_30px_rgba(250,204,21,0.2)] active:scale-95"
          >
            Export PDF Report
          </button>
        </div>
      </div>
    </div>
  );
};

