          </div>
          <p className="text-gray-400 text-xl leading-relaxed font-medium">
            {analysis.coverageAnalysis}
          </p>
        </div>

        {/* Exclusions Card */}
        <div className="bg-[#0a0a0a] rounded-[2.5rem] p-12 border border-white/5 space-y-10 h-full">
          <h3 className="text-2xl font-black italic uppercase tracking-tighter text-red-500">Exclusions</h3>
          <ul className="space-y-5">
            {analysis.foundExclusions?.map((ex, i) => (
              <li key={i} className="flex items-start gap-4 group">
                <div className="flex-shrink-0 text-red-500 mt-1">
                  <XIcon />
                </div>
                <span className="text-gray-400 text-lg font-bold uppercase tracking-tight leading-snug group-hover:text-red-400 transition-colors">
                  {ex}
                </span>
              </li>
            ))}
