        </div>
      </div>

      {/* NEW: INDUSTRY EXCLUSION DEPTH AUDIT */}
      {analysis.industryExclusionAudit && (
        <div className="bg-[#0a0a0a] rounded-[2.5rem] p-12 border border-yellow-400/20 relative overflow-hidden">
