        <ColumnCard 
          title="Red Flags" 
          color="red" 
          icon={<XIcon />} 
          items={analysis.redFlags} 
        />
        <ColumnCard 
          title="Recommendations" 
          color="yellow" 
          icon={<ArrowIcon />} 
          items={analysis.recommendations} 
        />
