import React, { useRef } from 'react';
import { PolicyAnalysis } from '../types';

interface AnalysisResultProps {
  analysis: PolicyAnalysis;
  onReset: () => void;
  onOpenWizard: () => void;
}

const AnalysisResult: React.FC<AnalysisResultProps> = ({ analysis, onReset, onOpenWizard }) => {
  const dashboardRef = useRef<HTMLDivElement>(null);

  const handleDownloadPDF = async () => {
    if (!dashboardRef.current) return;
    const html2pdf = (window as any).html2pdf;
    if (!html2pdf) {
      alert("Boss, the PDF engine is still warming up. Try again in a second.");
      return;
    }

    const element = dashboardRef.current;
    const opt = {
      margin: [0.2, 0.2],
      filename: `BOSS_REPORT_${analysis.insuredName.toUpperCase().replace(/\s+/g, '_')}.pdf`,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { 
        scale: 2, 
        useCORS: true, 
        backgroundColor: '#000000',
        letterRendering: true,
        windowWidth: 1400 
      },
      jsPDF: { unit: 'in', format: 'letter', orientation: 'landscape' },
      pagebreak: { mode: ['avoid-all', 'css', 'legacy'] }
    };

    const hideElements = Array.from(element.querySelectorAll('.pdf-hide')) as HTMLElement[];
    try {
      hideElements.forEach(el => el.style.setProperty('display', 'none', 'important'));
      window.scrollTo(0, 0);
      await new Promise(resolve => setTimeout(resolve, 150));
      await html2pdf().set(opt).from(element).save();
    } catch (error) {
      console.error("PDF Export failed:", error);
    } finally {
      hideElements.forEach(el => el.style.removeProperty('display'));
    }
  };

  const getScoreColor = () => {
    if (analysis.score >= 8) return 'text-green-500';
    if (analysis.score >= 5) return 'text-yellow-400';
    return 'text-red-500';
  };

  const getScoreRingColor = () => {
    if (analysis.score >= 8) return 'stroke-green-500';
    if (analysis.score >= 5) return 'stroke-yellow-400';
    return 'stroke-red-500';
  };

  return (
    <div ref={dashboardRef} className="relative space-y-6 animate-in fade-in duration-1000 pb-24 max-w-7xl mx-auto px-4 bg-black text-white">

      {/* TOP HEADER: SCORE & SUMMARY */}
      <div className="bg-[#111111] rounded-[2rem] p-8 border border-white/5 flex flex-col md:flex-row items-center gap-10">
        {/* CIRCULAR SCORE */}
        <div className="relative w-36 h-36 flex-shrink-0">
          <svg className="w-full h-full transform -rotate-90">
            <circle cx="72" cy="72" r="64" stroke="currentColor" strokeWidth="6" fill="transparent" className="text-white/5" />
            <circle
              cx="72"
              cy="72"
              r="64"
              stroke="currentColor"
              strokeWidth="6"
              fill="transparent"
              strokeDasharray={2 * Math.PI * 64}
              strokeDashoffset={2 * Math.PI * 64 * (1 - analysis.score / 10)}
              className={`${getScoreRingColor()} transition-all duration-1000 ease-out`}
              strokeLinecap="round"
            />
          </svg>
          <div className="absolute inset-0 flex flex-col items-center justify-center">
            <span className={`text-5xl font-black italic tracking-tighter ${getScoreColor()}`}>
              {Math.round(analysis.score)}
            </span>
            <span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest -mt-1">/ 10</span>
          </div>
        </div>

        {/* BADGES & SUMMARY */}
        <div className="flex-1 space-y-4">
          <div className="flex flex-wrap gap-2">
            <Badge text={analysis.rating?.toUpperCase() || "GOOD"} color="green" />
            <Badge text={analysis.type?.toUpperCase() || "BUSINESS"} color="gray" />
            <Badge text="RECOMMENDED" color="green-dark" />
          </div>
          <p className="text-gray-300 text-xl font-medium leading-relaxed italic">
            {analysis.summary}
          </p>
        </div>
      </div>

      {/* 2X2 ASSESSMENT GRID */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <AssessmentCard 
          title="Coverage Analysis" 
          icon={<ShieldIcon />} 
          content={analysis.coverageAnalysis} 
        />
        <AssessmentCard 
          title="Premium vs Value" 
          icon={<TrendIcon />} 
          content={analysis.premiumVsValue} 
        />
        <AssessmentCard 
          title="Exclusions & Limitations" 
          icon={<ExclusionIcon />} 
          content={analysis.exclusions} 
          warning
        />
        <AssessmentCard 
          title="Deductibles Assessment" 
          icon={<FileTextIcon />} 
          content={analysis.deductibles} 
        />
      </div>

      {/* 3-COLUMN FOOTER: STRENGTHS, RED FLAGS, RECOMMENDATIONS */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* STRENGTHS */}
        <div className="bg-[#111111] rounded-[2rem] border border-white/5 p-8 space-y-8">
          <div className="flex items-center gap-3 text-green-500">
            <CheckCircleIcon />
            <h3 className="text-xl font-black italic uppercase tracking-tighter">Strengths</h3>
          </div>
          <ul className="space-y-4">
            {analysis.strengths.map((item, i) => (
              <li key={i} className="flex gap-4 items-start group">
                <StarIcon className="text-green-500 w-5 h-5 flex-shrink-0 mt-0.5" />
                <p className="text-sm font-semibold text-gray-400 group-hover:text-white transition-colors leading-relaxed">{item}</p>
              </li>
            ))}
          </ul>
        </div>

        {/* RED FLAGS */}
        <div className="bg-[#111111] rounded-[2rem] border border-white/5 p-8 space-y-8">
          <div className="flex items-center gap-3 text-red-500">
            <AlertCircleIcon />
            <h3 className="text-xl font-black italic uppercase tracking-tighter">Red Flags</h3>
          </div>
          <ul className="space-y-4">
            {analysis.redFlags.map((item, i) => (
              <li key={i} className="flex gap-4 items-start group">
                <WarningTriangleIcon className="text-red-500 w-5 h-5 flex-shrink-0 mt-0.5" />
                <p className="text-sm font-semibold text-red-500/80 group-hover:text-red-400 transition-colors leading-relaxed">{item}</p>
              </li>
            ))}
          </ul>
        </div>

        {/* RECOMMENDATIONS */}
        <div className="bg-[#111111] rounded-[2rem] border border-white/5 p-8 space-y-8">
          <div className="flex items-center gap-3 text-yellow-400">
            <ArrowRightIcon />
            <h3 className="text-xl font-black italic uppercase tracking-tighter">Recommendations</h3>
          </div>
          <ul className="space-y-5">
            {analysis.recommendations.map((item, i) => (
              <li key={i} className="flex gap-4 items-start group">
                <div className="w-6 h-6 rounded-full bg-yellow-400/20 text-yellow-400 flex items-center justify-center text-[10px] font-black flex-shrink-0 mt-0.5 border border-yellow-400/30">
                  {i + 1}
                </div>
                <p className="text-sm font-semibold text-gray-400 group-hover:text-white transition-colors leading-relaxed">{item}</p>
              </li>
            ))}
          </ul>
        </div>
      </div>

      {/* ACTION BAR */}
      <div className="pdf-hide pt-10 flex flex-col md:flex-row justify-between items-center gap-6 border-t border-white/5">
        <button 
          onClick={onReset} 
          className="text-gray-500 hover:text-white font-black text-sm uppercase tracking-[0.2em] transition-all flex items-center gap-2 group"
        >
          <svg className="w-4 h-4 group-hover:-translate-x-1 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
          New Audit
        </button>
        <div className="flex gap-4">
          <button 
            onClick={onOpenWizard} 
            className="px-8 py-4 rounded-2xl bg-white/5 border border-white/10 text-white font-black text-xs uppercase tracking-widest hover:bg-white/10 transition-all"
          >
            Consult Expert
          </button>
          <button 
            onClick={handleDownloadPDF} 
            className="bg-yellow-400 px-10 py-4 rounded-2xl text-black font-black text-sm uppercase tracking-widest hover:bg-yellow-500 transition-all shadow-[0_15px_30px_rgba(250,204,21,0.2)] active:scale-95"
          >
            Export PDF
          </button>
        </div>
      </div>
    </div>
  );
};

// HELPERS
const Badge: React.FC<{ text: string; color: 'green' | 'gray' | 'green-dark' }> = ({ text, color }) => {
  const styles = {
    green: "bg-green-500/10 text-green-500 border-green-500/20",
    gray: "bg-white/5 text-gray-500 border-white/10",
