// Insurance policy analysis is a complex reasoning task; using gemini-3-pro-preview for best results.
const MODEL_NAME = 'gemini-3-pro-preview';

/**
 * Calculates a unique hash for the file content.
 */
export const calculateFileHash = async (base64: string): Promise<string> => {
  try {
    if (window.isSecureContext && crypto.subtle) {
      const msgUint8 = new TextEncoder().encode(base64);
      const hashBuffer = await crypto.subtle.digest('SHA-256', msgUint8);
      const hashArray = Array.from(new Uint8Array(hashBuffer));
      return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
    }
  } catch (e) {
    console.warn("Secure crypto failed, falling back to basic hash", e);
  }

  let hash = 0;
  for (let i = 0; i < base64.length; i++) {
    const char = base64.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash; 
  }
  return 'fallback-' + Math.abs(hash).toString(16);
};

/**
 * Analyzes the policy using Gemini AI with an emphasis on customer data extraction for lead gen.
 */
export const analyzePolicy = async (file: File): Promise<PolicyAnalysis> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const base64Data = await new Promise<string>((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = (reader.result as string).split(',')[1];
      resolve(base64String);
    };
    reader.onerror = () => reject(new Error("Failed to read the file."));
    reader.readAsDataURL(file);
  });

  const fileHash = await calculateFileHash(base64Data);

  const prompt = `You are "The Insurance Boss", a legendary insurance auditor.

  TASK:
  Analyze the provided PDF insurance policy. 

  1. CUSTOMER DATA EXTRACTION (CRITICAL): 
     - Extract the full Business Name, Mailing Address, and any Contact Information (Email, Phone) found in the policy or on the agency stamp/letterhead.
     - Identify the primary Industry/Business Type (e.g., HVAC Contractor, Retailer, Multi-family Real Estate).

  2. DETECT EXCLUSIONS & AUDIT:
     - Search for specific exclusion clauses. 
     - Perform a critical review relative to the identified industry.

  3. BOSS CRITIQUE & SCORING:
     - Score 0-10 based on coverage quality and industry gaps.

  OUTPUT REQUIREMENTS:
  - Return JSON.
  - Populate "contactEmail", "contactPhone", and "industry" with found data. If not found, use empty strings but try your hardest to find them in the document headers or footer agency sections.`;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: {
        parts: [
          { inlineData: { data: base64Data, mimeType: file.type || 'application/pdf' } },
          { text: prompt }
        ]
      },
      config: {
        seed: 42,
        temperature: 0,
        thinkingConfig: { thinkingBudget: 32768 }, 
