                <p class="font-black text-xl">${lead.id.toUpperCase()}</p>
              </div>
            </div>
            <div class="grid grid-cols-2 gap-12">
              <div class="space-y-6">
                <section>
                  <h2 class="text-[10px] font-black uppercase text-gray-500 tracking-widest mb-4">Business Information</h2>
