                    <p><strong>Legal Name:</strong> ${lead.businessName}</p>
                    <p><strong>DBA:</strong> ${lead.dba || 'None'}</p>
                    <p><strong>FEIN:</strong> ${lead.fein}</p>
                    <p><strong>Years in Business:</strong> ${lead.yearsInBusiness}</p>
