          <div class="fixed bottom-10 right-10 no-print">
            <button onclick="window.print()" class="bg-black text-white px-10 py-4 rounded-full font-bold shadow-2xl">Download as PDF</button>
          </div>
        </body>
      </html>
    `);
    printWindow.document.close();
