const { Link } = ReactRouterDOM;

interface HeaderProps {
  isAdmin: boolean;
  setIsAdmin: (v: boolean) => void;
  onOpenWizard: () => void;
  onGoHome: () => void;
}

const Header: React.FC<HeaderProps> = ({ isAdmin, setIsAdmin, onOpenWizard, onGoHome }) => {
  const location = ReactRouterDOM.useLocation();
  const navigate = ReactRouterDOM.useNavigate();
  const [hasKey, setHasKey] = useState<boolean>(true);

  useEffect(() => {
    const checkKey = async () => {
      if ((window as any).aistudio?.hasSelectedApiKey) {
        const selected = await (window as any).aistudio.hasSelectedApiKey();
        setHasKey(selected || !!process.env.API_KEY);
      } else {
        setHasKey(!!process.env.API_KEY);
      }
    };
    checkKey();
    const timer = setInterval(checkKey, 2000);
    return () => clearInterval(timer);
  }, []);

  const handleConnectKey = async () => {
    if ((window as any).aistudio?.openSelectKey) {
      await (window as any).aistudio.openSelectKey();
      // Assume success as per guidelines to avoid race condition
      setHasKey(true);
    }
  };

  const handleLogout = () => {
    setIsAdmin(false);
    navigate('/');
  };

  return (
    <header className="sticky top-0 z-50 bg-black/60 backdrop-blur-2xl border-b border-white/5 px-8 py-6 flex items-center justify-between">
      <div className="flex items-center gap-10">
        <div 
          onClick={onGoHome} 
          className="flex items-center gap-4 group cursor-pointer"
        >
          <div className="w-12 h-12 rounded-2xl overflow-hidden border border-white/10 group-hover:scale-110 transition-transform bg-[#0a0a0a] flex items-center justify-center p-2.5">
            <svg className="w-full h-full text-yellow-400" fill="currentColor" viewBox="0 0 24 24">
              <path d="M12 2L3 7v6c0 5.55 3.84 10.74 9 12 5.16-1.26 9-6.45 9-12V7l-9-5zm0 2.18l7 3.89v5.93c0 4.62-3 8.94-7 10-4-1.06-7-5.38-7-10V8.07l7-3.89z"/>
            </svg>
          </div>
          <div>
            <div className="flex items-center gap-3">
              <h1 className="font-black text-2xl tracking-tighter leading-none italic uppercase">The Insurance Boss</h1>
              <div className="flex items-center gap-1.5 bg-yellow-400/10 text-yellow-400 text-[9px] font-black uppercase tracking-widest px-2 py-1 rounded-full border border-yellow-400/20">
                <div className="w-1.5 h-1.5 bg-yellow-400 rounded-full" />
                Local Vault
              </div>
