          className={`relative border border-white/10 rounded-[4rem] p-12 md:p-20 transition-all cursor-pointer group overflow-hidden bg-white/5 backdrop-blur-xl shadow-2xl
            ${isUploading ? 'opacity-80 scale-95' : 'hover:border-yellow-400/50 hover:bg-white/10 active:scale-[0.98]'}
            ${(!userName.trim() || !userEmail.trim()) && !isUploading ? 'opacity-50 grayscale cursor-not-allowed' : ''}
          `}
        >
          <input 
