                onChange={(e) => setUserName(e.target.value)}
                placeholder="Enter your name"
                className="w-full bg-black/40 backdrop-blur-md border border-white/10 rounded-2xl px-6 py-5 focus:outline-none focus:border-yellow-400/50 transition-all text-sm font-bold placeholder:text-gray-700 text-white"
