        {/* UPLOAD BOX */}
        <div 
          onClick={() => !isUploading && isFormValid && fileInputRef.current?.click()}
          className={`relative border border-white/5 rounded-[3rem] p-16 md:p-24 transition-all overflow-hidden bg-black/40 backdrop-blur-xl shadow-2xl flex flex-col items-center justify-center
            ${isUploading ? 'opacity-80' : isFormValid ? 'cursor-pointer hover:bg-white/[0.03] active:scale-[0.99]' : 'opacity-60 grayscale cursor-not-allowed'}
