import React, { useState, useRef } from 'react';
import { analyzePolicy } from '../services/geminiService';
import { PolicyAnalysis } from '../types';

interface UploadSectionProps {
  onAnalysisComplete: (analysis: PolicyAnalysis, userDetails?: { name: string; email: string }) => void;
  existingPolicies: PolicyAnalysis[];
  onOpenWizard: () => void;
}

const UploadSection: React.FC<UploadSectionProps> = ({ onAnalysisComplete, existingPolicies, onOpenWizard }) => {
  const [isUploading, setIsUploading] = useState(false);
  const [userName, setUserName] = useState('');
  const [userEmail, setUserEmail] = useState('');
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsUploading(true);
    setError(null);

    try {
      // Analyze the policy using the Gemini API.
      const analysis = await analyzePolicy(file);
      onAnalysisComplete(analysis, { name: userName, email: userEmail });
    } catch (err: any) {
      setError(err.message || "Audit failed. Please ensure your API key is configured.");
      setIsUploading(false);
    }
  };

  const isFormValid = userName.trim() !== '' && userEmail.trim() !== '';

  return (
    <div className="flex flex-col items-center justify-center text-center py-12 px-4 bg-transparent max-w-5xl mx-auto">

      {/* HEADER */}
      <div className="mb-16 space-y-4">
        <h1 className="text-6xl md:text-[7.5rem] font-black italic leading-[0.85] tracking-tighter">
          Is Your Policy <br />
          <span className="text-yellow-400">Protecting</span> You?
        </h1>
        <p className="text-gray-500 text-lg md:text-2xl font-bold max-w-2xl mx-auto leading-tight italic opacity-80">
          Upload your policy for an instant technical audit. Identify traps before they identify you.
        </p>
      </div>

      {/* INPUTS */}
      {!isUploading && (
        <div className="w-full max-w-3xl grid grid-cols-1 md:grid-cols-2 gap-8 text-left mb-10">
          <div className="space-y-3">
            <label className="text-[11px] font-black text-gray-600 tracking-wider ml-1">Full Name</label>
            <input 
              type="text"
              value={userName}
              onChange={(e) => setUserName(e.target.value)}
              placeholder="Enter your name"
              className="w-full bg-[#0a0a0a] border border-white/5 rounded-2xl px-6 py-5 text-sm font-bold focus:outline-none focus:border-yellow-400/20 transition-all text-white"
            />
          </div>
          <div className="space-y-3">
            <label className="text-[11px] font-black text-gray-600 tracking-wider ml-1">Email Address</label>
            <input 
              type="email"
              value={userEmail}
              onChange={(e) => setUserEmail(e.target.value)}
              placeholder="boss@example.com"
              className="w-full bg-[#0a0a0a] border border-white/5 rounded-2xl px-6 py-5 text-sm font-bold focus:outline-none focus:border-yellow-400/20 transition-all text-white"
            />
          </div>
        </div>
      )}

      {/* MAIN UPLOAD BOX */}
      <div 
        onClick={() => !isUploading && isFormValid && fileInputRef.current?.click()}
        className={`w-full max-w-4xl min-h-[450px] rounded-[4.5rem] bg-[#050505] border border-white/5 flex flex-col items-center justify-center p-12 transition-all relative
          ${isFormValid && !isUploading ? 'cursor-pointer hover:bg-white/[0.01] active:scale-[0.99] border-white/10 shadow-[0_40px_100px_rgba(0,0,0,0.6)]' : 'opacity-80'}
        `}
      >
        <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" accept="application/pdf" />

        {isUploading ? (
          <div className="space-y-8 flex flex-col items-center">
            <div className="w-20 h-20 border-[6px] border-yellow-400/10 border-t-yellow-400 rounded-full animate-spin" />
            <h3 className="text-3xl font-black italic tracking-tighter text-white">Boss AI Analysis...</h3>
          </div>
        ) : (
          <div className="space-y-12 flex flex-col items-center">
            <div className="bg-white/[0.03] p-10 rounded-[2.5rem] border border-white/5 flex items-center justify-center">
              <svg className="w-16 h-16 text-gray-700" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <rect x="4" y="4" width="16" height="16" rx="4" strokeWidth="2.5" />
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 15V9m0 0l-3 3m3-3l3 3" />
              </svg>
            </div>
            <h3 className="text-4xl md:text-[3.5rem] font-black italic tracking-tighter leading-none text-white">
              {isFormValid ? 'Click to Upload Policy' : 'Enter Your Details First'}
            </h3>
          </div>
        )}
      </div>

      {/* FOOTER ACTIONS */}
      {!isUploading && (
        <div className="mt-12 flex flex-col items-center gap-6">
          <button 
            onClick={onOpenWizard}
            className="px-28 py-6 rounded-2xl bg-yellow-400 text-black font-black text-sm tracking-wider hover:bg-yellow-500 transition-all active:scale-95 shadow-[0_20px_50px_rgba(250,204,21,0.25)]"
          >
            Get A Quote
          </button>
          <p className="text-gray-700 text-[11px] font-black tracking-widest opacity-80">
            No policy handy? Fill out to get one
          </p>
        </div>
      )}

      {error && (
        <div className="mt-8 p-6 bg-red-500/10 border border-red-500/20 rounded-2xl text-red-400 text-xs font-black tracking-widest animate-in fade-in">
          {error}
        </div>
      )}
    </div>
  );
};

export default UploadSection;

import React, { useRef, useState } from 'react';
import { PolicyAnalysis } from '../types';

interface AnalysisResultProps {
  analysis: PolicyAnalysis;
  onReset: () => void;
  onOpenWizard: () => void;
}

const AnalysisResult: React.FC<AnalysisResultProps> = ({ analysis, onReset, onOpenWizard }) => {
  const dashboardRef = useRef<HTMLDivElement>(null);
  const [bundleInfo, setBundleInfo] = useState('');
  const [isBundleRequested, setIsBundleRequested] = useState(false);
  const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);

  const handleDownloadPDF = async () => {
    if (!dashboardRef.current) return;
    const html2pdf = (window as any).html2pdf;
    if (!html2pdf) {
      alert("Boss, the PDF engine is still warming up. Try again in a second.");
      return;
    }

    setIsGeneratingPdf(true);
    const element = dashboardRef.current;

    // Create a deep copy or use temporary classes for styling
    element.classList.add('pdf-mode');

    const opt = {
      margin: [0.5, 0.5],
      filename: `The_Insurance_Boss_Audit_${analysis.insuredName.replace(/\s+/g, '_')}.pdf`,
      image: { type: 'jpeg', quality: 1.0 },
      html2canvas: { 
        scale: 2, 
        useCORS: true, 
        backgroundColor: '#000000',
        logging: false,
        letterRendering: true,
      },
      jsPDF: { unit: 'in', format: 'letter', orientation: 'portrait' }
    };

    try {
      await html2pdf().set(opt).from(element).save();
    } catch (error) {
      console.error("PDF Export failed:", error);
      alert("Boss, PDF generation hit a snag. Please try again.");
    } finally {
      element.classList.remove('pdf-mode');
      setIsGeneratingPdf(false);
    }
  };

  const handleConsultExpert = () => {
    window.open('https://theinsuranceboss.com/contact/', '_blank');
  };

  const handleRequestBundle = () => {
    if (!bundleInfo.trim()) {
      alert("Please provide some policy details for the bundle review, Boss.");
      return;
    }
    setIsBundleRequested(true);
    setTimeout(() => {
      alert("Bundle review request received. Our experts will audit your entire portfolio.");
    }, 500);
  };

  const getScoreColor = () => {
    if (analysis.score >= 8) return 'text-green-400';
    if (analysis.score >= 5) return 'text-yellow-400';
    return 'text-red-500';
  };

  return (
    <div ref={dashboardRef} className="relative space-y-8 animate-in fade-in duration-1000 pb-24 max-w-7xl mx-auto px-4 bg-transparent text-white">

      {/* PDF ONLY HEADER */}
      <div className="hidden pdf-only flex justify-between items-center border-b-2 border-yellow-400/30 pb-6 mb-10 text-white">
        <div>
          <h1 className="text-3xl font-black tracking-tighter">The Insurance Boss</h1>
          <p className="text-[10px] text-gray-400 font-black tracking-widest">Executive Policy Audit Report</p>
        </div>
        <div className="text-right">
          <p className="text-[9px] text-gray-500 font-black">Date Generated</p>
          <p className="text-sm font-bold">{new Date().toLocaleDateString()}</p>
        </div>
      </div>

      {/* SECTION 1: TOP HEADER (SUMMARY & INSURED DETAILS) */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">

        {/* SUMMARY & SCORE CARD */}
        <div className="lg:col-span-8 bg-black/40 backdrop-blur-2xl rounded-[3rem] p-10 border border-white/10 relative overflow-hidden flex flex-col md:flex-row items-center gap-10 shadow-2xl">
          <div className="absolute right-10 top-1/2 -translate-y-1/2 opacity-[0.03] pointer-events-none">
            <svg className="w-64 h-64" fill="currentColor" viewBox="0 0 24 24">
              <path d="M12 1L3 5v6c0 5.55 3.84 10.74 9 12 5.16-1.26 9-6.45 9-12V5l-9-4zm0 2.18l7 3.89v5.93c0 4.62-3 8.94-7 10-4-1.06-7-5.38-7-10V8.07l7-3.89z"/>
            </svg>
          </div>

          <div className="flex flex-col items-center flex-shrink-0 text-center relative z-10">
            <div className="flex items-baseline gap-1">
              <span className={`text-9xl font-black tracking-tighter leading-none ${getScoreColor()}`}>
                {analysis.score.toFixed(1)}
              </span>
              <span className="text-3xl font-black text-gray-700 tracking-tighter">/10</span>
            </div>
            <p className="text-[10px] font-black text-gray-500 tracking-widest mt-2">Boss Score</p>
          </div>

          <div className="flex-1 space-y-6 relative z-10 text-left">
            <div className="flex flex-wrap gap-3">
              <div className="px-5 py-1.5 rounded-xl border border-yellow-400/30 bg-yellow-400/5 text-yellow-400 text-[10px] font-black tracking-wider">
                {analysis.rating || "Fair"}
              </div>
              <div className="px-5 py-1.5 rounded-xl border border-white/10 bg-white/5 text-gray-400 text-[10px] font-black tracking-wider">
                {analysis.type || "Commercial Package Policy"}
              </div>
            </div>
            <div className="pl-6 border-l-4 border-yellow-400">
              <p className="text-white text-2xl md:text-3xl font-bold leading-tight tracking-tight">
                "{analysis.summary}"
              </p>
            </div>
          </div>
        </div>

        {/* INSURED DETAILS CARD */}
        <div className="lg:col-span-4 bg-black/40 backdrop-blur-2xl rounded-[3rem] p-10 border border-white/10 relative overflow-hidden flex flex-col shadow-2xl text-left">
          <div className="absolute left-0 top-10 bottom-10 w-1.5 bg-yellow-400 rounded-full" />
          <h3 className="text-[10px] font-black text-gray-500 tracking-widest mb-10">Insured Details</h3>
          <div className="space-y-8 flex-1 flex flex-col justify-center">
            <DetailItem label="Company Name" value={analysis.insuredName} large highlight />
