import React, { useState, useEffect } from 'react';
import * as ReactRouterDOM from 'react-router-dom';
import Header from './components/Header';
import UploadSection from './components/UploadSection';
import AnalysisResult from './components/AnalysisResult';
import AdminDashboard from './components/AdminDashboard';
import AdminLogin from './components/AdminLogin';
import WizardForm from './components/WizardForm';
import RegistrationForm from './components/RegistrationForm';
import VerificationPending from './components/VerificationPending';
import { PolicyAnalysis, QuoteRequest } from './types';
import { storage } from './services/storage';
import { bossServer } from './services/serverService';

const { HashRouter, Routes, Route, useSearchParams } = ReactRouterDOM;

// Wrapper to handle search params logic within the HashRouter context
const MainView: React.FC<{
  isAdmin: boolean,
  showWizard: boolean,
  setShowWizard: (v: boolean) => void,
  allPolicies: PolicyAnalysis[],
  currentAnalysis: PolicyAnalysis | null,
  handleNewAnalysis: (a: PolicyAnalysis) => void,
  handleNewLead: (l: QuoteRequest) => void,
  setCurrentAnalysis: (a: PolicyAnalysis | null) => void,
  allLeads: QuoteRequest[]
}> = ({ isAdmin, showWizard, setShowWizard, allPolicies, currentAnalysis, handleNewAnalysis, handleNewLead, setCurrentAnalysis, allLeads }) => {
  const [searchParams, setSearchParams] = useSearchParams();
  const [isVerified, setIsVerified] = useState(() => {
    // Persistent verification for the demo
    return localStorage.getItem('boss_is_verified') === 'true';
  });
  const [pendingUser, setPendingUser] = useState<{ name: string; email: string } | null>(null);

  useEffect(() => {
    const token = searchParams.get('token');
    if (token) {
      // Find the lead associated with this token
      const matchingLead = allLeads.find(l => l.verificationToken === token);
      if (matchingLead) {
        setIsVerified(true);
        localStorage.setItem('boss_is_verified', 'true');
        localStorage.setItem('boss_user_email', matchingLead.contactEmail);
        localStorage.setItem('boss_user_name', matchingLead.contactName);
        // Clear param to clean URL
        setSearchParams({}, { replace: true });
      }
    }
  }, [searchParams, allLeads, setSearchParams]);

  const handleRegister = async (name: string, email: string) => {
    const token = Math.random().toString(36).substr(2, 12);
    const newLead: QuoteRequest = {
      id: `lead-${Date.now()}`,
      submissionDate: new Date().toLocaleString(),
      status: 'New',
      businessName: `${name}'s Company`,
      fein: 'PENDING',
      yearsInBusiness: '1',
      address1: 'PENDING',
      city: 'PENDING',
      state: 'PENDING',
      zip: 'PENDING',
      country: 'United States',
      industries: ['Pending Verification'],
      hasActiveCoverage: false,
      knowsPremium: false,
      hasDeclPage: false,
      contactName: name,
      contactEmail: email,
      contactPhone: '',
      verificationToken: token,
      isVerified: false
    };

    // Store the lead in the background
    await storage.saveLead(newLead);
    await bossServer.upstream('lead', newLead);

    setPendingUser({ name, email });
    // In a real app, you would fire off an email via a backend here using the token
  };

  const simulateMagicLink = () => {
    if (!pendingUser) return;
    const leads = allLeads.length > 0 ? allLeads : []; // Just in case leads haven't loaded
    // We simulate by just setting verified true since we are in the same browser session
    setIsVerified(true);
    localStorage.setItem('boss_is_verified', 'true');
    localStorage.setItem('boss_user_email', pendingUser.email);
    localStorage.setItem('boss_user_name', pendingUser.name);
    setPendingUser(null);
  };

  if (showWizard) {
    return <WizardForm onSubmit={handleNewLead} onCancel={() => setShowWizard(false)} />;
  }

  if (currentAnalysis) {
    return (
      <AnalysisResult 
        analysis={currentAnalysis} 
        onReset={() => setCurrentAnalysis(null)} 
        onOpenWizard={() => setShowWizard(true)}
      />
    );
  }

  if (isVerified) {
    return (
      <UploadSection 
        onAnalysisComplete={handleNewAnalysis} 
        existingPolicies={allPolicies}
        onOpenWizard={() => setShowWizard(true)}
      />
    );
  }

  if (pendingUser) {
    return <VerificationPending email={pendingUser.email} onSimulateLink={simulateMagicLink} />;
  }

  return <RegistrationForm onRegister={handleRegister} />;
};

const App: React.FC = () => {
  const [isAdmin, setIsAdmin] = useState(false);
  const [allPolicies, setAllPolicies] = useState<PolicyAnalysis[]>([]);
  const [allLeads, setAllLeads] = useState<QuoteRequest[]>([]);
  const [currentAnalysis, setCurrentAnalysis] = useState<PolicyAnalysis | null>(null);
  const [showWizard, setShowWizard] = useState(false);
  const [isEmbedded, setIsEmbedded] = useState(false);

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const embedMode = params.get('embed') === 'true' || window.location.href.includes('embed=true');
    setIsEmbedded(embedMode);

    const loadData = async () => {
      try {
        const cloudData = await bossServer.fetchGlobalVault();
        if (cloudData.policies) {
          for (const p of cloudData.policies) await storage.savePolicy(p);
        }
        if (cloudData.leads) {
          for (const l of cloudData.leads) await storage.saveLead(l);
        }

        const p = await storage.getPolicies();
        const l = await storage.getLeads();
        setAllPolicies(p);
        setAllLeads(l);
      } catch (err) {
        console.error("Silent Sync Warning:", err);
      }
    };
    loadData();
  }, []);

  const handleNewAnalysis = async (analysis: PolicyAnalysis) => {
    setCurrentAnalysis(analysis);
    setShowWizard(false);

    const userEmail = localStorage.getItem('boss_user_email') || '';
    const userName = localStorage.getItem('boss_user_name') || '';

    storage.savePolicy(analysis).then(() => {
      setAllPolicies(prev => {
        const exists = prev.some(p => p.id === analysis.id);
        return exists ? prev : [analysis, ...prev];
      });
      bossServer.upstream('policy', analysis);
    });

    const autoLead: QuoteRequest = {
      id: `auto-${analysis.id}`,
      submissionDate: new Date().toLocaleString(),
      status: 'New',
      businessName: analysis.insuredName,
      fein: analysis.fein || 'EXTRACTED',
      yearsInBusiness: 'EXTRACTED',
      address1: analysis.insuredAddress || '',
      city: 'EXTRACTED',
      state: 'EXTRACTED',
      zip: 'EXTRACTED',
      country: 'United States',
      industries: analysis.industry ? [analysis.industry] : ['Policy Audit'],
      hasActiveCoverage: true,
      knowsPremium: false,
      hasDeclPage: true,
      contactName: userName || analysis.insuredName || 'Insured',
      contactEmail: userEmail || analysis.contactEmail || '',
      contactPhone: analysis.contactPhone || '',
      sourcePolicyId: analysis.id,
      isVerified: true
    };

    handleNewLead(autoLead);
  };

  const handleNewLead = async (lead: QuoteRequest) => {
    setAllLeads(prev => {
      const filtered = prev.filter(l => l.id !== lead.id);
      return [lead, ...filtered];
    });
    storage.saveLead(lead);
    bossServer.upstream('lead', lead);
  };

  const handleDeletePolicy = async (id: string) => {
    await storage.deletePolicy(id);
    setAllPolicies(prev => prev.filter(p => p.id !== id));
  };

  const handleDeleteLead = async (id: string) => {
    await storage.deleteLead(id);
    setAllLeads(prev => prev.filter(l => l.id !== id));
  };

  const handleStatusChange = async (id: string, status: QuoteRequest['status']) => {
    const lead = allLeads.find(l => l.id === id);
    if (lead) {
      const updated = { ...lead, status };
      await storage.saveLead(updated);
      setAllLeads(prev => prev.map(l => l.id === id ? updated : l));
      await bossServer.upstream('lead', updated);
    }
  };

  const handleImport = async (json: string) => {
    await storage.importBackup(json);
    const p = await storage.getPolicies();
    const l = await storage.getLeads();
    setAllPolicies(p);
    setAllLeads(l);
  };

  return (
    <HashRouter>
      <div className="min-h-screen bg-transparent text-white border-none">
        {!isEmbedded && (
          <Header 
            isAdmin={isAdmin} 
            setIsAdmin={setIsAdmin} 
            onOpenWizard={() => { setCurrentAnalysis(null); setShowWizard(true); }} 
            onGoHome={() => { setCurrentAnalysis(null); setShowWizard(false); }}
          />
        )}

        <main className={`container mx-auto px-4 max-w-6xl bg-transparent ${isEmbedded ? 'py-0' : 'py-8'}`}>
          <Routes>
            <Route path="/" element={
              <MainView 
                isAdmin={isAdmin}
                showWizard={showWizard}
                setShowWizard={setShowWizard}
                allPolicies={allPolicies}
                currentAnalysis={currentAnalysis}
                handleNewAnalysis={handleNewAnalysis}
                handleNewLead={handleNewLead}
                setCurrentAnalysis={setCurrentAnalysis}
                allLeads={allLeads}
              />
            } />

            <Route path="/admin" element={
              isAdmin ? (
                <AdminDashboard 
                  policies={allPolicies} 
                  leads={allLeads}
                  onDeletePolicy={handleDeletePolicy}
                  onDeleteLead={handleDeleteLead}
                  onStatusChange={handleStatusChange}
                  onImport={handleImport}
                  onViewPolicy={(p) => {
                    setCurrentAnalysis(p);
                    setShowWizard(false);
                    window.location.hash = '#/';
                  }}
                />
              ) : (
                <AdminLogin onLogin={() => setIsAdmin(true)} />
              )
            } />
          </Routes>
        </main>

        {!isEmbedded && (
          <footer className="py-12 border-none text-center text-gray-500 text-sm bg-transparent">
            <p>© {new Date().getFullYear()} The Insurance Boss Policy Review Tool.</p>
          </footer>
        )}
      </div>
    </HashRouter>
  );
};

