interface AnalysisResultProps {
  analysis: PolicyAnalysis;
  onReset: () => void;
  onOpenWizard: () => void;
}

const AnalysisResult: React.FC<AnalysisResultProps> = ({ analysis, onReset, onOpenWizard }) => {
  const dashboardRef = useRef<HTMLDivElement>(null);
  const [bundleInfo, setBundleInfo] = useState('');
  const [isBundleRequested, setIsBundleRequested] = useState(false);

  const handleConsultExpert = () => {
    window.open('https://theinsuranceboss.com/contact/', '_blank');
  };

  const handleRequestBundle = () => {
    if (!bundleInfo.trim()) {
      alert("Please provide some policy details for the bundle review, Boss.");
      return;
    }
    setIsBundleRequested(true);
    setTimeout(() => {
      alert("Bundle review request received. Our experts will audit your entire portfolio.");
    }, 500);
  };

  const getScoreColor = () => {
    if (analysis.score >= 8) return 'text-green-400';
    if (analysis.score >= 5) return 'text-yellow-400';
    return 'text-red-500';
  };

  return (
    <div ref={dashboardRef} className="relative space-y-8 animate-in fade-in duration-1000 pb-24 max-w-7xl mx-auto px-4 bg-transparent text-white">

      {/* SECTION 1: TOP HEADER (SUMMARY & INSURED DETAILS) */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">

        {/* SUMMARY & SCORE CARD */}
        <div className="lg:col-span-8 bg-black/40 backdrop-blur-2xl rounded-[3rem] p-10 border border-white/10 relative overflow-hidden flex flex-col md:flex-row items-center gap-10 shadow-2xl">
          <div className="absolute right-10 top-1/2 -translate-y-1/2 opacity-[0.03] pointer-events-none">
            <svg className="w-64 h-64" fill="currentColor" viewBox="0 0 24 24">
              <path d="M12 1L3 5v6c0 5.55 3.84 10.74 9 12 5.16-1.26 9-6.45 9-12V5l-9-4zm0 2.18l7 3.89v5.93c0 4.62-3 8.94-7 10-4-1.06-7-5.38-7-10V8.07l7-3.89z"/>
            </svg>
          </div>

          <div className="flex flex-col items-center flex-shrink-0 text-center relative z-10">
            <div className="flex items-baseline gap-1">
              <span className={`text-9xl font-black tracking-tighter leading-none ${getScoreColor()}`}>
                {analysis.score.toFixed(1)}
              </span>
              <span className="text-3xl font-black text-gray-700 tracking-tighter">/10</span>
            </div>
            <p className="text-[10px] font-black text-gray-500 tracking-widest mt-2 uppercase">Boss score</p>
          </div>

          <div className="flex-1 space-y-6 relative z-10 text-left">
            <div className="flex flex-wrap gap-3">
              <div className="px-5 py-1.5 rounded-xl border border-yellow-400/30 bg-yellow-400/5 text-yellow-400 text-[10px] font-black tracking-wider">
                {analysis.rating || "Fair"}
              </div>
              <div className="px-5 py-1.5 rounded-xl border border-white/10 bg-white/5 text-gray-400 text-[10px] font-black tracking-wider">
                {analysis.type || "Commercial Package Policy"}
              </div>
            </div>
            <div className="pl-6 border-l-4 border-yellow-400">
              <p className="text-white text-2xl md:text-3xl font-bold leading-tight tracking-tight">
                "{analysis.summary}"
              </p>
            </div>
          </div>
        </div>

        {/* INSURED DETAILS CARD */}
        <div className="lg:col-span-4 bg-black/40 backdrop-blur-2xl rounded-[3rem] p-10 border border-white/10 relative overflow-hidden flex flex-col shadow-2xl text-left">
          <div className="absolute left-0 top-10 bottom-10 w-1.5 bg-yellow-400 rounded-full" />
          <h3 className="text-[10px] font-black text-gray-500 tracking-widest mb-10 uppercase">Insured details</h3>
          <div className="space-y-8 flex-1 flex flex-col justify-center">
            <DetailItem label="Company name" value={analysis.insuredName} large highlight />
            <DetailItem label="Policy number" value={analysis.policyNumber || "Not Found"} highlight />
            <div className="grid grid-cols-2 gap-4">
              <DetailItem label="Effective" value={analysis.effectiveDate || "N/A"} />
              <DetailItem label="Expires" value={analysis.expirationDate || "N/A"} />
            </div>
            <DetailItem label="Location address" value={analysis.insuredAddress || "See Policy Documents"} />
          </div>
        </div>
      </div>

      {/* SECTION 2: MIDDLE ROW (COVERAGE ANALYSIS & EXCLUSIONS) */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 text-left">
        <div className="bg-black/40 backdrop-blur-2xl rounded-[2.5rem] p-10 border border-white/10 space-y-8 h-full shadow-xl">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-white/5 rounded-2xl flex items-center justify-center text-yellow-400 border border-white/10">
               <ShieldIcon />
            </div>
            <h3 className="text-xl font-black tracking-tighter text-white">Coverage analysis</h3>
          </div>
          <p className="text-gray-400 text-lg font-semibold leading-relaxed">
            {analysis.coverageAnalysis}
          </p>
        </div>

        <div className="bg-black/40 backdrop-blur-2xl rounded-[2.5rem] p-10 border border-white/10 space-y-10 h-full shadow-xl">
          <h3 className="text-xl font-black tracking-tighter text-red-500">Exclusions</h3>
          <ul className="space-y-4">
            {analysis.foundExclusions?.map((ex, i) => (
              <li key={i} className="flex items-center gap-4 group">
                <div className="flex-shrink-0 text-red-500">
                  <XIcon />
                </div>
                <span className="text-gray-400 text-base font-bold tracking-tight group-hover:text-red-400 transition-colors leading-none">
                  {ex}
                </span>
              </li>
            ))}
            {(!analysis.foundExclusions || analysis.foundExclusions.length === 0) && (
              <li className="text-gray-600 font-bold tracking-widest text-[10px]">No critical exclusions detected in scan.</li>
            )}
          </ul>
        </div>
      </div>

      {/* SECTION 3: BOTTOM ROW (STRENGTHS, RED FLAGS, RECOMMENDATIONS) */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 text-left">
        <ColumnCard 
          title="Strengths" 
          color="green" 
          icon={<CheckIcon />} 
          items={analysis.strengths} 
        />
        <ColumnCard 
          title="Red flags" 
          color="red" 
          icon={<XIcon />} 
          items={analysis.redFlags} 
        />
        <ColumnCard 
          title="Recommendations" 
          color="yellow" 
          icon={<ArrowIcon />} 
          items={analysis.recommendations} 
        />
      </div>

      {/* NEW SECTION: FULL BUNDLE REVIEW REQUEST */}
      <div className="bg-black/40 backdrop-blur-3xl rounded-[3rem] p-10 border border-yellow-400/20 relative overflow-hidden group shadow-2xl text-left">
        <div className="absolute -right-20 -top-20 w-64 h-64 bg-yellow-400/5 rounded-full blur-[100px] pointer-events-none group-hover:bg-yellow-400/10 transition-all duration-700" />

        <div className="relative z-10 flex flex-col lg:flex-row gap-12 items-center">
          <div className="flex-1 space-y-6">
            <div className="inline-flex items-center gap-2 px-4 py-1.5 rounded-full bg-yellow-400/10 border border-yellow-400/30 text-yellow-400 text-[10px] font-black tracking-widest animate-pulse uppercase">
              <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2L2 7l10 5 10-5-10-5zM2 17l10 5 10-5M2 12l10 5 10-5"/></svg>
              Account maximization
            </div>
            <h3 className="text-4xl font-black tracking-tighter leading-none">
              Get a full <span className="text-yellow-400">bundle review</span>
            </h3>
            <p className="text-gray-400 text-lg font-semibold leading-relaxed max-w-2xl">
              Do you have additional policies? For a truly comprehensive risk audit, the Boss needs to see your entire portfolio.
            </p>
          </div>

          <div className="w-full lg:w-1/2 space-y-4">
            {isBundleRequested ? (
              <div className="bg-yellow-400/10 border border-yellow-400/30 p-8 rounded-[2rem] text-center animate-in zoom-in-95">
                <p className="text-yellow-400 font-black text-xl tracking-tighter">Bundle audit initiated!</p>
                <p className="text-gray-500 text-sm mt-2 font-bold tracking-widest">Our risk specialists are standing by.</p>
              </div>
            ) : (
              <div className="flex flex-col gap-4">
                <textarea 
                  placeholder="e.g. Workers Comp ($1M/$1M), GL Excess ($5M)..."
                  value={bundleInfo}
                  onChange={(e) => setBundleInfo(e.target.value)}
                  className="w-full bg-white/5 border border-white/10 rounded-2xl p-6 text-sm font-bold focus:border-yellow-400 transition-all outline-none min-h-[100px] placeholder:text-gray-600 text-white"
                />
                <button 
                  onClick={handleRequestBundle}
                  className="bg-yellow-400 text-black px-6 py-4 rounded-xl text-xs font-black tracking-wider hover:bg-yellow-500 transition-all active:scale-95 shadow-xl uppercase"
                >
                  Audit my entire portfolio
                </button>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* ACTION BAR */}
      <div className="pt-10 flex flex-col md:flex-row justify-between items-center gap-6 border-t border-white/10 text-left">
        <button 
          onClick={onReset} 
          className="text-gray-500 hover:text-white font-black text-xs tracking-wider transition-all flex items-center gap-3 group uppercase"
        >
          <svg className="w-5 h-5 group-hover:-translate-x-1 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
          </svg>
          New audit
        </button>
        <div className="flex gap-4">
          <button 
            onClick={handleConsultExpert} 
            className="bg-yellow-400 text-black px-12 py-5 rounded-2xl font-black text-xs tracking-wider hover:bg-yellow-500 transition-all shadow-xl active:scale-95 flex items-center gap-3 uppercase"
          >
            Consult expert
          </button>
        </div>
      </div>
    </div>
  );
};

const DetailItem: React.FC<{ label: string; value: string; large?: boolean; highlight?: boolean }> = ({ label, value, large, highlight }) => (
  <div className="space-y-1.5">
    <p className="text-[9px] font-black text-gray-500 tracking-widest uppercase">{label}</p>
    <p className={`font-black tracking-tight leading-none ${large ? 'text-2xl' : 'text-base'} ${highlight ? 'text-yellow-400' : 'text-white'}`}>
      {value}
    </p>
  </div>
);

const ColumnCard: React.FC<{ title: string; color: 'green' | 'red' | 'yellow'; icon: React.ReactNode; items: string[] }> = ({ title, color, icon, items }) => {
  const titleColor = {
    green: "text-green-500",
    red: "text-red-500",
    yellow: "text-yellow-400"
  };

  return (
    <div className="bg-black/40 backdrop-blur-2xl border border-white/10 rounded-[2.5rem] p-10 space-y-10 flex flex-col h-full shadow-lg text-left">
      <h3 className={`text-xl font-black tracking-tighter ${titleColor[color]}`}>{title}</h3>
      <ul className="space-y-6 flex-1">
        {items.map((item, i) => (
          <li key={i} className="flex gap-4 items-start group">
            <div className={`mt-1 flex-shrink-0 ${titleColor[color]}`}>
              {icon}
            </div>
            <p className="text-gray-400 text-base font-bold leading-relaxed group-hover:text-white transition-colors tracking-tight">{item}</p>
          </li>
        ))}
      </ul>
    </div>
  );
};

const ShieldIcon = () => (
  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" />
  </svg>
);

const CheckIcon = () => (
  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
  </svg>
);

const XIcon = () => (
  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" />
  </svg>
);

const ArrowIcon = () => (
  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M13 7l5 5m0 0l-5 5m5-5H6" />
  </svg>
);

export default AnalysisResult;

import React, { useMemo, useState, useEffect } from 'react';
import { PolicyAnalysis, AdminStats, QuoteRequest } from '../types';
import { bossServer } from '../services/serverService';

interface AdminDashboardProps {
  policies: PolicyAnalysis[];
  leads: QuoteRequest[];
  onDeletePolicy: (id: string) => void;
  onDeleteLead: (id: string) => void;
  onStatusChange: (id: string, status: QuoteRequest['status']) => void;
  onViewPolicy: (p: PolicyAnalysis) => void;
  onImport: (json: string) => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ policies, leads, onDeletePolicy, onDeleteLead, onStatusChange, onViewPolicy, onImport }) => {
  const [activeTab, setActiveTab] = useState<'policies' | 'leads' | 'activity'>('policies');
  const [serverStatus, setServerStatus] = useState(bossServer.getStatus());

  useEffect(() => {
    bossServer.onStatusChange(() => {
      setServerStatus(bossServer.getStatus());
    });
  }, []);

  const stats = useMemo<AdminStats>(() => {
    return {
      totalPolicies: policies.length,
      totalLeads: leads.length,
      reviewed: policies.length,
      goodPolicies: policies.filter(p => p.rating === 'Good').length,
      needsImprovement: policies.filter(p => p.rating === 'Needs Improvement').length,
      needsReview: policies.filter(p => p.rating === 'Poor').length
    };
  }, [policies, leads]);

  const activityLog = useMemo(() => {
    const all = [
      ...policies.map(p => ({ id: p.id, type: 'Audit', title: p.insuredName, date: p.uploadDate, status: p.rating })),
      ...leads.map(l => ({ id: l.id, type: 'Lead', title: l.businessName, date: l.submissionDate, status: l.status }))
    ];
    return all.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()).slice(0, 10);
  }, [policies, leads]);

  return (
    <div className="space-y-10 animate-in fade-in slide-in-from-bottom-2 duration-500 pb-20 text-left bg-transparent">

      {/* GLOBAL COMMAND HEADER */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 px-2">
        <div className="flex items-center gap-6">
          <div>
            <h2 className="text-4xl font-black tracking-tighter text-white">Staff vault</h2>
            <p className="text-gray-500 font-bold uppercase tracking-widest text-[10px]">Command center access</p>
          </div>

          <div className={`flex items-center gap-3 px-5 py-2.5 rounded-2xl border transition-all duration-700 ${serverStatus === 'Online' ? 'bg-green-500/10 border-green-500/20' : 'bg-red-500/10 border-red-500/20'}`}>
            <div className={`w-2.5 h-2.5 rounded-full ${serverStatus === 'Online' ? 'bg-green-400 animate-pulse shadow-[0_0_10px_rgba(74,222,128,0.5)]' : 'bg-red-400'}`} />
            <span className={`text-[10px] font-black uppercase tracking-widest ${serverStatus === 'Online' ? 'text-green-400' : 'text-red-400'}`}>
              Server authority: {serverStatus}
            </span>
          </div>
        </div>

        <div className="flex bg-white/5 backdrop-blur-xl p-1.5 rounded-2xl border border-white/10 overflow-x-auto shadow-2xl">
          <button onClick={() => setActiveTab('policies')} className={`px-6 py-2.5 rounded-xl text-xs font-black transition-all whitespace-nowrap tracking-widest uppercase ${activeTab === 'policies' ? 'bg-yellow-400 text-black shadow-lg' : 'text-gray-400 hover:text-white'}`}>Audits</button>
          <button onClick={() => setActiveTab('leads')} className={`px-6 py-2.5 rounded-xl text-xs font-black transition-all whitespace-nowrap tracking-widest uppercase ${activeTab === 'leads' ? 'bg-yellow-400 text-black shadow-lg' : 'text-gray-400 hover:text-white'}`}>Leads ({leads.length})</button>
          <button onClick={() => setActiveTab('activity')} className={`px-6 py-2.5 rounded-xl text-xs font-black transition-all whitespace-nowrap tracking-widest uppercase ${activeTab === 'activity' ? 'bg-yellow-400 text-black shadow-lg' : 'text-gray-400 hover:text-white'}`}>Activity</button>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard title="Total audits" value={stats.totalPolicies} color="gray" />
        <StatCard title="New leads" value={leads.filter(l => l.status === 'New').length} color="blue" />
        <StatCard title="High risk clients" value={stats.needsReview} color="red" />
        <StatCard title="Live server" value={100} isPercent color="green" />
      </div>

      {activeTab === 'policies' && (
        <div className="bg-black/40 backdrop-blur-2xl rounded-[2.5rem] border border-white/10 overflow-hidden shadow-2xl animate-in fade-in slide-in-from-top-4">
          <div className="px-8 py-6 border-b border-white/10 flex items-center justify-between bg-white/[0.02]">
            <h3 className="font-bold text-xl tracking-tighter text-white">Policy audit vault</h3>
            <div className="flex items-center gap-3">
               <span className="text-[10px] text-gray-500 font-black uppercase tracking-widest">Auto-synced</span>
               <div className="w-2 h-2 rounded-full bg-green-500 animate-pulse" />
            </div>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="text-gray-500 text-[10px] font-bold tracking-widest border-b border-white/5 bg-black/40">
                  <th className="px-8 py-5 uppercase">Insured</th>
                  <th className="px-8 py-5 uppercase">Policy</th>
                  <th className="px-8 py-5 uppercase">Rating</th>
                  <th className="px-8 py-5 uppercase">Boss score</th>
                  <th className="px-8 py-5 text-right uppercase">Action</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-white/5">
                {policies.length === 0 ? (
                  <tr><td colSpan={5} className="px-8 py-20 text-center text-gray-500 font-bold italic tracking-wider uppercase text-xs">Waiting for incoming audits...</td></tr>
                ) : policies.map((p) => (
                  <tr key={p.id} className="hover:bg-white/[0.03] transition-colors group">
                    <td className="px-8 py-6">
                      <div className="text-sm font-bold text-white group-hover:text-yellow-400 transition-colors">{p.insuredName || 'N/A'}</div>
                      <div className="text-[10px] text-gray-600 font-mono tracking-tighter truncate max-w-[150px] uppercase">Ref: {p.id}</div>
                    </td>
                    <td className="px-8 py-6">
                      <span className="inline-block px-3 py-1 rounded-lg bg-white/5 text-[10px] font-black text-gray-400 border border-white/5">{p.type || 'Standard'}</span>
                    </td>
                    <td className="px-8 py-6">
                      <span className={`px-3 py-1 rounded-full text-[9px] font-black tracking-widest uppercase ${p.rating === 'Good' ? 'bg-green-500/10 text-green-400' : p.rating === 'Needs Improvement' ? 'bg-yellow-500/10 text-yellow-400' : 'bg-red-500/10 text-red-400'}`}>{p.rating}</span>
                    </td>
                    <td className="px-8 py-6 font-black text-white text-lg">{p.score.toFixed(1)}</td>
                    <td className="px-8 py-6 text-right">
                      <div className="flex justify-end gap-2">
                        <button onClick={() => onViewPolicy(p)} className="px-4 py-2 rounded-xl bg-white/5 text-gray-400 hover:text-white border border-white/5 text-[10px] font-black uppercase tracking-widest transition-all">Review</button>
                        <button onClick={() => onDeletePolicy(p.id)} className="p-2.5 rounded-xl bg-red-500/5 text-gray-600 hover:text-red-400 border border-red-500/10 transition-all">
                           <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {activeTab === 'leads' && (
        <div className="bg-black/40 backdrop-blur-2xl rounded-[2.5rem] border border-white/10 overflow-hidden shadow-2xl animate-in fade-in slide-in-from-top-4">
          <div className="px-8 py-6 border-b border-white/10 flex items-center justify-between bg-white/[0.02]">
            <h3 className="font-bold text-xl tracking-tighter text-white">Global lead authority</h3>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="text-gray-500 text-[10px] font-bold tracking-widest border-b border-white/5 bg-black/40">
                  <th className="px-8 py-5 uppercase">Business</th>
                  <th className="px-8 py-5 uppercase">Contact</th>
                  <th className="px-8 py-5 uppercase">Workflow</th>
                  <th className="px-8 py-5 text-right uppercase">Action</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-white/5">
                {leads.length === 0 ? (
                  <tr><td colSpan={5} className="px-8 py-20 text-center text-gray-500 font-bold italic tracking-wider uppercase text-xs">System ready. Awaiting quotes...</td></tr>
                ) : leads.map((l) => (
                  <tr key={l.id} className="hover:bg-white/[0.03] transition-colors group">
                    <td className="px-8 py-6">
                      <div className="text-sm font-bold text-white">{l.businessName}</div>
                      <div className="text-[10px] text-gray-600 font-medium">{l.city || 'Central System'}</div>
                    </td>
                    <td className="px-8 py-6">
                      <div className="text-sm font-bold text-white">{l.contactName}</div>
                      <div className="text-[10px] text-gray-500 font-mono lowercase tracking-tighter">{l.contactEmail}</div>
                    </td>
                    <td className="px-8 py-6">
                       <select 
                        value={l.status} 
                        onChange={(e) => onStatusChange(l.id, e.target.value as any)}
                        className="bg-black border border-white/10 rounded-xl px-4 py-2 text-[10px] font-black tracking-widest uppercase text-yellow-400 focus:outline-none focus:border-yellow-400 transition-all cursor-pointer"
                       >
                         <option value="New">New lead</option>
                         <option value="In Review">Under review</option>
                         <option value="Quoted">Quoted</option>
                         <option value="Closed">Closed box</option>
                       </select>
                    </td>
                    <td className="px-8 py-6 text-right">
                       <button onClick={() => onDeleteLead(l.id)} className="p-2.5 rounded-xl bg-red-500/5 text-gray-600 hover:text-red-400 border border-red-500/10 transition-all">
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                        </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {activeTab === 'activity' && (
        <div className="max-w-3xl mx-auto space-y-6 animate-in fade-in slide-in-from-top-4">
          <div className="bg-black/40 backdrop-blur-3xl p-10 rounded-[3rem] border border-white/10 shadow-2xl">
            <h3 className="text-2xl font-black tracking-tighter text-white mb-8">Live activity log</h3>
            <div className="space-y-4">
              {activityLog.map((log, i) => (
                <div key={log.id} className="flex items-center justify-between p-5 bg-white/[0.02] border border-white/5 rounded-2xl group hover:bg-white/[0.04] transition-all">
                  <div className="flex items-center gap-4">
                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-black text-[10px] tracking-widest uppercase border ${log.type === 'Audit' ? 'bg-yellow-400/10 border-yellow-400/20 text-yellow-400' : 'bg-blue-400/10 border-blue-400/20 text-blue-400'}`}>
                      {log.type.charAt(0)}
                    </div>
                    <div>
                      <p className="text-sm font-bold text-white group-hover:text-yellow-400 transition-colors">{log.title}</p>
                      <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest">New {log.type} received</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="text-[10px] text-gray-600 font-black uppercase tracking-widest">{log.date}</p>
                    <p className={`text-[9px] font-black uppercase tracking-[0.2em] mt-1 ${log.status === 'Poor' || log.status === 'New' ? 'text-red-400' : 'text-green-400'}`}>{log.status}</p>
                  </div>
                </div>
              ))}
              {activityLog.length === 0 && (
                <p className="text-center text-gray-600 font-bold tracking-widest py-10 uppercase text-xs italic">Awaiting activity from customers...</p>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const StatCard: React.FC<{ title: string; value: number; color: 'gray' | 'blue' | 'green' | 'red'; isPercent?: boolean }> = ({ title, value, color, isPercent }) => {
  const colorMap: any = {
    blue: 'text-blue-400 bg-blue-400/10 border-blue-400/20 shadow-blue-400/5',
    green: 'text-green-400 bg-green-500/10 border-green-500/20 shadow-green-500/5',
    red: 'text-red-400 bg-red-500/10 border-red-500/20 shadow-red-500/5',
    gray: 'text-gray-300 bg-white/5 border-white/10 shadow-black/20'
  };

  return (
    <div className="bg-black/30 backdrop-blur-xl p-8 rounded-[2rem] border border-white/10 flex flex-col gap-1 shadow-xl group hover:border-white/20 transition-all text-left">
      <p className="text-gray-500 text-[9px] font-black uppercase tracking-[0.2em]">{title}</p>
      <div className="flex items-baseline gap-1">
        <p className="text-4xl font-black text-white">{value}</p>
        {isPercent && <span className="text-lg font-black text-gray-600 tracking-tighter uppercase">%</span>}
      </div>
      <div className={`mt-4 w-full h-1 rounded-full overflow-hidden bg-white/5 border border-white/5`}>
        <div className={`h-full ${colorMap[color].split(' ')[0]} animate-pulse`} style={{ width: `${Math.min(value, 100)}%` }} />
