import { openDB, IDBPDatabase } from 'idb';
import { PremiumUser, PremiumRequest } from '../types';

const DB_NAME = 'TheInsuranceBossDB';
const DB_VERSION = 5; // Incrementing version for premium_requests store
const STORE_POLICIES = 'policies';
const STORE_LEADS = 'leads';
const STORE_RECYCLE_LEADS = 'recycle_leads';
const STORE_RECYCLE_POLICIES = 'recycle_policies';
const STORE_PREMIUM_USERS = 'premium_users';
const STORE_PREMIUM_REQUESTS = 'premium_requests';

let dbPromise: Promise<IDBPDatabase>;

const getDB = () => {
  if (!dbPromise) {
    dbPromise = openDB(DB_NAME, DB_VERSION, {
      upgrade(db, oldVersion) {
        if (!db.objectStoreNames.contains(STORE_POLICIES)) {
          db.createObjectStore(STORE_POLICIES, { keyPath: 'id' });
        }
        if (!db.objectStoreNames.contains(STORE_LEADS)) {
          db.createObjectStore(STORE_LEADS, { keyPath: 'id' });
        }
        if (!db.objectStoreNames.contains(STORE_RECYCLE_LEADS)) {
          db.createObjectStore(STORE_RECYCLE_LEADS, { keyPath: 'id' });
        }
        if (!db.objectStoreNames.contains(STORE_RECYCLE_POLICIES)) {
          db.createObjectStore(STORE_RECYCLE_POLICIES, { keyPath: 'id' });
        }
        if (!db.objectStoreNames.contains(STORE_PREMIUM_USERS)) {
          db.createObjectStore(STORE_PREMIUM_USERS, { keyPath: 'id' });
        }
        if (!db.objectStoreNames.contains(STORE_PREMIUM_REQUESTS)) {
          db.createObjectStore(STORE_PREMIUM_REQUESTS, { keyPath: 'id' });
        }
      },
    });
  }
  return dbPromise;
};

export const storage = {
  // Policy Methods
  async savePolicy(policy: any) {
    const db = await getDB();
    await db.put(STORE_POLICIES, policy);
  },
  async getPolicies() {
    const db = await getDB();
    return db.getAll(STORE_POLICIES);
  },
  async deletePolicy(id: string) {
    const db = await getDB();
    await db.delete(STORE_POLICIES, id);
  },
  // Lead Methods
  async saveLead(lead: any) {
    const db = await getDB();
    await db.put(STORE_LEADS, lead);
  },
  async getLeads() {
    const db = await getDB();
    return db.getAll(STORE_LEADS);
  },
  async deleteLead(id: string) {
    const db = await getDB();
    await db.delete(STORE_LEADS, id);
  },
  // Recycle Bin Methods
  async moveToRecycle(lead: any) {
    const db = await getDB();
    const tx = db.transaction([STORE_LEADS, STORE_RECYCLE_LEADS], 'readwrite');
    await tx.objectStore(STORE_LEADS).delete(lead.id);
    await tx.objectStore(STORE_RECYCLE_LEADS).put(lead);
    await tx.done;
  },
  async getRecycledLeads() {
    const db = await getDB();
    return db.getAll(STORE_RECYCLE_LEADS);
  },
  async restoreFromRecycle(lead: any) {
    const db = await getDB();
    const tx = db.transaction([STORE_LEADS, STORE_RECYCLE_LEADS], 'readwrite');
    await tx.objectStore(STORE_RECYCLE_LEADS).delete(lead.id);
    await tx.objectStore(STORE_LEADS).put(lead);
    await tx.done;
  },
  async permanentDeleteLead(id: string) {
    const db = await getDB();
    await db.delete(STORE_RECYCLE_LEADS, id);
  },
  // Policy Recycle
  async moveToRecyclePolicy(policy: any) {
    const db = await getDB();
    const tx = db.transaction([STORE_POLICIES, STORE_RECYCLE_POLICIES], 'readwrite');
    await tx.objectStore(STORE_POLICIES).delete(policy.id);
    await tx.objectStore(STORE_RECYCLE_POLICIES).put(policy);
    await tx.done;
  },
  async getRecycledPolicies() {
    const db = await getDB();
    return db.getAll(STORE_RECYCLE_POLICIES);
  },
  async restoreFromRecyclePolicy(policy: any) {
    const db = await getDB();
    const tx = db.transaction([STORE_POLICIES, STORE_RECYCLE_POLICIES], 'readwrite');
    await tx.objectStore(STORE_RECYCLE_POLICIES).delete(policy.id);
    await tx.objectStore(STORE_POLICIES).put(policy);
    await tx.done;
  },
  async permanentDeletePolicy(id: string) {
    const db = await getDB();
    await db.delete(STORE_RECYCLE_POLICIES, id);
  },
  // Premium User Management
  async addPremiumUser(user: PremiumUser) {
    const db = await getDB();
    await db.put(STORE_PREMIUM_USERS, user);
  },
  async getPremiumUsers() {
    const db = await getDB();
    return db.getAll(STORE_PREMIUM_USERS);
  },
  async deletePremiumUser(id: string) {
    const db = await getDB();
    await db.delete(STORE_PREMIUM_USERS, id);
  },
  async validatePremiumUser(username: string, password: string): Promise<boolean> {
    const users = await this.getPremiumUsers();
    return users.some(u => u.username === username && u.password === password);
  },
  // Premium Request Management
  async savePremiumRequest(request: PremiumRequest) {
    const db = await getDB();
    await db.put(STORE_PREMIUM_REQUESTS, request);
  },
  async getPremiumRequests() {
    const db = await getDB();
    return db.getAll(STORE_PREMIUM_REQUESTS);
  },
  async deletePremiumRequest(id: string) {
    const db = await getDB();
    await db.delete(STORE_PREMIUM_REQUESTS, id);
  },
  // Maintenance
  async clearAll() {
    const db = await getDB();
    const stores = [STORE_POLICIES, STORE_LEADS, STORE_RECYCLE_LEADS, STORE_RECYCLE_POLICIES, STORE_PREMIUM_USERS, STORE_PREMIUM_REQUESTS];
    for (const s of stores) await db.clear(s);
  },
  async exportBackup() {
    const policies = await this.getPolicies();
    const leads = await this.getLeads();
    const recycledLeads = await this.getRecycledLeads();
    const recycledPolicies = await this.getRecycledPolicies();
    const premiumUsers = await this.getPremiumUsers();
    const premiumRequests = await this.getPremiumRequests();
    return JSON.stringify({ 
      policies, 
      leads, 
      recycledLeads, 
      recycledPolicies, 
      premiumUsers,
      premiumRequests,
      version: DB_VERSION, 
      timestamp: new Date().toISOString() 
    });
  },
  async importBackup(jsonString: string) {
    const data = JSON.parse(jsonString);
    const db = await getDB();
    const tx = db.transaction([STORE_POLICIES, STORE_LEADS, STORE_RECYCLE_LEADS, STORE_RECYCLE_POLICIES, STORE_PREMIUM_USERS, STORE_PREMIUM_REQUESTS], 'readwrite');
    for (const p of (data.policies || [])) await tx.objectStore(STORE_POLICIES).put(p);
    for (const l of (data.leads || [])) await tx.objectStore(STORE_LEADS).put(l);
    for (const r of (data.recycledLeads || [])) await tx.objectStore(STORE_RECYCLE_LEADS).put(r);
    for (const rp of (data.recycledPolicies || [])) await tx.objectStore(STORE_RECYCLE_POLICIES).put(rp);
    for (const u of (data.premiumUsers || [])) await tx.objectStore(STORE_PREMIUM_USERS).put(u);
    for (const pr of (data.premiumRequests || [])) await tx.objectStore(STORE_PREMIUM_REQUESTS).put(pr);
    await tx.done;
  }
};

import React, { useState, useEffect } from 'react';
import * as ReactRouterDOM from 'react-router-dom';
import Header from './components/Header';
import UploadSection from './components/UploadSection';
import AnalysisResult from './components/AnalysisResult';
import AdminDashboard from './components/AdminDashboard';
import AdminLogin from './components/AdminLogin';
import WizardForm from './components/WizardForm';
import { PolicyAnalysis, QuoteRequest, PremiumRequest } from './types';
import { storage } from './services/storage';
import { bossServer } from './services/serverService';

const { HashRouter, Routes, Route } = ReactRouterDOM;

// Wrapper to handle main app view states
const MainView: React.FC<{
  showWizard: boolean,
  setShowWizard: (v: boolean) => void,
  allPolicies: PolicyAnalysis[],
  currentAnalysis: PolicyAnalysis | null,
  handleNewAnalysis: (a: PolicyAnalysis, details: {name: string, email: string}) => void,
  handleNewLead: (l: QuoteRequest) => void,
  handleNewPremiumRequest: (r: PremiumRequest) => void,
  setCurrentAnalysis: (a: PolicyAnalysis | null) => void,
}> = ({ showWizard, setShowWizard, allPolicies, currentAnalysis, handleNewAnalysis, handleNewLead, handleNewPremiumRequest, setCurrentAnalysis }) => {

  if (showWizard) {
    return <WizardForm onSubmit={handleNewLead} onCancel={() => setShowWizard(false)} />;
  }

  if (currentAnalysis) {
    return (
      <AnalysisResult 
        analysis={currentAnalysis} 
        onReset={() => setCurrentAnalysis(null)} 
        onOpenWizard={() => setShowWizard(true)}
      />
    );
  }

  return (
    <UploadSection 
      onAnalysisComplete={handleNewAnalysis} 
      existingPolicies={allPolicies}
      onOpenWizard={() => setShowWizard(true)}
      onPremiumRequest={handleNewPremiumRequest}
    />
  );
};

const App: React.FC = () => {
  const [isAdmin, setIsAdmin] = useState(false);
  const [allPolicies, setAllPolicies] = useState<PolicyAnalysis[]>([]);
  const [allLeads, setAllLeads] = useState<QuoteRequest[]>([]);
  const [recycledLeads, setRecycledLeads] = useState<QuoteRequest[]>([]);
  const [recycledPolicies, setRecycledPolicies] = useState<PolicyAnalysis[]>([]);
  const [premiumRequests, setPremiumRequests] = useState<PremiumRequest[]>([]);
  const [currentAnalysis, setCurrentAnalysis] = useState<PolicyAnalysis | null>(null);
  const [showWizard, setShowWizard] = useState(false);
  const [isEmbedded, setIsEmbedded] = useState(false);

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const embedMode = params.get('embed') === 'true' || window.location.href.includes('embed=true');
    setIsEmbedded(embedMode);

    const loadData = async () => {
      try {
        const cloudData = await bossServer.fetchGlobalVault();
        if (cloudData.policies) {
          for (const p of cloudData.policies) await storage.savePolicy(p);
        }
        if (cloudData.leads) {
          for (const l of cloudData.leads) await storage.saveLead(l);
        }

        const p = await storage.getPolicies();
        const l = await storage.getLeads();
        const rl = await storage.getRecycledLeads();
        const rp = await storage.getRecycledPolicies();
        const pr = await storage.getPremiumRequests();
        setAllPolicies(p);
        setAllLeads(l);
        setRecycledLeads(rl);
        setRecycledPolicies(rp);
        setPremiumRequests(pr);
      } catch (err) {
        console.error("Silent Sync Warning:", err);
      }
    };
    loadData();
  }, []);

  const handleGoHome = () => {
    window.location.hash = '#/';
    setCurrentAnalysis(null);
    setShowWizard(false);
  };

  const handleNewAnalysis = async (analysis: PolicyAnalysis, details: {name: string, email: string}) => {
    setCurrentAnalysis(analysis);
    setShowWizard(false);

    storage.savePolicy(analysis).then(() => {
      setAllPolicies(prev => {
        const exists = prev.some(p => p.id === analysis.id);
        return exists ? prev : [analysis, ...prev];
      });
      bossServer.upstream('policy', analysis);
    });

    const autoLead: QuoteRequest = {
      id: `auto-${analysis.id}`,
      submissionDate: new Date().toLocaleString(),
      status: 'New',
      businessName: analysis.insuredName || details.name,
      fein: analysis.fein || 'EXTRACTED',
      yearsInBusiness: 'EXTRACTED',
      address1: analysis.insuredAddress || '',
      city: 'EXTRACTED',
      state: 'EXTRACTED',
      zip: 'EXTRACTED',
      country: 'United States',
      industries: analysis.industry ? [analysis.industry] : ['Policy Audit'],
      hasActiveCoverage: true,
      knowsPremium: false,
      hasDeclPage: true,
      contactName: details.name || analysis.insuredName || 'Insured',
      contactEmail: details.email || analysis.contactEmail || '',
      contactPhone: analysis.contactPhone || '',
      sourcePolicyId: analysis.id
    };

    handleNewLead(autoLead);
  };

  const handleNewLead = async (lead: QuoteRequest) => {
    setAllLeads(prev => {
      const filtered = prev.filter(l => l.id !== lead.id);
      return [lead, ...filtered];
    });
    storage.saveLead(lead);
    bossServer.upstream('lead', lead);
  };

  const handleNewPremiumRequest = async (request: PremiumRequest) => {
    await storage.savePremiumRequest(request);
    setPremiumRequests(prev => [request, ...prev]);
  };

  const handleDeletePolicy = async (id: string) => {
    const policyToRecycle = allPolicies.find(p => p.id === id);
    if (policyToRecycle) {
      await storage.moveToRecyclePolicy(policyToRecycle);
      setAllPolicies(prev => prev.filter(p => p.id !== id));
      setRecycledPolicies(prev => [policyToRecycle, ...prev]);
    }
  };

  const handleRestorePolicy = async (id: string) => {
    const policyToRestore = recycledPolicies.find(p => p.id === id);
    if (policyToRestore) {
      await storage.restoreFromRecyclePolicy(policyToRestore);
      setRecycledPolicies(prev => prev.filter(p => p.id !== id));
      setAllPolicies(prev => [policyToRestore, ...prev]);
    }
  };

  const handlePermanentDeletePolicy = async (id: string) => {
    await storage.permanentDeletePolicy(id);
    setRecycledPolicies(prev => prev.filter(p => p.id !== id));
  };

  const handleDeleteLead = async (id: string) => {
    const leadToRecycle = allLeads.find(l => l.id === id);
    if (leadToRecycle) {
      await storage.moveToRecycle(leadToRecycle);
      setAllLeads(prev => prev.filter(l => l.id !== id));
      setRecycledLeads(prev => [leadToRecycle, ...prev]);
    }
  };

  const handleRestoreLead = async (id: string) => {
    const leadToRestore = recycledLeads.find(l => l.id === id);
    if (leadToRestore) {
      await storage.restoreFromRecycle(leadToRestore);
      setRecycledLeads(prev => prev.filter(l => l.id !== id));
      setAllLeads(prev => [leadToRestore, ...prev]);
    }
  };

  const handlePermanentDeleteLead = async (id: string) => {
    await storage.permanentDeleteLead(id);
    setRecycledLeads(prev => prev.filter(l => l.id !== id));
  };

  const handleDeletePremiumRequest = async (id: string) => {
    await storage.deletePremiumRequest(id);
    setPremiumRequests(prev => prev.filter(r => r.id !== id));
  };

  const handleStatusChange = async (id: string, status: QuoteRequest['status']) => {
    const lead = allLeads.find(l => l.id === id);
    if (lead) {
      const updated = { ...lead, status };
      await storage.saveLead(updated);
      setAllLeads(prev => prev.map(l => l.id === id ? updated : l));
      await bossServer.upstream('lead', updated);
    }
  };

  const handleImport = async (json: string) => {
    await storage.importBackup(json);
    const p = await storage.getPolicies();
    const l = await storage.getLeads();
    const rl = await storage.getRecycledLeads();
    const rp = await storage.getRecycledPolicies();
    const pr = await storage.getPremiumRequests();
    setAllPolicies(p);
    setAllLeads(l);
    setRecycledLeads(rl);
    setRecycledPolicies(rp);
    setPremiumRequests(pr);
  };

  return (
    <HashRouter>
      <div className="min-h-screen bg-transparent text-white border-none">
        {!isEmbedded && (
          <Header 
            isAdmin={isAdmin} 
            setIsAdmin={setIsAdmin} 
            onOpenWizard={() => { setCurrentAnalysis(null); setShowWizard(true); }} 
            onGoHome={handleGoHome}
          />
        )}

        <main className={`container mx-auto px-4 max-w-6xl bg-transparent ${isEmbedded ? 'py-0' : 'py-8'}`}>
          <Routes>
            <Route path="/" element={
              <MainView 
                showWizard={showWizard}
                setShowWizard={setShowWizard}
                allPolicies={allPolicies}
                currentAnalysis={currentAnalysis}
                handleNewAnalysis={handleNewAnalysis}
                handleNewLead={handleNewLead}
                handleNewPremiumRequest={handleNewPremiumRequest}
                setCurrentAnalysis={setCurrentAnalysis}
              />
            } />

            <Route path="/admin" element={
              isAdmin ? (
                <AdminDashboard 
                  policies={allPolicies} 
                  leads={allLeads}
                  recycledLeads={recycledLeads}
                  recycledPolicies={recycledPolicies}
                  premiumRequests={premiumRequests}
                  onDeletePolicy={handleDeletePolicy}
                  onRestorePolicy={handleRestorePolicy}
                  onPermanentDeletePolicy={handlePermanentDeletePolicy}
                  onDeleteLead={handleDeleteLead}
                  onRestoreLead={handleRestoreLead}
                  onPermanentDeleteLead={handlePermanentDeleteLead}
                  onDeletePremiumRequest={handleDeletePremiumRequest}
                  onStatusChange={handleStatusChange}
                  onImport={handleImport}
                  onViewPolicy={(p) => {
                    setCurrentAnalysis(p);
                    setShowWizard(false);
                    window.location.hash = '#/';
                  }}
                />
              ) : (
                <AdminLogin onLogin={() => setIsAdmin(true)} />
              )
            } />
          </Routes>
        </main>

        {!isEmbedded && (
          <footer className="py-12 border-none text-center text-gray-500 text-sm bg-transparent">
            <p>© {new Date().getFullYear()} The Insurance Boss Policy Review Tool.</p>
          </footer>
        )}
      </div>
    </HashRouter>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { analyzePolicy, calculateFileHash } from '../services/geminiService';
import { PolicyAnalysis, PremiumRequest } from '../types';
import { storage } from '../services/storage';

interface UploadSectionProps {
  onAnalysisComplete: (analysis: PolicyAnalysis, details: { name: string; email: string }) => void;
  existingPolicies: PolicyAnalysis[];
  onOpenWizard: () => void;
  onPremiumRequest: (request: PremiumRequest) => void;
}

const FREE_LIMIT = 5;

const UploadSection: React.FC<UploadSectionProps> = ({ onAnalysisComplete, existingPolicies, onOpenWizard, onPremiumRequest }) => {
  const [isUploading, setIsUploading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [userName, setUserName] = useState('');
  const [userEmail, setUserEmail] = useState('');

  // Premium/Limit State
  const [uploadCount, setUploadCount] = useState(0);
  const [isPremium, setIsPremium] = useState(false);
  const [showPremiumLogin, setShowPremiumLogin] = useState(false);
  const [premiumUsername, setPremiumUsername] = useState('');
  const [premiumPassword, setPremiumPassword] = useState('');
  const [loginError, setLoginError] = useState('');

  // Premium Request Form State
  const [showRequestForm, setShowRequestForm] = useState(false);
  const [reqUsername, setReqUsername] = useState('');
  const [reqPassword, setReqPassword] = useState('');
  const [reqEmail, setReqEmail] = useState('');
  const [reqStatus, setReqStatus] = useState<'idle' | 'submitting' | 'done'>('idle');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const progressIntervalRef = useRef<number | null>(null);
  const abortControllerRef = useRef<AbortController | null>(null);

  useEffect(() => {
    // Load local count
    const count = parseInt(localStorage.getItem('boss_upload_count') || '0');
    const premiumStatus = localStorage.getItem('boss_premium_session') === 'active';
    setUploadCount(count);
    setIsPremium(premiumStatus);

    return () => {
      if (progressIntervalRef.current) clearInterval(progressIntervalRef.current);
    };
  }, []);

  const handleStop = () => {
    if (progressIntervalRef.current) clearInterval(progressIntervalRef.current);
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }
    setIsUploading(false);
    setProgress(0);
  };

  const startProgressSimulation = (isFastTrack: boolean = false) => {
    setProgress(0);
    if (progressIntervalRef.current) clearInterval(progressIntervalRef.current);

    const intervalSpeed = isFastTrack ? 10 : 100;

    progressIntervalRef.current = window.setInterval(() => {
      setProgress(prev => {
        if (prev >= 98) {
          if (!isFastTrack) return 98;
          return 100;
        }
        const increment = isFastTrack ? 15 : (prev < 40 ? 3 : prev < 70 ? 0.8 : 0.2);
        return Math.min(prev + increment, 100);
      });
    }, intervalSpeed);
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Check Limit
    if (!isPremium && uploadCount >= FREE_LIMIT) {
      alert("Boss, you've reached your free audit limit. Log in for premium access.");
      setShowPremiumLogin(true);
      return;
    }

    setIsUploading(true);
    startProgressSimulation();
    abortControllerRef.current = new AbortController();

    try {
      const base64Data = await new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onloadend = () => resolve((reader.result as string).split(',')[1]);
        reader.onerror = () => reject(new Error("Failed to read file"));
        reader.readAsDataURL(file);
      });

      const fileHash = await calculateFileHash(base64Data);
      const existingMatch = existingPolicies.find(p => p.fileHash === fileHash);

      const userDetails = { name: userName, email: userEmail };

      if (existingMatch) {
        startProgressSimulation(true); 
        await new Promise(r => setTimeout(r, 800)); 
        if (progressIntervalRef.current) clearInterval(progressIntervalRef.current);
        setProgress(100);
        setTimeout(() => {
          onAnalysisComplete(existingMatch, userDetails);
          setIsUploading(false);
          setProgress(0);
        }, 300);
        return;
      }

      // Perform AI Analysis
      const analysis = await analyzePolicy(file, abortControllerRef.current.signal);

      // Increment count
      if (!isPremium) {
        const newCount = uploadCount + 1;
        setUploadCount(newCount);
        localStorage.setItem('boss_upload_count', newCount.toString());
      }

      if (progressIntervalRef.current) clearInterval(progressIntervalRef.current);
      setProgress(100);

      setTimeout(() => {
        onAnalysisComplete(analysis, userDetails);
        setIsUploading(false);
        setProgress(0);
      }, 500);

    } catch (err: any) {
      if (err.name === 'AbortError') return;
      console.error("Technical Audit Failure:", err);
      setIsUploading(false);
      setProgress(0);
      if (progressIntervalRef.current) clearInterval(progressIntervalRef.current);
      alert(`Audit Failure: ${err.message || "Unknown error occurred on Boss Central Engine."}`);
    } finally {
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  const handlePremiumLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    const isValid = await storage.validatePremiumUser(premiumUsername, premiumPassword);
    if (isValid) {
      setIsPremium(true);
      localStorage.setItem('boss_premium_session', 'active');
      setShowPremiumLogin(false);
      setLoginError('');
    } else {
      setLoginError('Invalid credentials. Contact the Boss.');
    }
  };

  const handleSubmitPremiumRequest = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!reqUsername || !reqPassword || !reqEmail) return;
    setReqStatus('submitting');

    const request: PremiumRequest = {
      id: Math.random().toString(36).substr(2, 9),
      username: reqUsername,
      password: reqPassword,
      email: reqEmail,
      requestDate: new Date().toLocaleString()
    };

    // Simulate short delay
    await new Promise(r => setTimeout(r, 1000));
    onPremiumRequest(request);
    setReqStatus('done');
    setReqUsername('');
    setReqPassword('');
    setReqEmail('');
    setTimeout(() => {
      setReqStatus('idle');
      setShowRequestForm(false);
    }, 2000);
  };

  const isFormValid = userName.trim() !== '' && userEmail.trim().includes('@');
  const isLimitReached = !isPremium && uploadCount >= FREE_LIMIT;

  return (
    <div className="flex flex-col items-center justify-center text-center py-4 px-4 bg-transparent max-w-5xl mx-auto animate-in fade-in duration-1000">

      {/* HEADER */}
      <div className="mb-12 space-y-4">
        <h1 className="text-6xl md:text-8xl font-black leading-[1.0] tracking-tighter text-white">
          Is Your Policy <br />
          <span className="text-yellow-400">Protecting</span> You?
        </h1>
        <p className="text-gray-400 text-lg md:text-xl font-bold max-w-2xl mx-auto leading-tight opacity-90">
          Upload your policy for an instant technical audit (5 free quotes). Identify gaps before they identify you.
        </p>
      </div>

      {isLimitReached && !showPremiumLogin && (
        <div className="mb-10 w-full max-w-2xl bg-red-500/10 border border-red-500/20 p-8 rounded-3xl animate-in zoom-in-95">
          <h3 className="text-xl font-black text-white mb-2">Limit reached, Boss.</h3>
          <p className="text-gray-400 text-sm font-bold mb-6">
            You have used your 5 free audits. To continue inspecting more policies, please log in with your personal premium account.
          </p>
          <div className="flex flex-col sm:flex-row gap-4 justify-center">
             <button 
              onClick={() => setShowPremiumLogin(true)}
              className="px-8 py-3 bg-yellow-400 text-black font-black text-xs rounded-xl hover:bg-yellow-500 uppercase tracking-widest shadow-lg transition-all"
             >
               Log in to premium
             </button>
             <button 
              onClick={() => setShowRequestForm(true)}
              className="px-8 py-3 bg-white/5 border border-white/10 text-gray-400 font-black text-xs rounded-xl hover:bg-white/10 uppercase tracking-widest transition-all"
             >
               Ask the Boss for your premium access
             </button>
          </div>
        </div>
      )}

      {showPremiumLogin && (
        <div className="mb-10 w-full max-w-md bg-[#121212] border border-white/10 p-8 rounded-3xl shadow-2xl animate-in fade-in slide-in-from-top-4">
          <h3 className="text-lg font-black text-white mb-6 uppercase tracking-widest">Premium login</h3>
          <form onSubmit={handlePremiumLogin} className="space-y-4 text-left">
            <div>
              <label className="text-[10px] font-black text-gray-500 tracking-widest uppercase ml-1">Username</label>
              <input 
                type="text"
                value={premiumUsername}
                onChange={(e) => setPremiumUsername(e.target.value)}
                className="w-full bg-black border border-white/10 rounded-xl px-4 py-3 text-sm focus:border-yellow-400 outline-none text-white"
                placeholder="BossUsername"
              />
            </div>
            <div>
              <label className="text-[10px] font-black text-gray-500 tracking-widest uppercase ml-1">Password</label>
              <input 
                type="password"
                value={premiumPassword}
                onChange={(e) => setPremiumPassword(e.target.value)}
                className="w-full bg-black border border-white/10 rounded-xl px-4 py-3 text-sm focus:border-yellow-400 outline-none text-white"
                placeholder="••••••••"
              />
            </div>
            {loginError && <p className="text-red-400 text-[10px] font-bold uppercase">{loginError}</p>}
            <div className="pt-2 flex flex-col gap-3">
              <button 
                type="submit"
                className="w-full bg-yellow-400 text-black font-black py-3 rounded-xl hover:bg-yellow-500 uppercase text-xs tracking-widest shadow-xl transition-all"
              >
                Authenticate access
              </button>
              <button 
                type="button"
                onClick={() => setShowPremiumLogin(false)}
                className="w-full text-center text-gray-500 text-[10px] font-black uppercase hover:text-white transition-all"
              >
                Back to audit
              </button>
            </div>
          </form>
        </div>
      )}

      {!showPremiumLogin && !showRequestForm && (
        <>
          <div className="w-full max-w-3xl grid grid-cols-1 md:grid-cols-2 gap-6 mb-10">
            <div className="text-left space-y-2">
              <label className="text-[10px] font-black text-gray-500 tracking-widest uppercase ml-1">Full name</label>
              <input 
                type="text"
                value={userName}
                onChange={(e) => setUserName(e.target.value)}
                placeholder="Enter your name"
                className="w-full bg-[#121212] border border-white/10 rounded-xl px-6 py-4 text-sm font-medium focus:outline-none focus:border-yellow-400/30 transition-all text-white placeholder:text-gray-700"
              />
            </div>
            <div className="text-left space-y-2">
              <label className="text-[10px] font-black text-gray-500 tracking-widest uppercase ml-1">Email address</label>
              <input 
                type="email"
                value={userEmail}
                onChange={(e) => setUserEmail(e.target.value)}
                placeholder="boss@example.com"
                className="w-full bg-[#121212] border border-white/10 rounded-xl px-6 py-4 text-sm font-medium focus:outline-none focus:border-yellow-400/30 transition-all text-white placeholder:text-gray-700"
              />
            </div>
          </div>

          <div 
            onClick={() => !isUploading && isFormValid && !isLimitReached && fileInputRef.current?.click()}
            className={`w-full max-w-4xl min-h-[400px] rounded-[3.5rem] border border-white/10 flex flex-col items-center justify-center p-12 transition-all relative overflow-hidden bg-[#0d0d0d] shadow-2xl
              ${!isUploading && isFormValid && !isLimitReached ? 'cursor-pointer hover:bg-white/[0.02] active:scale-[0.99] border-white/20' : 'opacity-80 cursor-default'}
            `}
          >
            <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" accept="application/pdf" />

            {isUploading ? (
              <div className="w-full max-w-xl space-y-12 flex flex-col items-center animate-in fade-in zoom-in-95">
                <div className="relative w-32 h-32 mb-4">
                  <div className="absolute inset-0 border-[8px] border-yellow-400/10 rounded-full" />
                  <div className="absolute inset-0 border-[8px] border-yellow-400 border-t-transparent rounded-full animate-spin" />
                  <div className="absolute inset-0 flex items-center justify-center">
                    <span className="text-yellow-400 font-black text-2xl">{Math.round(progress)}%</span>
                  </div>
                </div>
                <div className="w-full space-y-10">
                  <div className="space-y-3">
                    <div className="flex justify-end pr-2">
                       <span className="text-yellow-400 font-black text-xs tracking-widest">{progress.toFixed(1)}%</span>
                    </div>
                    <div className="h-4 w-full bg-white/5 rounded-full p-1 border border-white/10 overflow-hidden shadow-inner">
                      <div 
                        className="h-full bg-yellow-400 rounded-full transition-all duration-300 relative shadow-[0_0_25px_rgba(250,204,21,0.5)]" 
                        style={{ width: `${progress}%` }}
                      >
                        <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/30 to-transparent animate-[shimmer_2s_infinite]" />
                      </div>
                    </div>
                  </div>
                  <button 
                    onClick={(e) => { e.stopPropagation(); handleStop(); }}
                    className="px-10 py-4 bg-yellow-400 text-black font-black text-[11px] tracking-widest uppercase rounded-2xl hover:bg-yellow-500 transition-all active:scale-95 shadow-[0_10px_20px_rgba(250,204,21,0.2)]"
                  >
                    Stop audit
                  </button>
                </div>
              </div>
            ) : (
              <div className="space-y-12 flex flex-col items-center">
                <div className="bg-white/[0.03] p-10 rounded-[2rem] border border-white/5 flex items-center justify-center shadow-2xl transition-transform duration-500 group">
                  <div className="w-14 h-14 rounded-xl border-2 border-yellow-400/40 flex items-center justify-center">
                    <svg className="w-8 h-8 text-yellow-400" fill="currentColor" viewBox="0 0 24 24">
                      <path d="M11 15h2v-4h3l-4-4-4 4h3v4z"/>
                      <path d="M20 18H4v-7H2v7c0 1.1.9 2 2 2h16c1.1 0 2-.9 2-2v-7h-2v7z"/>
                    </svg>
                  </div>
                </div>
                <div className="text-center">
                  <h3 className="text-5xl md:text-7xl font-black tracking-tighter leading-none text-white">
                    {isLimitReached ? 'Limit reached' : isFormValid ? 'Click to upload policy' : 'Enter details to audit'}
                  </h3>
                </div>
              </div>
            )}
          </div>
        </>
      )}

      {/* FOOTER ACTIONS */}
      {!isUploading && (
        <div className="mt-12 flex flex-col items-center gap-8 w-full">
          <button 
            onClick={onOpenWizard}
            className="px-24 py-6 rounded-2xl bg-yellow-400 text-black font-black text-sm tracking-widest hover:bg-yellow-500 transition-all active:scale-95 shadow-[0_15px_30px_rgba(250,204,21,0.3)] uppercase"
          >
            Get a quote
          </button>

          <div className="flex flex-col gap-2 items-center">
            <p className="text-[11px] text-gray-600 font-black uppercase tracking-[0.2em] opacity-80">
              Identify gaps before they identify you.
            </p>
            {!isPremium && (
              <p className="text-[10px] text-yellow-400/50 font-black uppercase tracking-widest">
                {uploadCount} of {FREE_LIMIT} free audits used
              </p>
            )}
          </div>

          {/* ASKING THE BOSS FOR ACCESS SECTION */}
          {showRequestForm ? (
             <div className="w-full max-w-md bg-[#121212] border border-yellow-400/20 p-8 rounded-3xl shadow-2xl animate-in zoom-in-95 mt-8 text-left">
               <h3 className="text-lg font-black text-white mb-6 uppercase tracking-widest">Request Premium Access</h3>
               {reqStatus === 'done' ? (
                  <div className="text-center py-6 text-yellow-400 font-black animate-in fade-in">
                    Access request sent to the Boss vault!
                  </div>
               ) : (
                  <form onSubmit={handleSubmitPremiumRequest} className="space-y-4">
                    <div>
                      <label className="text-[10px] font-black text-gray-500 tracking-widest uppercase ml-1">Proposed Username</label>
                      <input 
                        required
                        type="text"
                        value={reqUsername}
                        onChange={(e) => setReqUsername(e.target.value)}
                        className="w-full bg-black border border-white/10 rounded-xl px-4 py-3 text-sm focus:border-yellow-400 outline-none text-white"
                        placeholder="JohnDoe_Boss"
                      />
                    </div>
                    <div>
                      <label className="text-[10px] font-black text-gray-500 tracking-widest uppercase ml-1">Proposed Password</label>
                      <input 
                        required
                        type="password"
                        value={reqPassword}
                        onChange={(e) => setReqPassword(e.target.value)}
                        className="w-full bg-black border border-white/10 rounded-xl px-4 py-3 text-sm focus:border-yellow-400 outline-none text-white"
                        placeholder="••••••••"
                      />
                    </div>
                    <div>
                      <label className="text-[10px] font-black text-gray-500 tracking-widest uppercase ml-1">Business Email</label>
                      <input 
                        required
                        type="email"
                        value={reqEmail}
                        onChange={(e) => setReqEmail(e.target.value)}
                        className="w-full bg-black border border-white/10 rounded-xl px-4 py-3 text-sm focus:border-yellow-400 outline-none text-white"
                        placeholder="john@example.com"
                      />
                    </div>
                    <div className="pt-2 flex flex-col gap-3">
                      <button 
                        type="submit"
                        disabled={reqStatus === 'submitting'}
                        className="w-full bg-yellow-400 text-black font-black py-3 rounded-xl hover:bg-yellow-500 uppercase text-xs tracking-widest shadow-xl transition-all"
                      >
                        {reqStatus === 'submitting' ? 'Sending request...' : 'Ask the boss for your premium access'}
                      </button>
                      <button 
                        type="button"
                        onClick={() => setShowRequestForm(false)}
                        className="w-full text-center text-gray-500 text-[10px] font-black uppercase hover:text-white transition-all"
                      >
                        Cancel request
                      </button>
                    </div>
                  </form>
               )}
             </div>
          ) : (
            <button 
              onClick={() => setShowRequestForm(true)}
              className="mt-4 text-[10px] font-black text-gray-600 hover:text-yellow-400 uppercase tracking-[0.2em] transition-all border-b border-gray-800 pb-1"
            >
              Ask the boss for your premium access
            </button>
          )}
        </div>
      )}

      <style>{`
        @keyframes shimmer {
          0% { transform: translateX(-100%); }
          100% { transform: translateX(200%); }
        }
      `}</style>
    </div>
  );
};

export default UploadSection;

import React, { useMemo, useState, useEffect } from 'react';
import { PolicyAnalysis, AdminStats, QuoteRequest, PremiumUser, PremiumRequest } from '../types';
import { bossServer } from '../services/serverService';
import { storage } from '../services/storage';

interface AdminDashboardProps {
  policies: PolicyAnalysis[];
  leads: QuoteRequest[];
  recycledLeads: QuoteRequest[];
  recycledPolicies: PolicyAnalysis[];
  premiumRequests: PremiumRequest[];
  onDeletePolicy: (id: string) => void;
  onRestorePolicy: (id: string) => void;
  onPermanentDeletePolicy: (id: string) => void;
  onDeleteLead: (id: string) => void;
  onRestoreLead: (id: string) => void;
  onPermanentDeleteLead: (id: string) => void;
  onDeletePremiumRequest: (id: string) => void;
  onStatusChange: (id: string, status: QuoteRequest['status']) => void;
  onViewPolicy: (p: PolicyAnalysis) => void;
  onImport: (json: string) => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  policies, 
  leads, 
  recycledLeads,
  recycledPolicies,
  premiumRequests,
  onDeletePolicy, 
  onRestorePolicy,
  onPermanentDeletePolicy,
  onDeleteLead, 
  onRestoreLead,
  onPermanentDeleteLead,
  onDeletePremiumRequest,
  onStatusChange, 
  onViewPolicy, 
  onImport 
}) => {
  const [activeTab, setActiveTab] = useState<'policies' | 'leads' | 'activity' | 'recycle' | 'premium'>('policies');
  const [recycleSubTab, setRecycleSubTab] = useState<'leads' | 'audits'>('leads');
  const [serverStatus, setServerStatus] = useState(bossServer.getStatus());

  // Premium User Management
  const [premiumUsers, setPremiumUsers] = useState<PremiumUser[]>([]);
  const [newUsername, setNewUsername] = useState('');
  const [newPassword, setNewPassword] = useState('');

  useEffect(() => {
    bossServer.onStatusChange(() => {
      setServerStatus(bossServer.getStatus());
    });
    loadPremiumUsers();
  }, []);

  const loadPremiumUsers = async () => {
    const users = await storage.getPremiumUsers();
    setPremiumUsers(users);
  };

  const handleCreatePremiumUser = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newUsername || !newPassword) return;

    const newUser: PremiumUser = {
      id: Math.random().toString(36).substr(2, 9),
      username: newUsername,
      password: newPassword,
      createdAt: new Date().toLocaleString()
    };

    await storage.addPremiumUser(newUser);
    setNewUsername('');
    setNewPassword('');
    loadPremiumUsers();
  };

  const handleApproveRequest = async (req: PremiumRequest) => {
    const newUser: PremiumUser = {
      id: Math.random().toString(36).substr(2, 9),
      username: req.username,
      password: req.password,
      createdAt: new Date().toLocaleString()
    };
    await storage.addPremiumUser(newUser);
    await onDeletePremiumRequest(req.id);
    loadPremiumUsers();
  };

  const handleDeletePremiumUser = async (id: string) => {
    await storage.deletePremiumUser(id);
    loadPremiumUsers();
  };

  const stats = useMemo<AdminStats>(() => {
    return {
      totalPolicies: policies.length,
      totalLeads: leads.length,
      reviewed: policies.length,
      goodPolicies: policies.filter(p => p.rating === 'Good').length,
      needsImprovement: policies.filter(p => p.rating === 'Needs Improvement').length,
      needsReview: policies.filter(p => p.rating === 'Poor').length
    };
  }, [policies, leads]);

  const activityLog = useMemo(() => {
    const all = [
      ...policies.map(p => ({ id: p.id, type: 'Audit', title: p.insuredName, date: p.uploadDate, status: p.rating })),
      ...leads.map(l => ({ id: l.id, type: 'Lead', title: l.businessName, date: l.submissionDate, status: l.status }))
    ];
    return all.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()).slice(0, 10);
  }, [policies, leads]);

  return (
    <div className="space-y-10 animate-in fade-in slide-in-from-bottom-2 duration-500 pb-20 text-left bg-transparent">

      {/* GLOBAL COMMAND HEADER */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 px-2">
        <div className="flex items-center gap-6">
          <div>
            <h2 className="text-4xl font-black tracking-tighter text-white">Staff vault</h2>
            <p className="text-gray-500 font-bold uppercase tracking-widest text-[10px]">Command center access</p>
          </div>

          <div className={`flex items-center gap-3 px-5 py-2.5 rounded-2xl border transition-all duration-700 ${serverStatus === 'Online' ? 'bg-green-500/10 border-green-500/20' : 'bg-red-500/10 border-red-500/20'}`}>
            <div className={`w-2.5 h-2.5 rounded-full ${serverStatus === 'Online' ? 'bg-green-400 animate-pulse shadow-[0_0_10px_rgba(74,222,128,0.5)]' : 'bg-red-400'}`} />
            <span className={`text-[10px] font-black uppercase tracking-widest ${serverStatus === 'Online' ? 'text-green-400' : 'text-red-400'}`}>
              Server authority: {serverStatus}
            </span>
          </div>
        </div>

        <div className="flex bg-white/5 backdrop-blur-xl p-1.5 rounded-2xl border border-white/10 overflow-x-auto shadow-2xl">
          <button onClick={() => setActiveTab('policies')} className={`px-6 py-2.5 rounded-xl text-xs font-black transition-all whitespace-nowrap tracking-widest uppercase ${activeTab === 'policies' ? 'bg-yellow-400 text-black shadow-lg' : 'text-gray-400 hover:text-white'}`}>Audits</button>
          <button onClick={() => setActiveTab('leads')} className={`px-6 py-2.5 rounded-xl text-xs font-black transition-all whitespace-nowrap tracking-widest uppercase ${activeTab === 'leads' ? 'bg-yellow-400 text-black shadow-lg' : 'text-gray-400 hover:text-white'}`}>Leads ({leads.length})</button>
          <button onClick={() => setActiveTab('activity')} className={`px-6 py-2.5 rounded-xl text-xs font-black transition-all whitespace-nowrap tracking-widest uppercase ${activeTab === 'activity' ? 'bg-yellow-400 text-black shadow-lg' : 'text-gray-400 hover:text-white'}`}>Activity</button>
          <button onClick={() => setActiveTab('premium')} className={`px-6 py-2.5 rounded-xl text-xs font-black transition-all whitespace-nowrap tracking-widest uppercase ${activeTab === 'premium' ? 'bg-yellow-400 text-black shadow-lg' : 'text-gray-400 hover:text-white'}`}>Premium Access</button>
          <button onClick={() => setActiveTab('recycle')} className={`px-6 py-2.5 rounded-xl text-xs font-black transition-all whitespace-nowrap tracking-widest uppercase flex items-center gap-2 ${activeTab === 'recycle' ? 'bg-red-500 text-white shadow-lg' : 'text-gray-500 hover:text-white'}`}>
            <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
            Recycle Bin
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard title="Total audits" value={stats.totalPolicies} color="gray" />
        <StatCard title="New leads" value={leads.filter(l => l.status === 'New').length} color="blue" />
        <StatCard title="High risk clients" value={stats.needsReview} color="red" />
        <StatCard title="Recycled items" value={recycledLeads.length + recycledPolicies.length} color="red" />
      </div>

      {activeTab === 'policies' && (
        <div className="bg-black/40 backdrop-blur-2xl rounded-[2.5rem] border border-white/10 overflow-hidden shadow-2xl animate-in fade-in slide-in-from-top-4">
          <div className="px-8 py-6 border-b border-white/10 flex items-center justify-between bg-white/[0.02]">
            <h3 className="font-bold text-xl tracking-tighter text-white">Policy audit vault</h3>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="text-gray-500 text-[10px] font-bold tracking-widest border-b border-white/5 bg-black/40">
                  <th className="px-8 py-5 uppercase">Insured</th>
                  <th className="px-8 py-5 uppercase">Policy</th>
                  <th className="px-8 py-5 uppercase">Rating</th>
                  <th className="px-8 py-5 uppercase">Boss score</th>
                  <th className="px-8 py-5 text-right uppercase">Action</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-white/5">
                {policies.length === 0 ? (
                  <tr><td colSpan={5} className="px-8 py-20 text-center text-gray-500 font-bold italic tracking-wider uppercase text-xs">Waiting for incoming audits...</td></tr>
                ) : policies.map((p) => (
                  <tr key={p.id} className="hover:bg-white/[0.03] transition-colors group">
                    <td className="px-8 py-6">
                      <div className="text-sm font-bold text-white group-hover:text-yellow-400 transition-colors">{p.insuredName || 'N/A'}</div>
                      <div className="text-[10px] text-gray-600 font-mono tracking-tighter truncate max-w-[150px] uppercase">Ref: {p.id}</div>
                    </td>
                    <td className="px-8 py-6">
                      <span className="inline-block px-3 py-1 rounded-lg bg-white/5 text-[10px] font-black text-gray-400 border border-white/5">{p.type || 'Standard'}</span>
                    </td>
                    <td className="px-8 py-6">
                      <span className={`px-3 py-1 rounded-full text-[9px] font-black tracking-widest uppercase ${p.rating === 'Good' ? 'bg-green-500/10 text-green-400' : p.rating === 'Needs Improvement' ? 'bg-yellow-500/10 text-yellow-400' : 'bg-red-500/10 text-red-400'}`}>{p.rating}</span>
                    </td>
                    <td className="px-8 py-6 font-black text-white text-lg">{p.score.toFixed(1)}</td>
                    <td className="px-8 py-6 text-right">
                      <div className="flex justify-end gap-2">
                        <button onClick={() => onViewPolicy(p)} className="px-4 py-2 rounded-xl bg-white/5 text-gray-400 hover:text-white border border-white/5 text-[10px] font-black uppercase tracking-widest transition-all">Review</button>
                        <button onClick={() => onDeletePolicy(p.id)} className="p-2.5 rounded-xl bg-red-500/5 text-gray-600 hover:text-red-400 border border-red-500/10 transition-all">
                           <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {activeTab === 'premium' && (
        <div className="space-y-12 animate-in fade-in slide-in-from-top-4">

          {/* PENDING REQUESTS SECTION */}
          <div className="bg-black/40 backdrop-blur-2xl rounded-[2.5rem] border border-yellow-400/20 p-10 shadow-2xl">
            <h3 className="text-xl font-black text-white mb-8 uppercase tracking-widest flex items-center gap-3">
              Pending Access Requests
              <span className="px-2 py-0.5 rounded bg-yellow-400 text-black text-[10px] font-black">{premiumRequests.length}</span>
            </h3>

            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead>
                  <tr className="text-gray-500 text-[10px] font-bold tracking-widest border-b border-white/5 bg-black/40">
                    <th className="px-8 py-5 uppercase">Proposed User</th>
                    <th className="px-8 py-5 uppercase">Proposed Pass</th>
                    <th className="px-8 py-5 uppercase">Email</th>
                    <th className="px-8 py-5 text-right uppercase">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-white/5">
                  {premiumRequests.length === 0 ? (
                    <tr><td colSpan={4} className="px-8 py-12 text-center text-gray-500 font-bold italic uppercase text-[10px]">No pending requests</td></tr>
                  ) : premiumRequests.map((r) => (
                    <tr key={r.id} className="hover:bg-yellow-400/[0.02] transition-colors group">
                      <td className="px-8 py-5 text-sm font-bold text-white">{r.username}</td>
                      <td className="px-8 py-5 text-sm font-mono text-gray-400">{r.password}</td>
                      <td className="px-8 py-5 text-[10px] text-gray-500 font-black uppercase">{r.email}</td>
                      <td className="px-8 py-5 text-right">
                        <div className="flex justify-end gap-2">
                          <button onClick={() => handleApproveRequest(r)} className="px-4 py-2 rounded-xl bg-yellow-400 text-black border border-yellow-400/20 text-[10px] font-black uppercase tracking-widest hover:bg-yellow-500 transition-all">Approve</button>
                          <button onClick={() => onDeletePremiumRequest(r.id)} className="p-2 rounded-xl bg-red-500/10 text-red-400 border border-red-500/20 hover:bg-red-500 hover:text-white transition-all">
                             <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg>
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          <div className="bg-black/40 backdrop-blur-2xl rounded-[2.5rem] border border-white/10 p-10 shadow-2xl">
            <h3 className="text-xl font-black text-white mb-8 uppercase tracking-widest">Premium access management</h3>

            <form onSubmit={handleCreatePremiumUser} className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-12">
              <input 
                type="text" 
                placeholder="Username" 
                value={newUsername}
                onChange={(e) => setNewUsername(e.target.value)}
                className="bg-black border border-white/10 rounded-xl px-4 py-3 text-sm focus:border-yellow-400 outline-none text-white"
              />
              <input 
                type="text" 
                placeholder="Password" 
                value={newPassword}
                onChange={(e) => setNewPassword(e.target.value)}
                className="bg-black border border-white/10 rounded-xl px-4 py-3 text-sm focus:border-yellow-400 outline-none text-white"
              />
              <button 
                type="submit"
                className="bg-yellow-400 text-black font-black py-3 rounded-xl hover:bg-yellow-500 transition-all uppercase text-[10px] tracking-widest"
              >
                Create credentials
              </button>
            </form>

            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead>
                  <tr className="text-gray-500 text-[10px] font-bold tracking-widest border-b border-white/5 bg-black/40">
                    <th className="px-8 py-5 uppercase">Username</th>
                    <th className="px-8 py-5 uppercase">Password</th>
                    <th className="px-8 py-5 uppercase">Created</th>
                    <th className="px-8 py-5 text-right uppercase">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-white/5">
                  {premiumUsers.length === 0 ? (
                    <tr><td colSpan={4} className="px-8 py-12 text-center text-gray-500 font-bold italic uppercase text-[10px]">No premium users created</td></tr>
                  ) : premiumUsers.map((u) => (
                    <tr key={u.id} className="hover:bg-white/[0.03] transition-colors group">
                      <td className="px-8 py-5 text-sm font-bold text-white">{u.username}</td>
                      <td className="px-8 py-5 text-sm font-mono text-gray-400">{u.password}</td>
                      <td className="px-8 py-5 text-[10px] text-gray-500 font-black uppercase">{u.createdAt}</td>
                      <td className="px-8 py-5 text-right">
                        <button onClick={() => handleDeletePremiumUser(u.id)} className="p-2 rounded-xl bg-red-500/10 text-red-400 border border-red-500/20 hover:bg-red-500 hover:text-white transition-all">
                           <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg>
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}

      {/* Leads Tab */}
      {activeTab === 'leads' && (
        <div className="bg-black/40 backdrop-blur-2xl rounded-[2.5rem] border border-white/10 overflow-hidden shadow-2xl animate-in fade-in slide-in-from-top-4">
          <div className="px-8 py-6 border-b border-white/10 flex items-center justify-between bg-white/[0.02]">
            <h3 className="font-bold text-xl tracking-tighter text-white">Global lead authority</h3>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="text-gray-500 text-[10px] font-bold tracking-widest border-b border-white/5 bg-black/40">
                  <th className="px-8 py-5 uppercase">Business</th>
                  <th className="px-8 py-5 uppercase">Contact</th>
                  <th className="px-8 py-5 uppercase">Workflow</th>
                  <th className="px-8 py-5 text-right uppercase">Action</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-white/5">
                {leads.length === 0 ? (
                  <tr><td colSpan={5} className="px-8 py-20 text-center text-gray-500 font-bold italic tracking-wider uppercase text-xs">System ready. Awaiting quotes...</td></tr>
                ) : leads.map((l) => (
                  <tr key={l.id} className="hover:bg-white/[0.03] transition-colors group">
                    <td className="px-8 py-6">
                      <div className="text-sm font-bold text-white">{l.businessName}</div>
                      <div className="text-[10px] text-gray-600 font-medium">{l.city || 'Central System'}</div>
                    </td>
                    <td className="px-8 py-6">
                      <div className="text-sm font-bold text-white">{l.contactName}</div>
                      <div className="text-[10px] text-gray-500 font-mono lowercase tracking-tighter">{l.contactEmail}</div>
                    </td>
                    <td className="px-8 py-6">
                       <select 
                        value={l.status} 
                        onChange={(e) => onStatusChange(l.id, e.target.value as any)}
                        className="bg-black border border-white/10 rounded-xl px-4 py-2 text-[10px] font-black tracking-widest uppercase text-yellow-400 focus:outline-none focus:border-yellow-400 transition-all cursor-pointer"
                       >
                         <option value="New">New lead</option>
