import { GoogleGenAI, Type } from "@google/genai";
import { PolicyAnalysis } from "../types";

/**
 * Calculates a SHA-256 hash of the file content for duplicate detection.
 */
export const calculateFileHash = async (base64: string): Promise<string> => {
  const msgUint8 = new TextEncoder().encode(base64);
  const hashBuffer = await crypto.subtle.digest('SHA-256', msgUint8);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
};

/**
 * Deep scan of insurance policy using Gemini 3 Flash.
 * Switched to Flash to resolve quota limits while maintaining high-quality auditing.
 */
export const analyzePolicy = async (file: File, signal?: AbortSignal): Promise<PolicyAnalysis> => {
  // Always use process.env.API_KEY directly for initialization as per SDK guidelines.
  if (!process.env.API_KEY || process.env.API_KEY === 'undefined' || process.env.API_KEY === '') {
    throw new Error("Audit Failure: The Insurance Boss API key is not configured. Please check your deployment settings.");
  }

  // Use the exact required initialization pattern: new GoogleGenAI({ apiKey: ... })
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  if (signal?.aborted) throw new DOMException("Aborted", "AbortError");

  const base64Data = await new Promise<string>((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => resolve((reader.result as string).split(',')[1]);
    reader.onerror = () => reject(new Error("Failed to read file"));
    reader.readAsDataURL(file);
  });

  const fileHash = await calculateFileHash(base64Data);

  const prompt = `You are "The Insurance Boss", the world's most aggressive and accurate insurance auditor. 
  Perform a DEEP technical audit of this policy PDF. Identify traps, hidden exclusions, and gaps in coverage.
  Extract:
  1. Insured details (Name, Address, FEIN, Policy #).
  2. Limits (General Liability, Work Comp, etc).
  3. Industry specific exclusions (e.g., "Injury to Subcontractors", "Residential Exclusion").
  4. A score (0-10) based on coverage robustness.
  5. 3 specific Red Flags.
  6. 3 specific Strengths.
  7. 3 expert Recommendations.

  Return ONLY a valid JSON object matching the requested schema.`;

  try {
    const response = await ai.models.generateContent({
      // Switched to gemini-3-flash-preview to resolve 429 quota errors while maintaining excellent reasoning capabilities
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: base64Data, mimeType: 'application/pdf' } },
          { text: prompt }
        ]
      },
      config: {
        // Thinking budget allocated for complex reasoning; max for Flash is 24576
        thinkingConfig: { thinkingBudget: 4000 },
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            insuredName: { type: Type.STRING },
            insuredAddress: { type: Type.STRING },
            policyNumber: { type: Type.STRING },
            fein: { type: Type.STRING },
            industry: { type: Type.STRING },
            effectiveDate: { type: Type.STRING },
            expirationDate: { type: Type.STRING },
            type: { type: Type.STRING },
            rating: { 
              type: Type.STRING, 
              description: "Must be one of: Good, Needs Improvement, Poor, Unable to Analyze" 
            },
            score: { type: Type.NUMBER },
            summary: { type: Type.STRING },
            coverageAnalysis: { type: Type.STRING },
            premiumVsValue: { type: Type.STRING },
            deductibles: { type: Type.STRING },
            foundExclusions: { type: Type.ARRAY, items: { type: Type.STRING } },
            industryExclusionAudit: { type: Type.STRING },
            strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
            redFlags: { type: Type.ARRAY, items: { type: Type.STRING } },
            recommendations: { type: Type.ARRAY, items: { type: Type.STRING } },
            coverageLimits: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  label: { type: Type.STRING },
                  limit: { type: Type.STRING }
                },
                propertyOrdering: ["label", "limit"]
              }
            }
          },
          required: ["insuredName", "score", "summary", "redFlags", "rating"],
          propertyOrdering: [
            "insuredName", "insuredAddress", "policyNumber", "fein", "industry", 
            "effectiveDate", "expirationDate", "type", "rating", "score", 
            "summary", "coverageAnalysis", "premiumVsValue", "deductibles", 
            "foundExclusions", "industryExclusionAudit", "strengths", 
            "redFlags", "recommendations", "coverageLimits"
          ]
        }
      }
    });

    if (signal?.aborted) throw new DOMException("Aborted", "AbortError");

    // Access the .text property directly as per the @google/genai guidelines
    const responseText = response.text?.trim() || '{}';
    const result = JSON.parse(responseText);

    return {
      id: Math.random().toString(36).substr(2, 9),
      filename: file.name,
      uploadDate: new Date().toLocaleString(),
      fileHash,
      fileData: base64Data,
      ...result
    };
  } catch (error: any) {
    if (error.name === 'AbortError') throw error;
    console.error("Boss, Audit Failed:", error);
    throw error;
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { analyzePolicy, calculateFileHash } from '../services/geminiService';
import { PolicyAnalysis, PremiumRequest } from '../types';
import { storage } from '../services/storage';

interface UploadSectionProps {
  onAnalysisComplete: (analysis: PolicyAnalysis, details: { name: string; email: string }) => void;
  existingPolicies: PolicyAnalysis[];
  onOpenWizard: () => void;
  onPremiumRequest: (request: PremiumRequest) => void;
}

const FREE_LIMIT = 5;

const UploadSection: React.FC<UploadSectionProps> = ({ onAnalysisComplete, existingPolicies, onOpenWizard, onPremiumRequest }) => {
  const [isUploading, setIsUploading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [userName, setUserName] = useState('');
  const [userEmail, setUserEmail] = useState('');

  // Premium/Limit State
  const [uploadCount, setUploadCount] = useState(0);
  const [isPremium, setIsPremium] = useState(false);
  const [showPremiumLogin, setShowPremiumLogin] = useState(false);
  const [premiumUsername, setPremiumUsername] = useState('');
  const [premiumPassword, setPremiumPassword] = useState('');
  const [loginError, setLoginError] = useState('');

  // Premium Request Form State
  const [showRequestForm, setShowRequestForm] = useState(false);
  const [reqUsername, setReqUsername] = useState('');
  const [reqPassword, setReqPassword] = useState('');
  const [reqEmail, setReqEmail] = useState('');
  const [reqStatus, setReqStatus] = useState<'idle' | 'submitting' | 'done'>('idle');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const progressIntervalRef = useRef<number | null>(null);
  const abortControllerRef = useRef<AbortController | null>(null);

  useEffect(() => {
    // Load local count
    const count = parseInt(localStorage.getItem('boss_upload_count') || '0');
    const premiumStatus = localStorage.getItem('boss_premium_session') === 'active';
    setUploadCount(count);
    setIsPremium(premiumStatus);

    return () => {
      if (progressIntervalRef.current) clearInterval(progressIntervalRef.current);
    };
  }, []);

  const handleStop = () => {
    if (progressIntervalRef.current) clearInterval(progressIntervalRef.current);
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }
    setIsUploading(false);
    setProgress(0);
  };

  const startProgressSimulation = (isFastTrack: boolean = false) => {
    setProgress(0);
    if (progressIntervalRef.current) clearInterval(progressIntervalRef.current);

    const intervalSpeed = isFastTrack ? 10 : 100;

    progressIntervalRef.current = window.setInterval(() => {
      setProgress(prev => {
        if (prev >= 98) {
          if (!isFastTrack) return 98;
          return 100;
        }
        const increment = isFastTrack ? 15 : (prev < 40 ? 3 : prev < 70 ? 0.8 : 0.2);
        return Math.min(prev + increment, 100);
      });
    }, intervalSpeed);
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Check Limit
    if (!isPremium && uploadCount >= FREE_LIMIT) {
      alert("Boss, you've reached your free audit limit. Log in for premium access.");
      setShowPremiumLogin(true);
      return;
    }

    setIsUploading(true);
    startProgressSimulation();
    abortControllerRef.current = new AbortController();

    try {
      const base64Data = await new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onloadend = () => resolve((reader.result as string).split(',')[1]);
        reader.onerror = () => reject(new Error("Failed to read file"));
        reader.readAsDataURL(file);
      });

      const fileHash = await calculateFileHash(base64Data);
      const existingMatch = existingPolicies.find(p => p.fileHash === fileHash);

      const userDetails = { name: userName, email: userEmail };

      if (existingMatch) {
        startProgressSimulation(true); 
        await new Promise(r => setTimeout(r, 800)); 
        if (progressIntervalRef.current) clearInterval(progressIntervalRef.current);
        setProgress(100);
        setTimeout(() => {
          onAnalysisComplete(existingMatch, userDetails);
          setIsUploading(false);
          setProgress(0);
        }, 300);
        return;
      }

      // Perform AI Analysis
      const analysis = await analyzePolicy(file, abortControllerRef.current.signal);

      // Increment count
      if (!isPremium) {
        const newCount = uploadCount + 1;
        setUploadCount(newCount);
        localStorage.setItem('boss_upload_count', newCount.toString());
      }

      if (progressIntervalRef.current) clearInterval(progressIntervalRef.current);
      setProgress(100);

      setTimeout(() => {
        onAnalysisComplete(analysis, userDetails);
        setIsUploading(false);
        setProgress(0);
      }, 500);

    } catch (err: any) {
      if (err.name === 'AbortError') return;
      console.error("Technical Audit Failure:", err);
      setIsUploading(false);
      setProgress(0);
      if (progressIntervalRef.current) clearInterval(progressIntervalRef.current);
      alert(err.message || "Unknown error occurred on Boss Central Engine.");
    } finally {
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  const handlePremiumLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    const isValid = await storage.validatePremiumUser(premiumUsername, premiumPassword);
    if (isValid) {
      setIsPremium(true);
      localStorage.setItem('boss_premium_session', 'active');
      setShowPremiumLogin(false);
      setLoginError('');
    } else {
      setLoginError('Invalid credentials. Contact the Boss.');
    }
  };

  const handleSubmitPremiumRequest = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!reqUsername || !reqPassword || !reqEmail) return;
    setReqStatus('submitting');

    const request: PremiumRequest = {
      id: Math.random().toString(36).substr(2, 9),
      username: reqUsername,
      password: reqPassword,
      email: reqEmail,
      requestDate: new Date().toLocaleString()
    };

    await new Promise(r => setTimeout(r, 1000));
    onPremiumRequest(request);
    setReqStatus('done');
    setReqUsername('');
    setReqPassword('');
    setReqEmail('');
    setTimeout(() => {
      setReqStatus('idle');
      setShowRequestForm(false);
    }, 2000);
  };

  const isValidEmail = (email: string) => {
    const emailRegex = /^[a-zA-Z0-9._%+-]+@(gmail|hotmail)\.com$/i;
    return emailRegex.test(email.trim());
  };

  const isFormValid = userName.trim().length > 1 && isValidEmail(userEmail);
  const isLimitReached = !isPremium && uploadCount >= FREE_LIMIT;

  return (
    <div className="flex flex-col items-center justify-center text-center py-4 px-4 bg-transparent max-w-5xl mx-auto animate-in fade-in duration-1000">

      {/* HEADER */}
      <div className="mb-12 space-y-4">
        <h1 className="text-6xl md:text-8xl font-black leading-[1.0] tracking-tighter text-white">
          Is Your Policy <br />
          <span className="text-yellow-400">Protecting</span> You?
        </h1>
        <p className="text-gray-400 text-lg md:text-xl font-bold max-w-2xl mx-auto leading-tight opacity-90">
          Upload your policy for an instant technical audit (5 free quotes). Identify gaps before they identify you.
        </p>
      </div>

      {isLimitReached && !showPremiumLogin && (
        <div className="mb-10 w-full max-w-2xl bg-red-500/10 border border-red-500/20 p-8 rounded-3xl animate-in zoom-in-95">
          <h3 className="text-xl font-black text-white mb-2">Limit reached, Boss.</h3>
