export const analyzePolicy = async (file: File, signal?: AbortSignal): Promise<PolicyAnalysis> => {
  if (!process.env.API_KEY || process.env.API_KEY === 'undefined' || process.env.API_KEY === '') {
    throw new Error("Audit Failure: The Insurance Boss API key is not configured.");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  if (signal?.aborted) throw new DOMException("Aborted", "AbortError");

  const base64Data = await new Promise<string>((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => resolve((reader.result as string).split(',')[1]);
    reader.onerror = () => reject(new Error("Failed to read file"));
    reader.readAsDataURL(file);
  });

  const fileHash = await calculateFileHash(base64Data);

  const prompt = `### MANDATORY AUTHENTICATION PROTOCOL ###
1. INITIAL STATE: [LOCKED]
2. MANDATORY ACTION: You are strictly prohibited from performing policy audits, summaries, or any insurance-related analysis until the user provides the correct 6-digit Access Code.
3. ACCESS STATUS: VERIFIED. The terminal session has been authorized by the gatekeeper.

### THE INSURANCE BOSS AUTHORITY AUDIT ###
