import React, { useState } from 'react';

interface GatekeeperProps {
  onUnlock: () => void;
}

const Gatekeeper: React.FC<GatekeeperProps> = ({ onUnlock }) => {
  const [code, setCode] = useState('');
  const [error, setError] = useState('');
  const [showZapier, setShowZapier] = useState(false);

  const handleVerify = (e: React.FormEvent) => {
    e.preventDefault();

    if (!code) {
      setError("Identity Verification Required. Please enter your secure access code to initialize the uplink.");
      return;
    }

    // Protocol Update: Since AI Studio is standalone, check for any 6-digit number to allow entry.
    if (code.length === 6 && /^\d+$/.test(code)) {
      setError('');
      onUnlock();
    } else {
      setError("Access Denied. Invalid credentials. Please check your email or request a new code from The Insurance Boss.");
    }
  };

  const ZapierEmbed = 'zapier-interfaces-page-embed' as any;

  return (
    <div className="min-h-[80vh] flex flex-col items-center justify-center p-4 animate-in fade-in duration-700">
      <div className="w-full max-w-xl bg-black border-[4px] border-yellow-400 rounded-[3rem] p-8 md:p-12 shadow-[0_0_100px_rgba(250,204,21,0.2)] relative overflow-hidden">

        {/* Security Header */}
        <div className="flex items-center justify-between mb-10">
          <div className="flex items-center gap-3">
            <div className={`w-3 h-3 bg-red-600 rounded-full animate-pulse shadow-[0_0_10px_#dc2626]`} />
            <span className="text-red-500 font-black text-[10px] tracking-[0.3em] uppercase">Status: Locked</span>
          </div>
          <div className="text-yellow-400/30 font-mono text-[10px]">AUTH_TERMINAL_V7.0</div>
        </div>

        {!showZapier ? (
          <div className="space-y-8 text-center">
            <h2 className="text-4xl md:text-5xl font-black text-white tracking-tighter leading-none uppercase">
              Identity <br />
              <span className="text-yellow-400">Verification</span>
            </h2>

            <p className="text-gray-500 text-sm font-bold leading-tight uppercase tracking-tight max-w-xs mx-auto">
              Access to the Policy Review Tool is restricted. Enter your 6-digit code to initialize the uplink.
            </p>

            <form onSubmit={handleVerify} className="space-y-6">
              <div className="relative group">
                <input 
                  type="text" 
                  maxLength={6}
                  value={code}
                  onChange={(e) => {
                    setError('');
                    setCode(e.target.value.replace(/\D/g, ''));
                  }}
                  placeholder="X X X X X X"
                  className={`w-full bg-black border-2 rounded-2xl py-6 text-center text-3xl font-black tracking-[0.5em] text-yellow-400 transition-all outline-none placeholder:text-white/5 
                    ${error ? 'border-red-500/50' : 'border-white/10 focus:border-yellow-400'}
                  `}
                />
              </div>

              {error && (
                <p className="text-red-500 text-[10px] font-black uppercase tracking-widest animate-bounce px-4">
                  {error}
                </p>
              )}

              <button 
                type="submit"
                className="w-full bg-yellow-400 text-black font-black py-5 rounded-2xl hover:bg-yellow-500 transition-all active:scale-95 shadow-xl uppercase text-xs tracking-[0.2em]"
              >
                Establish Connection
              </button>
            </form>

            <div className="pt-6 border-t border-white/5">
              <button 
                onClick={() => setShowZapier(true)}
                className="text-gray-600 hover:text-white text-[10px] font-black uppercase tracking-widest transition-colors"
              >
                I don't have a code
              </button>
            </div>
          </div>
        ) : (
          <div className="space-y-6 animate-in zoom-in-95">
             <div className="flex justify-between items-center">
               <h3 className="text-yellow-400 font-black text-xs tracking-widest uppercase">Request Access Code</h3>
               <button onClick={() => setShowZapier(false)} className="text-gray-500 hover:text-white transition-colors">
                 <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg>
               </button>
             </div>
             <div className="rounded-2xl overflow-hidden bg-black border border-yellow-400/20 shadow-2xl">
               <ZapierEmbed 
                 page-id='cmkmy80ag006s10ek5p3z5au5' 
                 test-id='cmkmy80ag006s10ek5p3z5au5-zapier-interfaces-page-embed-iframe' 
                 no-background='true'  
                 style={{ maxWidth: '100%', height: '400px', display: 'block', backgroundColor: '#000000' }}
               />
             </div>
             <p className="text-[9px] text-gray-700 font-black uppercase tracking-widest text-center">Your unique 6-digit key will be dispatched to your terminal.</p>
          </div>
        )}

        <div className="absolute inset-0 pointer-events-none opacity-[0.03] bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')]" />
      </div>
    </div>
  );
};

