import { GoogleGenAI, Type } from "@google/genai";
import { PolicyAnalysis } from "../types";

const ZAPIER_WEBHOOK_URL = "https://hooks.zapier.com/hooks/catch/25763261/ucbw8rp/";

/**
 * Calculates a SHA-256 hash of the file content for duplicate detection.
 */
export const calculateFileHash = async (base64: string): Promise<string> => {
  const msgUint8 = new TextEncoder().encode(base64);
  const hashBuffer = await crypto.subtle.digest('SHA-256', msgUint8);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
};

/**
 * Triggers the outbound webhook for EZLynx/CRM integration.
 */
const triggerWebhook = async (data: any) => {
  try {
    await fetch(ZAPIER_WEBHOOK_URL, {
      method: 'POST',
      mode: 'no-cors', // Zapier webhooks often don't support CORS but still process requests
      body: JSON.stringify(data),
      headers: { 'Content-Type': 'application/json' }
    });
  } catch (e) {
    console.warn("Webhook signaling failure (non-critical):", e);
  }
};

/**
 * Deep scan of insurance policy using Gemini.
 */
export const analyzePolicy = async (file: File, signal?: AbortSignal): Promise<PolicyAnalysis> => {
  const apiKey = process.env.API_KEY;

  if (!apiKey || apiKey === 'undefined' || apiKey === 'null' || apiKey.trim() === '') {
    throw new Error("Uplink Failure: The Insurance Boss terminal API key is missing. Please ensure API_KEY is set in your environment.");
  }

  const ai = new GoogleGenAI({ apiKey: apiKey.trim() });

  if (signal?.aborted) throw new DOMException("Aborted", "AbortError");

  const base64Data = await new Promise<string>((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => resolve((reader.result as string).split(',')[1]);
    reader.onerror = () => reject(new Error("Failed to read file"));
    reader.readAsDataURL(file);
  });

  const fileHash = await calculateFileHash(base64Data);

  const prompt = `### ROLE: Lead Data Architect for "The Insurance Boss" ###

**MISSION:** 
Convert this unstructured insurance policy document into a high-precision, clean, structured JSON format for CRM and EZLynx integration.

**OPERATIONAL GUIDELINES:**
1. **Precision:** Extract values exactly as they appear. Use null if missing. Do not guess.
2. **Dates:** Format as YYYY-MM-DD.
3. **VINs:** Strictly 17 characters.
4. **Context:** Identify if the policy is Personal or Commercial.
5. **Cross-Sell Logic:** If an Auto policy is detected without a corresponding Home policy mentioned, add "Auto no Home" to cross_sell_flags.

**AUDIT PERSONA:**
You are also the "Authority Audit Terminal." Use aggressive, authoritative, and technical language for the summary and recommendations.

**JSON SCHEMA PROTOCOL:**
You must satisfy the response schema provided. The "ezlynx_data" property must contain the deep extraction for EZLynx.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: {
        parts: [
          { inlineData: { data: base64Data, mimeType: 'application/pdf' } },
          { text: prompt }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            insuredName: { type: Type.STRING },
            insuredAddress: { type: Type.STRING },
            policyNumber: { type: Type.STRING },
            fein: { type: Type.STRING },
            industry: { type: Type.STRING },
            effectiveDate: { type: Type.STRING },
            expirationDate: { type: Type.STRING },
            carrierName: { type: Type.STRING },
            premiumAmount: { type: Type.STRING },
            type: { type: Type.STRING },
            rating: { type: Type.STRING },
            score: { type: Type.NUMBER },
            summary: { type: Type.STRING },
            coverageAnalysis: { type: Type.STRING },
            premiumVsValue: { type: Type.STRING },
            deductibles: { type: Type.STRING },
            foundExclusions: { type: Type.ARRAY, items: { type: Type.STRING } },
            industryExclusionAudit: { type: Type.STRING },
            strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
            redFlags: { type: Type.ARRAY, items: { type: Type.STRING } },
            recommendations: { type: Type.ARRAY, items: { type: Type.STRING } },
            coverageLimits: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  label: { type: Type.STRING },
                  limit: { type: Type.STRING }
                }
              }
            },
            ezlynx_data: {
              type: Type.OBJECT,
              properties: {
                client_profile: {
                  type: Type.OBJECT,
                  properties: {
                    first_name: { type: Type.STRING, nullable: true },
                    last_name: { type: Type.STRING, nullable: true },
                    dob: { type: Type.STRING, nullable: true },
                    full_address: { type: Type.STRING, nullable: true },
                    email: { type: Type.STRING, nullable: true },
                    phone: { type: Type.STRING, nullable: true }
                  }
                },
                policy_data: {
                  type: Type.OBJECT,
                  properties: {
                    carrier: { type: Type.STRING, nullable: true },
                    policy_number: { type: Type.STRING, nullable: true },
                    lob_type: { type: Type.STRING, nullable: true },
                    effective_date: { type: Type.STRING, nullable: true },
                    expiration_date: { type: Type.STRING, nullable: true },
                    total_premium: { type: Type.STRING, nullable: true }
                  }
                },
                line_specific_details: {
                  type: Type.OBJECT,
                  properties: {
                    vehicles: { type: Type.ARRAY, items: { type: Type.OBJECT } },
                    property_info: { type: Type.OBJECT },
                    commercial_codes: { type: Type.OBJECT }
                  }
                },
                cross_sell_flags: { type: Type.ARRAY, items: { type: Type.STRING } },
                status: { type: Type.STRING }
              }
            }
          }
        }
      }
    });

    if (signal?.aborted) throw new DOMException("Aborted", "AbortError");

    const result = JSON.parse(response.text || '{}');

    let finalScore = result.score || 0;
    if (finalScore > 10) finalScore = finalScore / 10;
    finalScore = Math.max(0, Math.min(finalScore, 10));

    const analysis: PolicyAnalysis = {
      id: Math.random().toString(36).substr(2, 9),
      filename: file.name,
      uploadDate: new Date().toLocaleString(),
      fileHash,
      fileData: base64Data,
      ...result,
      score: finalScore,
      ezlynxData: result.ezlynx_data,
      uplinkData: {
        insured_name: result.insuredName || "N/A",
        carrier: result.carrierName || "N/A",
        premium: result.premiumAmount || "N/A",
        policy_type: result.type || "N/A",
        expiration: result.expirationDate || "N/A"
      }
    };

    // Auto-trigger EZLynx Webhook
    if (analysis.ezlynxData) {
      triggerWebhook({
        webhook_target: ZAPIER_WEBHOOK_URL,
        ...analysis.ezlynxData
      });
    }

    return analysis;
  } catch (error: any) {
    if (error.name === 'AbortError') throw error;
    throw new Error(error.message || "Unknown error occurred on Boss Central Engine.");
  }
};

