import { GoogleGenAI, Type } from "@google/genai";
import { PolicyAnalysis } from "../types";

const ZAPIER_WEBHOOK_URL = "https://hooks.zapier.com/hooks/catch/25763261/ucbw8rp/";

/**
 * TECHNICAL UPLINK: Sends extracted data to EZLynx via Zapier Hook.
 * Identifies JSON data between specific tags.
 */
async function sendToTheBossUplink(aiResponseText: string) {
    const zapierWebhookURL = ZAPIER_WEBHOOK_URL;

    // Localizar los datos entre las etiquetas del prompt
    const startTag = "--- UPLINK DATA START ---";
    const endTag = "--- UPLINK DATA END ---";
    const startIndex = aiResponseText.indexOf(startTag);
    const endIndex = aiResponseText.indexOf(endTag);

    if (startIndex !== -1 && endIndex !== -1) {
        const jsonContent = aiResponseText.substring(startIndex + startTag.length, endIndex).trim();

        try {
            const dataPayload = JSON.parse(jsonContent);

            // Enviar al Webhook de Zapier
            await fetch(zapierWebhookURL, {
                method: "POST",
                mode: "no-cors", // Previene bloqueos de seguridad del navegador
                body: JSON.stringify(dataPayload)
            });
            console.log("Uplink to EZLynx successful.");
        } catch (error) {
            console.error("Failed to parse or send uplink data:", error);
        }
    }
}

/**
 * Calculates a SHA-256 hash of the file content for duplicate detection.
 */
export const calculateFileHash = async (base64: string): Promise<string> => {
  const msgUint8 = new TextEncoder().encode(base64);
  const hashBuffer = await crypto.subtle.digest('SHA-256', msgUint8);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
};

/**
 * Helper to perform exponential backoff retries for transient API errors.
 */
const callWithRetry = async <T>(fn: () => Promise<T>, retries = 3, baseDelay = 2000): Promise<T> => {
  let lastError: any;
  for (let i = 0; i < retries; i++) {
    try {
      return await fn();
    } catch (error: any) {
      lastError = error;
      const isRateLimit = error.message?.includes('429') || error.message?.includes('RESOURCE_EXHAUSTED');
      const isOverloaded = error.message?.includes('503') || error.message?.includes('500');

      if ((isRateLimit || isOverloaded) && i < retries - 1) {
        const delay = baseDelay * Math.pow(2, i);
        console.warn(`Boss Engine Throttled. Attempt ${i + 1}/${retries}. Retrying in ${delay}ms...`);
        await new Promise(resolve => setTimeout(resolve, delay));
        continue;
      }
      throw error;
    }
  }
  throw lastError;
};

/**
 * Deep scan of insurance policy using Gemini.
 */
export const analyzePolicy = async (file: File, signal?: AbortSignal): Promise<PolicyAnalysis> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  if (signal?.aborted) throw new DOMException("Aborted", "AbortError");

  const base64Data = await new Promise<string>((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => resolve((reader.result as string).split(',')[1]);
    reader.onerror = () => reject(new Error("Failed to read file"));
    reader.readAsDataURL(file);
  });

  const fileHash = await calculateFileHash(base64Data);

  const prompt = `### PERSONA: Authority Audit Terminal for "The Insurance Boss" ###

**MISSION:** 
You are a high-precision cinematic underwriting engine. Your tone is cinematic, aggressive, and highly technical. Identify hidden gaps, fine-print traps, and coverage failures that put the insured at risk. You are an authority, not a salesperson.

**STRICT RESPONSE PROTOCOL:**
1. **Report Content:** Generate a deep, authoritative audit of the provided insurance policy.
2. **EZLynx Technical Uplink:** At the very end of your response, you MUST generate a structured JSON block with specific keys.

**MANDATORY JSON UPLINK FORMAT:**
--- UPLINK DATA START ---
{
  "client_first_name": "[Extracted First Name]",
  "client_last_name": "[Extracted Last Name]",
  "client_email": "[Extracted Email]",
  "client_phone": "[Extracted Phone Number]",
  "client_address_street": "[Extracted Street Address]",
  "client_address_city": "[Extracted City]",
  "client_address_state": "[Extracted State]",
  "client_address_zip": "[Extracted ZIP Code]",
  "carrier_name": "[Current Carrier Name]",
  "current_premium": "[Total Policy Premium]",
  "policy_type": "[LOB: e.g., Auto, Home, BOP]",
  "expiration_date": "[Policy Expiration Date]"
}
--- UPLINK DATA END ---

**JSON DATA PROTOCOL (UI_METADATA):**
Also provide a JSON object satisfyng the response schema for the UI dashboard.`;

  try {
    const generateContent = async () => {
      // We need both the text report and the JSON structure. 
      // We'll use a single text response and prompt the AI to include the UI metadata and Uplink block.
      return await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: {
          parts: [
            { inlineData: { data: base64Data, mimeType: 'application/pdf' } },
            { text: prompt }
          ]
        },
        config: {
          // We will extract structured data from the text response manually to support the cinematic report requirement.
          // However, for reliability in a production-grade tool, we define a schema for the main results.
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              cinematic_report: { type: Type.STRING },
              insuredName: { type: Type.STRING },
              insuredAddress: { type: Type.STRING },
              policyNumber: { type: Type.STRING },
              fein: { type: Type.STRING },
              industry: { type: Type.STRING },
              effectiveDate: { type: Type.STRING },
              expirationDate: { type: Type.STRING },
              carrierName: { type: Type.STRING },
              premiumAmount: { type: Type.STRING },
              type: { type: Type.STRING },
              rating: { type: Type.STRING },
              score: { type: Type.NUMBER },
              summary: { type: Type.STRING },
              coverageAnalysis: { type: Type.STRING },
              premiumVsValue: { type: Type.STRING },
              deductibles: { type: Type.STRING },
              foundExclusions: { type: Type.ARRAY, items: { type: Type.STRING } },
              strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
              redFlags: { type: Type.ARRAY, items: { type: Type.STRING } },
              recommendations: { type: Type.ARRAY, items: { type: Type.STRING } },
              ezlynx_uplink: {
                type: Type.OBJECT,
                properties: {
                  client_first_name: { type: Type.STRING, nullable: true },
                  client_last_name: { type: Type.STRING, nullable: true },
                  client_email: { type: Type.STRING, nullable: true },
                  client_phone: { type: Type.STRING, nullable: true },
                  client_address_street: { type: Type.STRING, nullable: true },
                  client_address_city: { type: Type.STRING, nullable: true },
                  client_address_state: { type: Type.STRING, nullable: true },
                  client_address_zip: { type: Type.STRING, nullable: true },
                  carrier_name: { type: Type.STRING, nullable: true },
                  current_premium: { type: Type.STRING, nullable: true },
                  policy_type: { type: Type.STRING, nullable: true },
                  expiration_date: { type: Type.STRING, nullable: true }
                }
              }
            }
          }
        }
      });
    };

    const response = await callWithRetry(generateContent);

    if (signal?.aborted) throw new DOMException("Aborted", "AbortError");

    const result = JSON.parse(response.text || '{}');

    // Construct the string for sendToTheBossUplink as requested
    const uplinkString = `--- UPLINK DATA START ---\n${JSON.stringify(result.ezlynx_uplink, null, 2)}\n--- UPLINK DATA END ---`;

    // Trigger Uplink
    await sendToTheBossUplink(uplinkString);

    let finalScore = result.score || 0;
    if (finalScore > 10) finalScore = finalScore / 10;
    finalScore = Math.max(0, Math.min(finalScore, 10));

    const analysis: PolicyAnalysis = {
      id: Math.random().toString(36).substr(2, 9),
      filename: file.name,
      uploadDate: new Date().toLocaleString(),
      fileHash,
      fileData: base64Data,
      ...result,
      score: finalScore,
      summary: result.summary || result.cinematic_report?.substring(0, 100) + "...",
      ezlynxData: result.ezlynx_uplink
    };

    return analysis;
  } catch (error: any) {
    if (error.name === 'AbortError') throw error;
    if (error.message?.includes('429')) {
      throw new Error("Uplink Throttled: Boss Central Engine quota exhausted. Wait 60s.");
    }
    throw new Error(error.message || "Unknown error occurred on Boss Central Engine.");
  }
};

