/**
 * TECHNICAL UPLINK: Sends extracted data to EZLynx via Zapier Hook.
 * Identifies JSON data between tags --- UPLINK DATA START --- and --- UPLINK DATA END ---.
 */
async function parseAndSendToZapier(aiResponseText: string) {
    const zapierWebhookURL = "https://hooks.zapier.com/hooks/catch/25763261/ucbw8rp/";

    // Localizar los datos entre las etiquetas del prompt
    const startTag = "--- UPLINK DATA START ---";
    const endTag = "--- UPLINK DATA END ---";
    const startIndex = aiResponseText.indexOf(startTag);
    const endIndex = aiResponseText.indexOf(endTag);

    if (startIndex !== -1 && endIndex !== -1) {
        const jsonContent = aiResponseText.substring(startIndex + startTag.length, endIndex).trim();

        try {
            const dataPayload = JSON.parse(jsonContent);

            // Enviar al Webhook de Zapier
            await fetch(zapierWebhookURL, {
                method: "POST",
                mode: "no-cors", // Previene bloqueos de seguridad del navegador
                body: JSON.stringify(dataPayload)
            });
            console.log("Uplink to EZLynx successful.");
        } catch (error) {
            console.error("Failed to parse or send uplink data:", error);
        }
    }
}

/**
 * Calculates a SHA-256 hash of the file content for duplicate detection.
 */
export const calculateFileHash = async (base64: string): Promise<string> => {
  const msgUint8 = new TextEncoder().encode(base64);
  const hashBuffer = await crypto.subtle.digest('SHA-256', msgUint8);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
};

/**
 * Deep scan of insurance policy using Gemini.
 */
export const analyzePolicy = async (file: File, signal?: AbortSignal): Promise<PolicyAnalysis> => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("Terminal Access Failed: API_KEY missing.");

  const ai = new GoogleGenAI({ apiKey });

  if (signal?.aborted) throw new DOMException("Aborted", "AbortError");

  const base64Data = await new Promise<string>((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => resolve((reader.result as string).split(',')[1]);
    reader.onerror = () => reject(new Error("Failed to read file"));
    reader.readAsDataURL(file);
  });

  const fileHash = await calculateFileHash(base64Data);

  const prompt = `### PERSONA: Authority Audit Terminal for "The Insurance Boss" ###

**MISSION:** 
You are a high-precision cinematic underwriting engine. Identify hidden gaps, fine-print traps, and coverage failures.

**STRICT RESPONSE PROTOCOL:**
1. Generate a deep cinematic technical audit report.
2. Embed a JSON object labeled [UI_METADATA] for the local dashboard.
3. MANDATORY: Generate a structured JSON data block at the very end for the technical uplink.

**UPLINK DATA KEYS:**
client_first_name, client_last_name, client_email, client_phone, client_address_street, client_address_city, client_address_state, client_address_zip, carrier_name, current_premium, policy_type, expiration_date, cross_sell_flags, insured-identity, authority-email.

--- UPLINK DATA START ---
{
  "client_first_name": "[Extracted]",
  "client_last_name": "[Extracted]",
  "client_email": "[Extracted]",
  "client_phone": "[Extracted]",
  "client_address_street": "[Extracted]",
  "client_address_city": "[Extracted]",
  "client_address_state": "[Extracted]",
  "client_address_zip": "[Extracted]",
  "carrier_name": "[Extracted]",
  "current_premium": "[Extracted]",
  "policy_type": "[Extracted]",
  "expiration_date": "[YYYY-MM-DD]",
  "cross_sell_flags": ["Auto", "Home", "Umbrella"],
  "insured-identity": "[Full Name]",
  "authority-email": "[Client Email]"
}
--- UPLINK DATA END ---`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: {
        parts: [
          { inlineData: { data: base64Data, mimeType: 'application/pdf' } },
          { text: prompt }
        ]
      }
    });

    if (signal?.aborted) throw new DOMException("Aborted", "AbortError");

    const fullText = response.text || '';

    // Trigger Uplink Protocol immediately
    await parseAndSendToZapier(fullText);

    // Parse UI metadata from the text
    let uiData: any = {};
    const uiMatch = fullText.match(/\[UI_METADATA\]\s*(\{[\s\S]*?\})/);
    if (uiMatch) {
      try {
        uiData = JSON.parse(uiMatch[1]);
      } catch (e) {
        console.error("UI metadata extraction failed");
      }
    }

    // Parse Uplink block for local storage copy
    let ezlynxData: any = null;
    const startTag = "--- UPLINK DATA START ---";
    const endTag = "--- UPLINK DATA END ---";
    const startIndex = fullText.indexOf(startTag);
    const endIndex = fullText.indexOf(endTag);
    if (startIndex !== -1 && endIndex !== -1) {
      try {
        ezlynxData = JSON.parse(fullText.substring(startIndex + startTag.length, endIndex).trim());
      } catch (e) {}
    }

    const analysis: PolicyAnalysis = {
      id: Math.random().toString(36).substr(2, 9),
      filename: file.name,
      uploadDate: new Date().toLocaleString(),
      fileHash,
      fileData: base64Data,
      score: uiData.score || 0,
      rating: uiData.rating || 'Needs Improvement',
      insuredName: ezlynxData?.['insured-identity'] || uiData.insuredName || 'Unknown',
      insuredAddress: uiData.insuredAddress || '',
      policyNumber: uiData.policyNumber || 'N/A',
      carrierName: ezlynxData?.carrier_name || uiData.carrierName || 'N/A',
      premiumAmount: ezlynxData?.current_premium || uiData.premiumAmount || 'N/A',
      type: ezlynxData?.policy_type || uiData.type || 'N/A',
      effectiveDate: uiData.effectiveDate || 'N/A',
      expirationDate: ezlynxData?.expiration_date || uiData.expirationDate || 'N/A',
      summary: uiData.summary || "Technical inspection complete.",
      coverageAnalysis: uiData.coverageAnalysis || "Refer to report.",
      premiumVsValue: uiData.premiumVsValue || "N/A",
      exclusions: uiData.exclusions || "N/A",
      foundExclusions: uiData.foundExclusions || [],
      industryExclusionAudit: uiData.industryExclusionAudit || "N/A",
      deductibles: uiData.deductibles || "N/A",
      strengths: uiData.strengths || [],
      redFlags: uiData.redFlags || [],
      recommendations: uiData.recommendations || [],
      coverageLimits: uiData.coverageLimits || [],
      ezlynxData: ezlynxData,
      contactEmail: ezlynxData?.['authority-email'] || uiData.contactEmail || ''
    };

    return analysis;
  } catch (error: any) {
    if (error.name === 'AbortError') throw error;
    throw new Error(error.message || "Boss Central Engine Failure.");
  }
};

