const ZAPIER_WEBHOOK_URL = "https://hooks.zapier.com/hooks/catch/25763261/ucbw8rp/";

/**
 * Robustly extracts JSON from a string that might contain markdown or tags.
 */
function extractJSON(text: string, startTag?: string, endTag?: string): any {
  let content = text;

  if (startTag && endTag) {
    const startIndex = text.indexOf(startTag);
    const endIndex = text.indexOf(endTag);
    if (startIndex === -1 || endIndex === -1) return null;
    content = text.substring(startIndex + startTag.length, endIndex).trim();
  }

  // Remove potential markdown code blocks
  content = content.replace(/```json\n?|```/g, '').trim();

  try {
    return JSON.parse(content);
  } catch (e) {
    console.error("JSON Extraction failed for content:", content.substring(0, 100));
    return null;
  }
}

/**
 * TECHNICAL UPLINK: Sends extracted data to EZLynx via Zapier Hook.
 */
async function parseAndSendToZapier(aiResponseText: string) {
  const payload = extractJSON(aiResponseText, "--- UPLINK DATA START ---", "--- UPLINK DATA END ---");

  if (payload) {
    try {
      await fetch(ZAPIER_WEBHOOK_URL, {
        method: "POST",
        mode: "no-cors", 
        body: JSON.stringify(payload),
        headers: { 'Content-Type': 'application/json' }
      });
      console.log("Authority Uplink: Data transmitted to central hub.");
    } catch (error) {
      console.error("Authority Uplink Failure: Network error.", error);
    }
  }
}

/**
 * Calculates a SHA-256 hash of the file content for duplicate detection.
 */
export const calculateFileHash = async (base64: string): Promise<string> => {
  const msgUint8 = new TextEncoder().encode(base64);
  const hashBuffer = await crypto.subtle.digest('SHA-256', msgUint8);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
};

