const ZAPIER_WEBHOOK_URL = "https://hooks.zapier.com/hooks/catch/25763261/ucmftd7/";

/**
 * Robustly extracts JSON from a string that might contain markdown, tags, or stray text.
 */
function extractJSON(text: string, startTag?: string, endTag?: string): any {
  let content = text;

  if (startTag && endTag) {
    const startIndex = text.indexOf(startTag);
    const endIndex = text.indexOf(endTag);
    if (startIndex === -1 || endIndex === -1) return null;
    content = text.substring(startIndex + startTag.length, endIndex).trim();
  }

  let cleaned = content.replace(/```json\n?|```/g, '').trim();

  try {
    return JSON.parse(cleaned);
  } catch (e) {
    const firstBrace = cleaned.indexOf('{');
    const lastBrace = cleaned.lastIndexOf('}');

    if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
      const jsonCandidate = cleaned.substring(firstBrace, lastBrace + 1);
      try {
        return JSON.parse(jsonCandidate);
      } catch (innerError) {
        console.error("Resilient JSON extraction failed.");
      }
    }
    return null;
  }
}

/**
 * DATA EXTRACTION PROTOCOL
 * Sends extracted data to EZLynx via Zapier Hook in the background.
 */
const sendToZapier = async (text: string) => {
  const startTag = "--- UPLINK DATA START ---";
  const endTag = "--- UPLINK DATA END ---";

  const startIndex = text.indexOf(startTag);
  const endIndex = text.indexOf(endTag);

  if (startIndex !== -1 && endIndex !== -1) {
    const jsonString = text.substring(startIndex + startTag.length, endIndex).trim();
    try {
      const payload: EZLynxPayload = JSON.parse(jsonString);
      fetch(ZAPIER_WEBHOOK_URL, {
        method: 'POST',
        mode: 'no-cors', 
        body: JSON.stringify(payload)
      }).catch(err => console.error("Background Webhook Dispatch Error:", err));

      console.log("Boss Terminal: Uplink packet dispatched to cloud.");
    } catch (e) {
      console.error("Error parsing Uplink JSON:", e);
    }
  }
};

async function generateWithRetry(ai: any, params: any, maxRetries = 3) {
  let delay = 1000; 
  for (let i = 0; i < maxRetries; i++) {
    try {
      return await ai.models.generateContent(params);
    } catch (error: any) {
      const errorMsg = error.message || "";
      const isRetryable = 
        errorMsg.includes('429') || 
        errorMsg.includes('503') ||
        errorMsg.includes('RESOURCE_EXHAUSTED') || 
        errorMsg.includes('SERVICE_UNAVAILABLE') ||
        error.status === 'RESOURCE_EXHAUSTED' ||
        error.status === 'SERVICE_UNAVAILABLE';

      if (isRetryable && i < maxRetries - 1) {
        const jitter = Math.random() * 400;
        await new Promise(resolve => setTimeout(resolve, delay + jitter));
        delay *= 2; 
        continue;
      }
      throw error;
    }
  }
}

export const calculateFileHash = async (base64: string): Promise<string> => {
  const msgUint8 = new TextEncoder().encode(base64);
  const hashBuffer = await crypto.subtle.digest('SHA-256', msgUint8);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
};

/**
 * Deep scan of insurance policy using the optimized Gemini-3-Flash model.
 */
export const analyzePolicy = async (file: File, signal?: AbortSignal): Promise<PolicyAnalysis> => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("AUTHORITY DENIED: VITE_GEMINI_API_KEY is missing. Configure Netlify environment variables.");
  }

  const ai = new GoogleGenAI({ apiKey });

  if (signal?.aborted) throw new DOMException("Aborted", "AbortError");

  const base64Data = await new Promise<string>((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => resolve((reader.result as string).split(',')[1]);
    reader.onerror = () => reject(new Error("Failed to read document stream."));
    reader.readAsDataURL(file);
  });

  const fileHash = await calculateFileHash(base64Data);

  const prompt = `### PERSONA: Authority Audit Terminal for "The Insurance Boss" ###

**MISSION:** 
Analyze the provided insurance policy. Extract LITERAL string values. Do NOT use placeholders.

**STRICT RESPONSE PROTOCOL:**
1. Generate a technical audit report in Markdown format.
2. Embed a JSON object labeled [UI_METADATA] for the results dashboard.
   - Extract literal values for: score (0-10), rating, insuredName, dba, fein, yearsInBusiness, policyNumber, carrierName, premiumAmount, type, effectiveDate, expirationDate, insuredStreet, insuredCity, insuredState, insuredZip, contactName, contactEmail, contactPhone, summary, coverageAnalysis, strengths[], redFlags[], recommendations[], foundExclusions[], coverageLimits[].
   - If a value is missing, use "Not found".
3. MANDATORY: Generate a structured JSON block at the very end for EZLynx.

Format the technical block EXACTLY like this:
--- UPLINK DATA START ---
{
  "client_name": "[Literal Full Name of Insured]",
  "client_email": "[Literal Email]",
  "client_phone": "[Literal Phone]",
  "client_street": "[Literal Street Address]",
  "client_city": "[Literal City]",
  "client_state": "[Literal State]",
  "client_zip": "[Literal Zip Code]",
  "business_name": "[Literal Business Name]",
  "dba": "[Literal DBA]",
  "fein_ein": "[Literal FEIN]",
  "years_in_business": "[Literal Years]",
  "carrier_name": "[Literal Carrier]",
  "current_premium": "[Literal Annual Premium]",
  "policy_type": "[Literal LOB]",
  "expiration_date": "[YYYY-MM-DD]"
}
--- UPLINK DATA END ---`;

  try {
    const response = await generateWithRetry(ai, {
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: base64Data, mimeType: 'application/pdf' } },
          { text: prompt }
        ]
      }
    });

    if (signal?.aborted) throw new DOMException("Aborted", "AbortError");

    const fullText = response.text || '';

    sendToZapier(fullText);

    let uiData = null;
    const uiDataMatch = fullText.match(/\[UI_METADATA\]\s*([\s\S]+?)(?=\n\n|---|$)/);

    if (uiDataMatch) {
      uiData = extractJSON(uiDataMatch[1]);
    }

    if (!uiData) {
      const jsonBlocks = fullText.match(/\{[\s\S]*?\}/g);
      if (jsonBlocks) {
        for (const block of jsonBlocks) {
          const parsed = extractJSON(block);
          if (parsed && (parsed.score !== undefined || parsed.rating !== undefined)) {
            uiData = parsed;
            break;
          }
        }
      }
    }

    if (!uiData) {
      throw new Error("Audit processing successful, but metadata extraction failed.");
    }

    const uplinkData: EZLynxPayload = extractJSON(fullText, "--- UPLINK DATA START ---", "--- UPLINK DATA END ---");

    const address = uiData.insuredStreet ? `${uiData.insuredStreet}, ${uiData.insuredCity}, ${uiData.insuredState} ${uiData.insuredZip}` : uiData.insuredAddress;

    const analysis: PolicyAnalysis = {
      id: Math.random().toString(36).substr(2, 9),
      filename: file.name,
      uploadDate: new Date().toLocaleString(),
      fileHash,
      fileData: base64Data,
      score: typeof uiData.score === 'number' ? uiData.score : parseFloat(uiData.score) || 0,
      rating: uiData.rating || 'Needs Improvement',
      insuredName: uiData.insuredName || uiData.business_name || 'Not found',
      dba: uiData.dba || 'Not found',
      fein: uiData.fein || 'Not found',
      yearsInBusiness: uiData.yearsInBusiness || 'Not found',
      insuredAddress: address || 'Not found',
      policyNumber: uiData.policyNumber || 'Not found',
      carrierName: uiData.carrierName || 'Not found',
      premiumAmount: uiData.premiumAmount || 'Not found',
      type: uiData.type || 'Not found',
      effectiveDate: uiData.effectiveDate || 'Not found',
      expirationDate: uiData.expirationDate || 'Not found',
      contactEmail: uiData.contactEmail || 'Not found',
      contactPhone: uiData.contactPhone || 'Not found',
      summary: uiData.summary || "Technical scan complete.",
      coverageAnalysis: uiData.coverageAnalysis || "Refer to technical report.",
      premiumVsValue: uiData.premiumVsValue || "N/A",
      exclusions: uiData.exclusions || "N/A",
      foundExclusions: uiData.foundExclusions || [],
      industryExclusionAudit: uiData.industryExclusionAudit || "N/A",
      deductibles: uiData.deductibles || "N/A",
      strengths: uiData.strengths || [],
      redFlags: uiData.redFlags || [],
      recommendations: uiData.recommendations || [],
      coverageLimits: uiData.coverageLimits || [],
      ezlynxData: uplinkData,
      uplinkData: uplinkData
    };

    return analysis;
  } catch (error: any) {
    if (error.name === 'AbortError') throw error;
    throw new Error(error.message || "Boss Central Engine connection failure.");
  }
};

import React, { useState, useEffect } from 'react';
import * as ReactRouterDOM from 'react-router-dom';
import Header from './components/Header';
import UploadSection from './components/UploadSection';
import AnalysisResult from './components/AnalysisResult';
import AdminDashboard from './components/AdminDashboard';
import AdminLogin from './components/AdminLogin';
import WizardForm from './components/WizardForm';
import Gatekeeper from './components/Gatekeeper';
import { PolicyAnalysis, QuoteRequest, PremiumRequest } from './types';
import { storage } from './services/storage';
import { bossServer } from './services/serverService';

const { HashRouter, Routes, Route } = ReactRouterDOM;

const MainView: React.FC<{
  isUnlocked: boolean,
  onUnlock: () => void,
  showWizard: boolean,
  setShowWizard: (v: boolean) => void,
  allPolicies: PolicyAnalysis[],
  currentAnalysis: PolicyAnalysis | null,
  handleNewAnalysis: (a: PolicyAnalysis, details: {name: string, email: string}) => void,
  handleNewLead: (l: QuoteRequest) => void,
  handleNewPremiumRequest: (r: PremiumRequest) => void,
  setCurrentAnalysis: (a: PolicyAnalysis | null) => void,
  onReset: () => void,
  auditCount: number,
  isAdmin?: boolean;
}> = ({ isUnlocked, onUnlock, showWizard, setShowWizard, allPolicies, currentAnalysis, handleNewAnalysis, handleNewLead, handleNewPremiumRequest, setCurrentAnalysis, onReset, auditCount, isAdmin }) => {

  if (!isUnlocked) {
    return <Gatekeeper onUnlock={onUnlock} />;
  }

  if (showWizard) {
    return <WizardForm onSubmit={handleNewLead} onCancel={onReset} />;
  }

  if (currentAnalysis) {
    return (
      <AnalysisResult 
        analysis={currentAnalysis} 
        onReset={onReset} 
        onOpenWizard={() => setShowWizard(true)}
        isAdmin={isAdmin}
      />
    );
  }

  return (
    <UploadSection 
      onAnalysisComplete={handleNewAnalysis} 
      existingPolicies={allPolicies}
      onOpenWizard={() => setShowWizard(true)}
      onPremiumRequest={handleNewPremiumRequest}
      auditCount={auditCount}
    />
  );
};

const App: React.FC = () => {
  const [isAdmin, setIsAdmin] = useState(false);
  const [isUnlocked, setIsUnlocked] = useState(false);
  const [allPolicies, setAllPolicies] = useState<PolicyAnalysis[]>([]);
  const [allLeads, setAllLeads] = useState<QuoteRequest[]>([]);
  const [recycledLeads, setRecycledLeads] = useState<QuoteRequest[]>([]);
  const [recycledPolicies, setRecycledPolicies] = useState<PolicyAnalysis[]>([]);
  const [premiumRequests, setPremiumRequests] = useState<PremiumRequest[]>([]);
  const [currentAnalysis, setCurrentAnalysis] = useState<PolicyAnalysis | null>(null);
  const [showWizard, setShowWizard] = useState(false);
  const [isEmbedded, setIsEmbedded] = useState(false);
  const [auditCount, setAuditCount] = useState(0);

  useEffect(() => {
    const unlocked = sessionStorage.getItem('boss_tool_unlocked') === 'true';
    setIsUnlocked(unlocked);

    const count = parseInt(sessionStorage.getItem('boss_audit_count') || '0', 10);
    setAuditCount(count);

    const params = new URLSearchParams(window.location.search);
    const embedMode = params.get('embed') === 'true' || window.location.href.includes('embed=true');
    setIsEmbedded(embedMode);

    const loadData = async () => {
      try {
        const cloudData = await bossServer.fetchGlobalVault();
        if (cloudData.policies) {
          for (const p of cloudData.policies) await storage.savePolicy(p);
        }
        if (cloudData.leads) {
          for (const l of cloudData.leads) await storage.saveLead(l);
        }

        const p = await storage.getPolicies();
        const l = await storage.getLeads();
        const rl = await storage.getRecycledLeads();
        const rp = await storage.getRecycledPolicies();
        const pr = await storage.getPremiumRequests();
        setAllPolicies(p);
        setAllLeads(l);
        setRecycledLeads(rl);
        setRecycledPolicies(rp);
        setPremiumRequests(pr);
      } catch (err) {
        console.error("Sync Notification:", err);
      }
    };
    loadData();
  }, []);

  const handleUnlock = () => {
    setIsUnlocked(true);
    sessionStorage.setItem('boss_tool_unlocked', 'true');
  };

  const lockApp = () => {
    setIsUnlocked(false);
    sessionStorage.removeItem('boss_tool_unlocked');
    setCurrentAnalysis(null);
    setShowWizard(false);
  };

  const handleGoHome = () => {
    lockApp();
    window.location.hash = '#/';
  };

  const handleNewSession = () => {
    lockApp();
  };

  const handleNewAnalysis = async (analysis: PolicyAnalysis, details: {name: string, email: string}) => {
    const newCount = auditCount + 1;
    setAuditCount(newCount);
    sessionStorage.setItem('boss_audit_count', newCount.toString());

    setCurrentAnalysis(analysis);
    setShowWizard(false);

    Promise.allSettled([
      storage.savePolicy(analysis),
      bossServer.upstream('policy', analysis)
    ]).then(() => {
      setAllPolicies(prev => {
        const exists = prev.some(p => p.id === analysis.id);
        return exists ? prev : [analysis, ...prev];
      });
    });

    const autoLead: QuoteRequest = {
      id: `auto-${analysis.id}`,
      submissionDate: new Date().toLocaleString(),
      status: 'New',
      businessName: analysis.insuredName || details.name,
      dba: analysis.dba || '',
      fein: analysis.fein || 'Not found',
      yearsInBusiness: analysis.yearsInBusiness || 'Not found',
      address1: analysis.insuredAddress || '',
      city: analysis.ezlynxData?.client_city || 'Not found',
      state: analysis.ezlynxData?.client_state || 'Not found',
      zip: analysis.ezlynxData?.client_zip || 'Not found',
      country: 'United States',
      industries: analysis.industry ? [analysis.industry] : ['Policy Audit'],
      hasActiveCoverage: true,
      knowsPremium: !!analysis.premiumAmount,
      hasDeclPage: true,
      contactName: analysis.uplinkData?.client_name || details.name || analysis.insuredName || 'Insured',
      contactEmail: analysis.contactEmail || details.email || '',
      contactPhone: analysis.contactPhone || '',
      sourcePolicyId: analysis.id,
      sourceFileData: analysis.fileData,
      extractedCoverage: analysis.summary
    };

    handleNewLead(autoLead);
  };

  const handleNewLead = async (lead: QuoteRequest) => {
    setAllLeads(prev => {
      const filtered = prev.filter(l => l.id !== lead.id);
      return [lead, ...filtered];
    });
    Promise.allSettled([
      storage.saveLead(lead),
      bossServer.upstream('lead', lead)
    ]);
  };

  const handleNewPremiumRequest = async (request: PremiumRequest) => {
    await storage.savePremiumRequest(request);
    setPremiumRequests(prev => [request, ...prev]);
  };

  const handleDeletePolicy = async (id: string) => {
    const policyToRecycle = allPolicies.find(p => p.id === id);
    if (policyToRecycle) {
      await storage.moveToRecyclePolicy(policyToRecycle);
      setAllPolicies(prev => prev.filter(p => p.id !== id));
      setRecycledPolicies(prev => [policyToRecycle, ...prev]);
    }
  };

  const handleRestorePolicy = async (id: string) => {
    const policyToRestore = recycledPolicies.find(p => p.id === id);
    if (policyToRestore) {
      await storage.restoreFromRecyclePolicy(policyToRestore);
      setRecycledPolicies(prev => prev.filter(p => p.id !== id));
      setAllPolicies(prev => [policyToRestore, ...prev]);
    }
  };

  const handlePermanentDeletePolicy = async (id: string) => {
    await storage.permanentDeletePolicy(id);
    setRecycledPolicies(prev => prev.filter(p => p.id !== id));
  };

  const handleDeleteLead = async (id: string) => {
    const leadToRecycle = allLeads.find(l => l.id === id);
    if (leadToRecycle) {
      await storage.moveToRecycle(leadToRecycle);
      setAllLeads(prev => prev.filter(l => l.id !== id));
      setRecycledLeads(prev => [leadToRecycle, ...prev]);
    }
  };

  const handleRestoreLead = async (id: string) => {
    const leadToRestore = recycledLeads.find(l => l.id === id);
    if (leadToRestore) {
      await storage.restoreFromRecycle(leadToRestore);
      setRecycledLeads(prev => prev.filter(l => l.id !== id));
      setAllLeads(prev => [leadToRestore, ...prev]);
    }
  };

  const handlePermanentDeleteLead = async (id: string) => {
    await storage.permanentDeleteLead(id);
    setRecycledLeads(prev => prev.filter(l => l.id !== id));
  };

  const handleDeletePremiumRequest = async (id: string) => {
    await storage.deletePremiumRequest(id);
    setPremiumRequests(prev => prev.filter(req => req.id !== id));
  };

  const handleStatusChange = async (id: string, status: QuoteRequest['status']) => {
    const lead = allLeads.find(l => l.id === id);
    if (lead) {
      const updated = { ...lead, status };
      await storage.saveLead(updated);
      setAllLeads(prev => prev.map(l => l.id === id ? updated : l));
      await bossServer.upstream('lead', updated);
    }
  };

  const handleImport = async (json: string) => {
    await storage.importBackup(json);
    const p = await storage.getPolicies();
    const l = await storage.getLeads();
    const rl = await storage.getRecycledLeads();
    const rp = await storage.getRecycledPolicies();
    const pr = await storage.getPremiumRequests();
    setAllPolicies(p);
    setAllLeads(l);
    setRecycledLeads(rl);
    setRecycledPolicies(rp);
    setPremiumRequests(pr);
  };

  return (
    <HashRouter>
      <div className="min-h-screen bg-transparent text-white border-none">
        {!isEmbedded && (
          <Header 
            isAdmin={isAdmin} 
            setIsAdmin={setIsAdmin} 
            onOpenWizard={() => { setCurrentAnalysis(null); setShowWizard(true); }} 
            onGoHome={handleGoHome}
          />
        )}

        <main className={`container mx-auto px-4 max-w-6xl bg-transparent ${isEmbedded ? 'py-0' : 'py-8'}`}>
          <Routes>
            <Route path="/" element={
              <MainView 
                isUnlocked={isUnlocked}
                onUnlock={handleUnlock}
                showWizard={showWizard}
                setShowWizard={setShowWizard}
                allPolicies={allPolicies}
                currentAnalysis={currentAnalysis}
                handleNewAnalysis={handleNewAnalysis}
                handleNewLead={handleNewLead}
                handleNewPremiumRequest={handleNewPremiumRequest}
                setCurrentAnalysis={setCurrentAnalysis}
                onReset={handleNewSession}
                auditCount={auditCount}
                isAdmin={isAdmin}
              />
            } />

            <Route path="/admin" element={
              isAdmin ? (
                <AdminDashboard 
                  policies={allPolicies} 
                  leads={allLeads}
                  recycledLeads={recycledLeads}
                  recycledPolicies={recycledPolicies}
                  premiumRequests={premiumRequests}
                  onDeletePolicy={handleDeletePolicy}
                  onRestorePolicy={handleRestorePolicy}
                  onPermanentDeletePolicy={handlePermanentDeletePolicy}
                  onDeleteLead={handleDeleteLead}
                  onRestoreLead={handleRestoreLead}
                  onPermanentDeleteLead={handlePermanentDeleteLead}
                  onDeletePremiumRequest={handleDeletePremiumRequest}
                  onStatusChange={handleStatusChange}
                  onImport={handleImport}
                  onViewPolicy={(p) => {
                    setCurrentAnalysis(p);
                    setShowWizard(false);
                    window.location.hash = '#/';
                  }}
                />
              ) : (
                <AdminLogin onLogin={() => setIsAdmin(true)} />
              )
            } />
          </Routes>
        </main>

        {!isEmbedded && (
          <footer className="py-12 border-none text-center text-gray-500 text-sm bg-transparent">
            <p>© {new Date().getFullYear()} The Insurance Boss Authority Terminal.</p>
          </footer>
        )}
      </div>
    </HashRouter>
  );
};

