          ${hasApiKey && !isUploading ? 'cursor-pointer hover:bg-white/[0.02] active:scale-[0.99] border-white/20' : 'opacity-80 cursor-default'}
          ${!hasApiKey ? 'grayscale opacity-50' : ''}
