            <span className={`font-black text-[10px] tracking-[0.3em] uppercase ${step === 'access' ? 'text-red-600' : 'text-yellow-400'}`}>
              {step === 'access' ? 'Status: Restricted' : 'Status: Identity Capture'}
            </span>
          </div>
          <button onClick={() => navigate('/admin')} className="text-[10px] font-black text-gray-600 hover:text-white uppercase tracking-widest transition-colors">
