import React, { useState, useRef, useEffect } from 'react';
import { analyzePolicy, calculateFileHash } from '../services/geminiService';
import { PolicyAnalysis, PremiumRequest } from '../types';

interface UploadSectionProps {
  onAnalysisComplete: (analysis: PolicyAnalysis, details: { name: string; email: string; phone: string }) => void;
  existingPolicies: PolicyAnalysis[];
  onOpenWizard: () => void;
  onPremiumRequest: (request: PremiumRequest) => void;
  auditCount: number;
}

const UploadSection: React.FC<UploadSectionProps> = ({ onAnalysisComplete, existingPolicies, onOpenWizard, onPremiumRequest, auditCount }) => {
  const [isUploading, setIsUploading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [hasApiKey, setHasApiKey] = useState(true);

  // Lead Capture State
  const [fullName, setFullName] = useState('');
  const [email, setEmail] = useState('');
  const [phone, setPhone] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const progressIntervalRef = useRef<number | null>(null);
  const abortControllerRef = useRef<AbortController | null>(null);

  useEffect(() => {
    // Check if API key is available on mount
    if (!process.env.API_KEY || process.env.API_KEY === '') {
      setHasApiKey(false);
    }
    return () => {
      if (progressIntervalRef.current) clearInterval(progressIntervalRef.current);
    };
  }, []);

  const isFormValid = () => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return (
      fullName.trim().length >= 2 &&
      emailRegex.test(email) &&
      phone.replace(/\D/g, '').length >= 10
    );
  };

  const handleStop = () => {
    if (progressIntervalRef.current) clearInterval(progressIntervalRef.current);
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }
    setIsUploading(false);
    setProgress(0);
  };

  const startProgressSimulation = (isFastTrack: boolean = false) => {
    setProgress(0);
    if (progressIntervalRef.current) clearInterval(progressIntervalRef.current);

    const intervalSpeed = isFastTrack ? 10 : 40; 

    progressIntervalRef.current = window.setInterval(() => {
      setProgress(prev => {
        if (prev >= 98.5) {
          return 98.5;
        }

        let increment = 0;
        if (isFastTrack) {
          increment = 20;
        } else {
          if (prev < 30) increment = 4;
          else if (prev < 65) increment = 1.2;
          else if (prev < 90) increment = 0.4;
          else increment = 0.05;
        }

        return Math.min(prev + increment, 98.5);
      });
    }, intervalSpeed);
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!hasApiKey) return;

    setIsUploading(true);
    startProgressSimulation();
    abortControllerRef.current = new AbortController();

    try {
      const userDetails = { name: fullName, email, phone };

      const base64Data = await new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onloadend = () => resolve((reader.result as string).split(',')[1]);
        reader.onerror = () => reject(new Error("Failed to read document stream."));
        reader.readAsDataURL(file);
      });

      const fileHash = await calculateFileHash(base64Data);
      const existingMatch = existingPolicies.find(p => p.fileHash === fileHash);

      let analysis: PolicyAnalysis;

      if (existingMatch) {
        analysis = existingMatch;
        startProgressSimulation(true); 
        await new Promise(r => setTimeout(r, 600)); 
      } else {
        // AI Analysis now includes mandatory literal user details for the backgrounded Zapier uplink
        analysis = await analyzePolicy(file, userDetails, abortControllerRef.current.signal);
      }

      if (progressIntervalRef.current) clearInterval(progressIntervalRef.current);
      setProgress(100);

      setTimeout(() => {
        onAnalysisComplete(analysis, userDetails);
        setIsUploading(false);
        setProgress(0);
      }, 400);

    } catch (err: any) {
      if (err.name === 'AbortError') return;
      console.error("Technical Audit Failure:", err);
      if (progressIntervalRef.current) clearInterval(progressIntervalRef.current);
      setIsUploading(false);
      setProgress(0);
      alert(`AUDIT SYSTEM FAILURE: ${err.message}`);
    } finally {
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  return (
    <div className="flex flex-col items-center justify-center text-center py-4 px-4 bg-transparent max-w-5xl mx-auto animate-in fade-in duration-1000">

      <div className="mb-12 space-y-4">
        <h1 className="text-6xl md:text-8xl font-black leading-[1.0] tracking-tighter text-white uppercase">
          Policy <br />
          <span className="text-yellow-400">Terminal</span>
        </h1>
        <p className="text-gray-400 text-lg md:text-xl font-bold max-w-2xl mx-auto leading-tight opacity-90">
          Provide your credentials to unlock the audit engine. <br />
          <span className="text-yellow-400">Gaps don't wait. Neither should you.</span>
        </p>
      </div>

      <div className="w-full max-w-4xl grid grid-cols-1 lg:grid-cols-2 gap-8 items-start">

        {/* LEAD CAPTURE FORM */}
        <div className="bg-[#0a0a0a] border border-white/10 rounded-[3rem] p-8 md:p-10 shadow-2xl text-left space-y-8 animate-in slide-in-from-left-4">
          <div className="space-y-2">
            <h3 className="text-xl font-black text-white uppercase tracking-tight">Identity Capture</h3>
            <p className="text-xs text-gray-500 font-bold uppercase tracking-widest">Mandatory for boss authorization</p>
          </div>

          <div className="space-y-5">
            <div className="space-y-1.5">
              <label className="text-[9px] font-black text-gray-500 uppercase tracking-widest px-1">Full Name</label>
              <input 
                type="text" 
                value={fullName}
                onChange={e => setFullName(e.target.value)}
                placeholder="Ex: John Boss"
                className="w-full bg-white/5 border border-white/10 rounded-2xl px-5 py-4 text-sm font-bold text-white focus:outline-none focus:border-yellow-400 transition-all placeholder:text-white/10"
              />
            </div>

            <div className="space-y-1.5">
              <label className="text-[9px] font-black text-gray-500 uppercase tracking-widest px-1">Email Address</label>
              <input 
                type="email" 
                value={email}
                onChange={e => setEmail(e.target.value)}
                placeholder="john@theboss.com"
                className="w-full bg-white/5 border border-white/10 rounded-2xl px-5 py-4 text-sm font-bold text-white focus:outline-none focus:border-yellow-400 transition-all placeholder:text-white/10"
              />
            </div>

            <div className="space-y-1.5">
              <label className="text-[9px] font-black text-gray-500 uppercase tracking-widest px-1">Work Phone</label>
              <input 
                type="tel" 
                value={phone}
                onChange={e => setPhone(e.target.value)}
                placeholder="(555) 000-0000"
                className="w-full bg-white/5 border border-white/10 rounded-2xl px-5 py-4 text-sm font-bold text-white focus:outline-none focus:border-yellow-400 transition-all placeholder:text-white/10"
              />
            </div>
          </div>

          <div className="pt-4 flex items-center gap-4">
             <div className={`w-3 h-3 rounded-full ${isFormValid() ? 'bg-green-500 shadow-[0_0_10px_#22c55e]' : 'bg-red-500'} transition-all`} />
             <span className="text-[10px] font-black uppercase tracking-[0.2em] text-gray-500">
               {isFormValid() ? 'Credentials Verified' : 'Awaiting Full Credentials'}
             </span>
          </div>
        </div>

        {/* UPLOAD TERMINAL */}
        <div 
          onClick={() => hasApiKey && !isUploading && isFormValid() && fileInputRef.current?.click()}
          className={`group h-full min-h-[400px] rounded-[3rem] border flex flex-col items-center justify-center p-12 transition-all relative overflow-hidden shadow-2xl
            ${!isFormValid() ? 'bg-black/40 border-white/5 opacity-50 cursor-not-allowed grayscale' : 'bg-[#0d0d0d] border-white/10 cursor-pointer hover:bg-white/[0.02] border-white/20 active:scale-[0.99]'}
            ${!hasApiKey ? 'grayscale opacity-50' : ''}
          `}
        >
          <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" accept="application/pdf" />

          {!isFormValid() && (
            <div className="absolute inset-0 z-20 flex flex-col items-center justify-center bg-black/40 backdrop-blur-[2px] p-8">
               <svg className="w-12 h-12 text-gray-600 mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
               </svg>
               <p className="text-[10px] font-black text-gray-500 uppercase tracking-widest text-center">Complete Identity Capture <br /> to Unlock Upload</p>
            </div>
          )}

          {isUploading ? (
            <div className="w-full space-y-10 flex flex-col items-center animate-in fade-in">
              <div className="relative w-24 h-24">
                <div className="absolute inset-0 border-[6px] border-yellow-400/10 rounded-full" />
                <div className="absolute inset-0 border-[6px] border-yellow-400 border-t-transparent rounded-full animate-spin" />
                <div className="absolute inset-0 flex items-center justify-center">
                  <span className="text-yellow-400 font-black text-xl">{Math.floor(progress)}%</span>
                </div>
              </div>
              <div className="w-full max-w-[200px] h-2 bg-white/5 rounded-full overflow-hidden border border-white/10">
                <div className="h-full bg-yellow-400 transition-all duration-300" style={{ width: `${progress}%` }} />
              </div>
              <button 
                onClick={(e) => { e.stopPropagation(); handleStop(); }}
                className="px-8 py-3 bg-white/5 border border-white/10 text-gray-500 hover:text-white text-[10px] font-black tracking-widest uppercase rounded-xl transition-all"
              >
                Abort
              </button>
            </div>
          ) : (
            <div className="space-y-8 flex flex-col items-center">
              <div className="bg-yellow-400/10 p-8 rounded-[2rem] border border-yellow-400/30 flex items-center justify-center shadow-2xl transition-transform duration-500 group-hover:scale-110">
                <svg className="w-10 h-10 text-yellow-400" fill="currentColor" viewBox="0 0 24 24">
                  <path d="M11 15h2v-4h3l-4-4-4 4h3v4z"/>
                  <path d="M20 18H4v-7H2v7c0 1.1.9 2 2 2h16c1.1 0 2-.9 2-2v-7h-2v7z"/>
                </svg>
              </div>
              <div className="space-y-2">
                <h3 className="text-4xl font-black tracking-tighter text-white">Upload Policy</h3>
                <p className="text-gray-500 text-xs font-bold uppercase tracking-widest">PDF Documents Only</p>
              </div>
            </div>
          )}
        </div>
      </div>

      <style>{`
        @keyframes shimmer {
          0% { transform: translateX(-100%); }
          100% { transform: translateX(200%); }
        }
      `}</style>
    </div>
  );
};

