    const jsonString = text.substring(startIndex + startTag.length, endIndex).trim();
    try {
      const extractedPayload: EZLynxPayload = JSON.parse(jsonString);

      // Merge lead form data, extracted literals, and binary file data
      const finalPayload: EZLynxPayload = {
        ...extractedPayload,
        full_name: userDetails.name,
        email: userDetails.email,
        phone: userDetails.phone,
        policy_file: fileData
      };

      console.log('Binary file data attached to webhook payload');

      fetch(ZAPIER_WEBHOOK_URL, {
