              </div>
            </div>
          )}
        </div>
      </div>

      {!isUploading && hasApiKey && isFormValid() && (
        <div className="mt-12 animate-in fade-in duration-700">
          <p className="text-[10px] font-black text-gray-600 uppercase tracking-[0.4em] mb-4">Official Submission Gateway</p>
